Ceviri.ekle("hy","olay",{
"OLAYLAR:1299-01:0":{"b": ["Օսմանյան բեյլիքի հիմնադրումը", "9f0b7c0a"], "d": ["Կայը ցեղից Օսման Ղազիի՝ Սոյութ-Դոմանիչի շրջակայքում ինքնուրույն գործել սկսելն ընդունվում է որպես Օսմանյան պետության հիմնադրման ավանդական դարձած սկզբնակետ. որոշ պատմաբաններ իրական շրջադարձային կետ են համարում 1302 թվականի Բաֆեոսի հաղթանակը։ Բյուզանդական սահմանամերձ շրջանում իր դիրքի շնորհիվ բեյլիքը ղազաթի (սրբազան պատերազմի) արշավանքներով արագ ուժ հավաքեց։ Սելջուկյան ժառանգության քայքայման այս պայմաններում Օսման Ղազին իր շուրջը համախմբեց ախիներին, ղազիներին և քոչվոր թուրքմեններին. Շեյխ Էդեբալիի հետ նրա հաստատած կապը համարվում է բեյլիքի հոգևոր լեգիտիմության հիմքը։ Նույն ամսաթվին միացած այլ վայրեր՝ Ինեգյոլ, Յարհիսար։", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Բուրսայի նվաճումը", "98c727fa"], "d": ["Տարիներ շարունակ շրջափակման մեջ պահված Բուրսան հանձնվեց Օրհան Ղազիին, որը ղեկավարում էր պաշարման վերջին փուլը. քաղաքը դարձավ բեյլիքի առաջին մեծ մայրաքաղաքը։ Ավանդվում է, որ նվաճման լուրը հասցվել է մահվան մահճում գտնվող Օսման Ղազիին. Օսման Ղազին իր կտակի համաձայն թաղվեց Բուրսայում։ Կարճ ժամանակում քաղաքը հարստացավ մզկիթներով, իմարեթներով և մեդրեսեներով և դարձավ վաղ օսմանյան քաղաքաշինության օրինակը։", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Իզնիկի նվաճումը", "a846a811"], "d": ["Անատոլիայում Բյուզանդիայի կարևորագույն կենտրոններից մեկը՝ Իզնիկը (Նիկիա), 1329 թվականի Պելեկանոնի հաղթանակից հետո կորցնելով դիմադրելու հույսը՝ հանձնվեց Օրհան Ղազիին։ Առաջին օսմանյան մեդրեսեն հիմնվեց այստեղ, և Դավուդ Կայսերիի նման գիտնականները սկսեցին դասավանդել. քաղաքը դարձավ վաղ շրջանի գիտական կենտրոնը։ Այա Սոֆիա եկեղեցին վերածվեց մզկիթի՝ դրսևորելով նվաճման ավանդույթի վաղ օրինակներից մեկը։", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Իզմիթի նվաճումը", "06a35035"], "d": ["Իզմիթի (Նիկոմեդիա) անկմամբ Անատոլիական ափին Բյուզանդիայի վերջին կարևոր ամրոցը ևս անցավ օսմանյան տիրապետության տակ. Ստամբուլի դիմացի ափը ներառյալ՝ ամբողջ Քոջաելի թերակղզին դարձավ օսմանյան հող։ Այսպիսով բեյլիքը, տիրելով Մարմարա ծովի հարավային և արևելյան ողջ ափին, նախապատրաստեց Ռումելի անցնելու հիմքը։", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Չիմփե ամրոցը — անցումը Ռումելի", "c2f0a07d"], "d": ["Օրհան Ղազիի որդի Սուլեյման փաշան 1352 թվականին որպես հենակետ ձեռք էր բերել Բյուզանդիայի քաղաքացիական պատերազմի ընթացքում տրված Չիմփե ամրոցը. 1354 թվականի մարտին Գելիբոլուն ավերած մեծ երկրաշարժից հետո լքված ամրոցներն արագորեն ամրացվեցին, և թերակղզին վերածվեց մշտական օսմանյան պլացդարմի։ Անատոլիայից բերված թուրքմեն բնակչության բնակեցմամբ ամրապնդված այս քայլը Եվրոպա մայրցամաքում օսմանցիների՝ ավելի քան 550 տարի տևած ներկայության սկիզբն է։", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Էդիրնեի նվաճումը", "2f54ebb0"], "d": ["Թրակիայի առանցքային քաղաք Էդիրնեի (Ադրիանապոլիս) գրավումը որոշեց բալկանյան նվաճումների գլխավոր հենակետն ու ուղղությունը. աղբյուրներում նվաճման ամսաթիվը վիճելի է՝ 1361-ից 1369 թվականների միջև։ Կարճ ժամանակ անց քաղաքը դարձավ մայրաքաղաք՝ ազդարարելով, որ պետության ծանրության կենտրոնը տեղափոխվել է Ռումելի. մինչև Կոստանդնուպոլսի նվաճումը այն շուրջ 90 տարի մնաց գահանիստ քաղաք։", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Մուրադ I-ը գահ բարձրացավ", "f8d48a26"], "d": ["Օրհան Ղազիի մահից հետո գահ բարձրացած Մուրադ I-ը (Հյուդավենդիգյար) իր 27-ամյա գահակալության ընթացքում պետությունը սահմանամերձ բեյլիքից հասցրեց կայսրության կմախքի։ Փենջիք համակարգով դրվեց ենիչերիական զորաբանակի (օջախի) հիմքը, տարածվեց թիմարային կարգը, հիմնվեց Ռումելիի բեյլերբեյությունը և ուժեղացվեց վեզիրության հաստատությունը։ Նրա օրոք բալկանյան նվաճումները դարձան համակարգված պետական քաղաքականություն։", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Կոսովոյի առաջին ճակատամարտը — Մուրադ I-ի նահատակությունը", "10b8ddc9"], "d": ["Կնյազ Լազարի գլխավորած բալկանյան դաշինքը վճռական պարտություն կրեց Կոսովոյի դաշտում. Սերբիան անցավ օսմանյան գերիշխանության տակ։ Մարտադաշտը շրջելիս Մուրադ I-ը սերբ ազնվական Միլոշ Օբիլիչի դաշույնի հարվածից նահատակվեց. նա մարտադաշտում մահացած միակ օսմանյան սուլթանն է։ Ռազմակայանում նրա փոխարեն գահ բարձրացվեց Յըլդըրըմ Բայազիդը. նրա եղբայր Յաքուբ Չելեբին խեղդամահ արվեց, և սա եղբայրասպանության գործելակերպի առաջին հայտնի օրինակներից էր։", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Նիկոպոլիսի հաղթանակը", "75716e96"], "d": ["Հունգարիայի թագավոր Սիգիզմունդի կոչով հավաքված խաչակրաց մեծ բանակը, որին միացել էին նաև ֆրանսիական և բուրգունդական ասպետները, Դանուբի ափին գտնվող Նիկոպոլիսի (Նիղբոլու) մոտ ծանր ջախջախում կրեց Յըլդըրըմ Բայազիդից։ Հաղթանակը վերջնականապես ամրապնդեց օսմանյան տիրապետությունը Բուլղարիայում. Եվրոպայում մեկ սերնդի ընթացքում խաչակրաց մեծ արշավանք չհաջողվեց կազմակերպել։", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Անկարայի ճակատամարտը — սկսվեց միջգահակալությունը (Ֆեթրեթի դարաշրջան)", "b4a99d96"], "d": ["Լենկ Թեմուրի բանակի դեմ Չուբուքի դաշտում կրած ծանր պարտության ժամանակ Յըլդըրըմ Բայազիդը գերի ընկավ և մի քանի ամիս անց մահացավ գերության մեջ։ Թեմուրը վերակենդանացրեց Անատոլիայի բեյլիքները. օսմանյան հողերը բաժան-բաժան եղան Բայազիդի որդիների միջև, և սկսվեց 11 տարի տևելիք գահակալական պայքարը (Ֆեթրեթի դարաշրջան)։ Պետության հիմնադրումից ի վեր ապրած ամենածանր ճգնաժամը եղած այս շրջանը օսմանյան հիշողության մեջ դրոշմեց կենտրոնացված կառույցի կարևորությունը։ Նույն ամսաթվին կորցրած այլ բնակավայրեր՝ Դաթչա, Մարմարիս, Ֆեթհիյե (Մակրի), Սյոքե, Քյոթահյա, Աֆյոն, Իսպարթա, Մանիսա, Այդըն, Դենիզլի, Մուղլա, Անթալիա, Կոնիա, Կարաման, Կեսարիա, Կաստամոնու, Բարթըն, Սաֆրանբոլու, Սամսուն, Սեբաստիա, Մալաթիա, Բեյշեհիր, Սիվրիհիսար, Քըրշեհիր, Չորում, Չանքըրը, Ենիշեհիր (Բուրսա), Ինեգյոլ, Այդոս ամրոց, Գեյվե, Քյոփրյուհիսար (Ենիշեհիր), Մարմարաջըք, Աքհիսար (Փամուքովա), Մեքեջե, Քեսթել, Ուլուբաթ, Հարմանքայա, Աքյազը, Իմրալը կղզի, Քանդըրա, Մուդանիա, Յալովա, Քարամյուրսել, Արմութլու, Գեմլիք (Կիոս), Սոյութ, Բիլեջիք, Էսքիշեհիր, Բուրսա, Իզնիկ, Իզմիթ, Բալըքեսիր, Չանաքքալե, Բերգամա, Ամասիա, Թոքաթ, Չորլու, Լյուլեբուրգազ, Մալքարա, Քեշան, Իփսալա, Քիլիթբահիր, Չիրմեն, Էսքի Զաղրա (Ստարա Զագորա), Թաթարփազարջըղը, Իհթիման, Քյոսթենդիլ, Պետրիչ, Նևրոկոփ (Գոցե Դելչև), Դրամա, Գելիբոլու, Չիմփե, Էդիրնե, Դիմոտիկա, Քըրքլարելի, Թեքիրդաղ, Ֆիլիպե, Սոֆիա, Նիշ, Վիդին, Տըռնովո, Վառնա, Շումեն, Սիլիստրա, Նիկոպոլիս, Ռուսչուկ, Սալոնիկ, Սերեզ, Կավալա, Սկոպյե, Մանաստիր, Օհրիդ, Ենիշեհիր (Լարիսա), Տիրհալա, Իզդին (Լամիա), Պլևնա, Գյումյուլջինե, Բիղա, Դոմանիչ, Քուլաջահիսար, Քարաջահիսար, Յարհիսար, Դիմբոս, Քիթե (Քեթե), Լեֆքե (Օսմանելի), Լեբլեբիջիհիսար, Քարաչեփյուշ, Քարաթիգին, Աբսու (Հիփսու), Ադրանոս (Օրհանելի), Պելեկանոն (Էսքիհիսար), Գեբզե, Հերեքե, Սամանդըրա, Քիրմաստի (Մ. Քեմալփաշա), Միհալիչ (Քարաջաբեյ), Քյոսթենջե, Գյոլյազը (Ապոլոնիա)։", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Չելեբի Մեհմեդը վերականգնեց միասնությունը", "03413dfd"], "d": ["Եղբայրների միջև վերջին հաշվեհարդարում Չամուրլուի մոտ Մուսա Չելեբիին հաղթած Մեհմեդ I-ը երկրի հողերը միավորեց մեկ իշխանության ներքո. այդ պատճառով նա համարվում է «պետության երկրորդ հիմնադիրը»։ Նրա գահակալության ընթացքում վերականգնվեց մաշված պետական կառույցը, հավասարակշռվեցին հարաբերությունները Անատոլիայի բեյլիքների հետ, իսկ Ռումելիում վարվեց զգուշավոր խաղաղության քաղաքականություն։ Նույն ամսաթվին քարտեզում Ֆեթրեթի միջանկյալ շրջանից օսմանյան կառավարման վերադարձած այլ բնակավայրեր՝ Աբսու (Հիփսու), Ադրանոս (Օրհանելի), Աքհիսար (Փամուքովա)։", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Շեյխ Բեդրեդդինի ապստամբությունը", "e0a072ca"], "d": ["Ֆեթրեթի դարաշրջանում ղազասքերի պաշտոն վարած մեծ իրավագետ և սուֆի Շեյխ Բեդրեդդինի շուրջ ձևավորված կրոնասոցիալական շարժումը բռնկվեց Քարաբուրունում Բյորքլյուջե Մուստաֆայի և Մանիսայում Թորլաք Քեմալի ապստամբությունների հետ միաժամանակ։ Ապստամբությունները ճնշվեցին արյունալի կերպով. Բեդրեդդինը ձերբակալվեց Դելիորմանում և մահապատժի ենթարկվեց Սերեզում։ Այս իրադարձությունը, որպես օսմանյան պատմության ամենավաղ խոշոր սոցիալ-մահդիական ապստամբությունը, խոր հետք թողեց գրականության և պատմագրության մեջ։", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Վառնայի հաղթանակը", "f739eedc"], "d": ["Սեգեդի պայմանագիրը խախտելով հարավ իջած հունգարա-լեհական խաչակիր բանակը Վառնայում ոչնչացրեց Մուրադ II-ը, որը, գահից հրաժարված լինելով, վերադարձել էր բանակի ղեկը. երիտասարդ թագավոր Վլադիսլավ III-ը զոհվեց մարտադաշտում։ Հաղթանակը վերացրեց Բալկաններում օսմանյան ներկայությունը վերացնելուն ուղղված արտաքին խոշոր միջամտության վերջին հնարավորությունը և ապահովեց Կոստանդնուպոլսի նվաճման տանող ճանապարհը։", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Կոսովոյի երկրորդ ճակատամարտը", "ebe0b662"], "d": ["Վառնայի վրեժը լուծել ցանկացող Յանոշ Հունյադիի բանակը երեք օր տևած համառ մարտում վճռական պարտություն կրեց Մուրադ II-ից։ Սա Բալկաններում օսմանցիների դեմ խաչակիրների ձեռնարկած վերջին մեծ դաշտային ճակատամարտն է. հաղթանակով Դանուբից հարավ օսմանյան տիրապետությունն այլևս հաստատվեց անշրջելիորեն։", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Կոստանդնուպոլսի նվաճումը", "583d5e3e"], "d": ["Հիսունչորս օր (1453 թ. ապրիլի 6 – մայիսի 29) տևած պաշարումից հետո մայիսի 29-ի առավոտյան պարիսպները հաղթահարած օսմանյան բանակը մտավ քաղաք. վերջին կայսր Կոստանդին XI-ը զոհվեց մարտերում, և 1100-ամյա Արևելյան Հռոմեական կայսրությունն անցավ պատմության գիրկը։ Երիտասարդ սուլթանն ստացավ «Ֆաթիհ» (Նվաճող) տիտղոսը, քաղաքը դարձրեց մայրաքաղաք և Այա Սոֆիան վերածեց մզկիթի. քաղաքը կարճ ժամանակում վերակենդանացվեց բնակեցմամբ և շինարարությամբ։ Ըստ TDV-ի՝ Սիլիվրին և Վիզեն վերջնականապես նվաճվել են միայն 1453 թվականին. ըստ TDV-ի «Լեմնոս» հոդվածի՝ կղզին նվաճումից անմիջապես հետո անցել է օսմանյան կառավարման տակ և խարաջ վճարելու պայմանով թողնվել Գատիլուզիո ընտանիքին։ Ատլասում Սիլիվրին, Վիզեն և Լեմնոսը այս օրվանից նշված են որպես Բյուզանդիայից Օսմանյան կայսրությանն անցած (Լեմնոսը՝ խարաջատու)։ Հսկա թնդանոթների ձուլումը, նավերի տեղափոխումը ցամաքով և պարիսպների առջև պաշարման դասավորությունը համարվում են այդ դարաշրջանի ռազմական ինժեներիայի գագաթնակետը։ Նվաճումը եվրոպական պատմագրության մեջ համարվում է միջնադարի ավարտը խորհրդանշող ամսաթվերից մեկը։", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Տրապիզոնի նվաճումը", "15f52403"], "d": ["Ֆաթիհի՝ բանակով և նավատորմով միաժամանակ վարած դժվարին սևծովյան արշավանքի արդյունքում Տրապիզոնի հունական կայսրությունը հանձնվեց. բյուզանդական աշխարհի՝ Անատոլիայում մնացած այս վերջին մնացորդի վերացմամբ Սև ծովի հարավային ափն ամբողջությամբ անցավ օսմանյան տիրապետության տակ։ Կոմնենոսների հարստությանը վերջ տալը ամրապնդեց Ֆաթիհի՝ «երկու ծովերի և երկու ցամաքների տիրակալ» լինելու հավակնությունը։ Նույն ամսաթվին միացած այլ վայրեր՝ Կիրասոն, Ռիզե։", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Սելևկիայի (Սիլիֆքե) վերջնական նվաճումը — Կարամանյանների վերջին դիմադրության կոտրումը", "d988bee4"], "d": ["Սիլիֆքեի ամրոցը 1472 թվականին մեկ անգամ հանձնվել էր Գեդիք Ահմեդ փաշային, սակայն նույն տարում Կարամանօղլու Կասըմ բեյը Միջերկրական ծովի խաչակիր նավատորմի օգնությամբ հետ էր վերցրել ամրոցը։ Օթլուքբելիի հաղթանակից հետո Ֆաթիհը իր որդուն և Գեդիք Ահմեդ փաշային հանձնարարեց վերջնականապես գրավել շրջանը. նախկին օսմանյան թնդանոթաձիգների օգնությամբ վառոդի պահեստը հրկիզվեց, և ամրոցն արագորեն ընկավ։ Այսպիսով կոտրվեց Կարամանյանների վերջին դիմադրությունը Թաշելի-Իչելի լեռներում. բեյլիքի վերացումն ավարտվելու էր 1474 թվականին։", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Օթլուքբելիի ճակատամարտը", "42c7194e"], "d": ["Արևելքում մեծ ուժ դարձած և Վենետիկի հետ դաշինք կնքած Ակ Կոյունլուների տիրակալ Ուզուն Հասանը Օթլուքբելիում ծանր պարտություն կրեց Ֆաթիհի՝ հրազենով զինված բանակից։ Հաղթանակը վերջնականապես ամրապնդեց օսմանյան գերակայությունը Անատոլիայում. այն նաև դասական բանակի դեմ թնդանոթ և հրացան կիրառող կենտրոնացված բանակի գերազանցության վաղ ապացույց դարձավ։ Ըստ TDV-ի «Գյումուշխանե» հոդվածի՝ քաղաքը 1467 թվականից ի վեր գտնվում էր Ակ Կոյունլուների տիրապետության տակ. այդ տիրապետությունն ավարտվեց Օթլուքբելիի պարտությամբ, և Գյումուշխանեն վերջնականապես անցավ օսմանյան տիրապետության տակ։", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Ղրիմի անցումը օսմանյան հովանավորության տակ", "44e3f7c8"], "d": ["Գեդիք Ահմեդ փաշայի հրամանատարությամբ նավատորմը նվաճեց Ղրիմի հարավային ափի քաղաքները, առաջին հերթին՝ ջենովացիներին պատկանող Կաֆան. այդ ափերը ուղղակիորեն դարձան օսմանյան սանջակ։ Իսկ Ղրիմի խանությունը Մենգլի Գիրեյի հետ դարձավ օսմանյան գերիշխանությունը ճանաչող արտոնյալ ենթակա պետություն և երեք դար շարունակ հյուսիսային քաղաքականության հիմնաքարը եղավ. Սև ծովն այլևս փաստացի վերածվեց օսմանյան ներքին ծովի։ Նույն ամսաթվին միացած այլ վայրեր՝ Բախչիսարայ, Կերչ, Ազով։", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Ֆաթիհի մահը — Ջեմ սուլթանի գործը", "190ecf01"], "d": ["Արշավանքի ճանապարհին Ֆաթիհի հանկարծակի մահից հետո գահ բարձրացավ Բայազիդ II-ը. նրա եղբայր Ջեմ սուլթանը, գահին հավակնելով, Բուրսայում իր անունով խուտբա կարդացնել տվեց և դրամ հատեց։ Պարտվելով՝ նա ապաստան գտավ նախ մամլուքների, ապա Ռոդոսի ասպետների մոտ. ասպետների և պապականության ձեռքում եվրոպական դիվանագիտության սակարկության խաղաքարտ դարձած Ջեմը 1495 թվականին մահացավ Նեապոլում։ Այս իրադարձությունը տասնհինգ տարի ստիպեց օսմանյան արտաքին քաղաքականությանը զգուշորեն գործել։", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Չալդրանի հաղթանակը", "fea64ebb"], "d": ["Անատոլիայում սեֆյան քարոզչության ստեղծած սպառնալիքն արմատախիլ անել ցանկացող Սուլթան Սելիմ Յավուզը Չալդրանի դաշտում թնդանոթների և հրացանների գերազանցությամբ ծանր պարտության մատնեց Շահ Իսմայիլի բանակը։ Նա մտավ Թավրիզ. Արևելյան և Հարավարևելյան Անատոլիան, ինչպես նաև Մոսուլ-Դիարբեքիր գիծը միացան օսմանյան տիրապետությանը։ Իդրիս Բիթլիսիի ջանքերով քուրդ բեյերի միանալը օսմանցիներին հիմնեց արևելյան սահմանի՝ դարեր տևելիք շրջանակը։", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Մարջ Դաբիքի հաղթանակը", "07d254d3"], "d": ["Մամլուքների բանակը Հալեպից հյուսիս գտնվող Մարջ Դաբիքում մի քանի ժամում ցրվեց. ծեր սուլթան Կանսուհ ալ-Ղաուրին մահացավ ճակատամարտի ընթացքում։ Հալեպի և Դամասկոսի դարպասները լայն բացած այս հաղթանակով Սիրիան, Լիբանանը և Պաղեստինը անցան օսմանյան կառավարման տակ. բացվեց Մամլուքների պետությանը վերջ տալիք եգիպտական արշավանքի ճանապարհը։", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ռիդանիե — Եգիպտոսի նվաճումը և խալիֆայությունը", "caf378d6"], "d": ["Սինայի անապատն արագ անցած օսմանյան բանակը Ռիդանիեում ճեղքեց Թումանբայի պաշտպանական գիծը և մտավ Կահիրե. դիմադրությունը շարունակող Թումանբայը ձերբակալվեց և մահապատժի ենթարկվեց, իսկ Մամլուքների պետությունն անցավ պատմության գիրկը։ Եգիպտոսը, Հիջազը և սրբազան քաղաքներն անցան օսմանյան կառավարման տակ. Աբբասյան խալիֆը և սրբազան մասունքները տեղափոխվեցին Ստամբուլ։ Խալիֆայության՝ օսմանյան հարստությանն անցնելով՝ սուլթանները ստանձնեցին իսլամական աշխարհի առաջնորդության հավակնությունը. Համեմունքների ճանապարհի վերահսկողությունը ևս մեծ եկամուտ ապահովեց կայսրությանը։ Նույն ամսաթվին միացած այլ վայրեր՝ Աքքա, Մաան, Սիդոն, Քերաք։", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Սուլթան Սուլեյման Քանունին գահ բարձրացավ", "f6512269"], "d": ["Յավուզի մահից հետո որպես միակ արու զավակ գահ բարձրացած Սուլեյման I-ի 46-ամյա գահակալությունը համարվում է կայսրության քաղաքական, ռազմական, իրավական և մշակութային գագաթնակետը։ Սովորութային իրավունքը համակարգած նրա կանունամեները նրան բերեցին «Քանունի» (Օրենսդիր) տիտղոսը. Արևմուտքում նրան կոչում էին «Հոյակապ» (Magnificent)։ Ճարտարապետ Սինանի կառույցները, դիվանական գրականության ոսկեդարը և նավատորմի գերակայությունը Միջերկրական ծովում այս դարաշրջանի խորհրդանիշներն են։", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Բելգրադի նվաճումը", "59ef5cec"], "d": ["Բելգրադը, որը Ֆաթիհը 1456 թվականին չէր կարողացել գրավել և որը համարվում էր «Կենտրոնական Եվրոպայի բանալին», Քանունիի առաջին արշավանքի ժամանակ ընկավ Դանուբի և Սավայի միախառնման վայրում տեղի ունեցած պաշարմամբ։ Այսպիսով փլուզվեց Հունգարիայի հարավային պաշտպանական գիծը. այս նվաճմամբ բացվեց Կենտրոնական Եվրոպայի գործողությունների դուռը, որը ձգվում էր մինչև հինգ տարի անց Մոհաչը և քսան տարի անց Բուդայի բռնակցումը։", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Ռոդոսի նվաճումը", "807bbb1e"], "d": ["Արևելյան Միջերկրածովի ծովային ուղիներին և ուխտագնացության երթուղուն սպառնացող Սուրբ Հովհաննեսի ասպետների հենակետ Ռոդոսը ամիսներ տևած արյունալի պաշարումից հետո հանձնվեց պայմանագրով. ասպետներին թույլատրվեց ազատ հեռանալ կղզուց (հետագայում նրանք հաստատվեցին Մալթայում)։ Ապահովվեց Անատոլիայի ափերի անվտանգությունը, և Ստամբուլ-Եգիպտոս ծովային գիծը անընդհատ կերպով անցավ օսմանյան վերահսկողության տակ։", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Մոհաչի դաշտային ճակատամարտը", "f3418b0d"], "d": ["Հունգարական բանակը Մոհաչի դաշտում մոտ երկու ժամվա ընթացքում ոչնչացվեց թնդանոթային կրակի և զորաշարժի գերազանցությամբ. թագավոր Լայոշ II-ը փախչելիս մահացավ ճահիճում։ Օսմանյան պատմության ամենաարագ տարած մեծ դաշտային ճակատամարտերից մեկը եղած Մոհաչը փաստացի վերջ տվեց Հունգարիայի անկախ թագավորությանը և Կենտրոնական Եվրոպայում բացեց օսմանա-հաբսբուրգյան մրցակցության դարաշրջանը։", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Վիեննայի առաջին պաշարումը", "dc49ea4f"], "d": ["Հաբսբուրգների՝ հունգարական գահին ձեռք մեկնելու դեմ ձեռնարկված արշավանքի ժամանակ օսմանյան բանակը պաշարեց Վիեննան. ծանր թնդանոթները ճանապարհին թողնելու, վաղ վրա հասած ձմռան և պարենավորման դժվարության պատճառով պաշարումը երեք շաբաթ անց վերացվեց։ Թեև քաղաքը չգրավվեց, օսմանյան ազդեցությունը Հունգարիայում պահպանվեց. Վիեննայի մատույցները նշեցին Կենտրոնական Եվրոպայում կայսրության լոգիստիկ հասանելիության սահմանը։", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Բաղդադի նվաճումը — երկու Իրաքների արշավանքը", "897092c3"], "d": ["«Երկու Իրաքների» (Արաբական Իրաք և Պարսկական Իրաք) դեմ ձեռնարկված արշավանքի ժամանակ նախ մտան Թավրիզ, ապա առանց կռվի՝ Բաղդադ. Աբբասյանների նախկին մայրաքաղաքի գրավումը օսմանյան տիրակալին մեծ հեղինակություն բերեց իսլամական աշխարհում։ Վերականգնվեց Իմամ Ազամ Աբու Հանիֆայի դամբարանը. Բաղդադի և Բասրայի միացմամբ օսմանյան հողերը հասան Պարսից ծոցին։ Նույն ամսաթվին միացած այլ վայրեր՝ Քիրքուկ, Քերբելա։", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Պրևեզայի ծովային հաղթանակը", "30dc0f97"], "d": ["Պապի նախաձեռնությամբ կազմված խաչակիր նավատորմը, թեև թվաքանակով գերազանց էր, Պրևեզայի մերձակա ջրերում ցրվեց Բարբարոսայի՝ քամին և ափը հմտորեն օգտագործող մարտավարությամբ. Անդրեա Դորիան լքեց մարտադաշտը։ Հաղթանակը Միջերկրական ծովում հաստատեց շուրջ 33 տարի տևելիք անվիճելի օսմանյան ծովային գերակայություն. թուրքական ծովագնացության ավանդույթում դա նավատորմի օրվա խորհրդանշական ամսաթիվն է։ Նույն ամսաթվին միացած այլ վայրեր՝ Ադեն, Բենդեր։", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Բուդայի բռնակցումը — Հունգարիան՝ օսմանյան էյալեթ", "db53b244"], "d": ["Բուդայի՝ Հաբսբուրգների պաշարման առիթով արշավանքի ելած Քանունին, քաղաքը փրկելուց հետո, Կենտրոնական Հունգարիան անմիջականորեն ներառեց օսմանյան կառավարման մեջ և հիմնեց Բուդայի բեյլերբեյությունը. իսկ Տրանսիլվանիան դարձավ Օսմանյան պետությանը ենթակա ինքնավար իշխանապետություն։ Հունգարիայի՝ երեք մասի բաժանված այս կարգը տևեց շուրջ 150 տարի և կազմեց օսմանյան մշտական կառավարման կմախքը Կենտրոնական Եվրոպայում։", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Ամասիայի պայմանագիրը", "a5afe0d1"], "d": ["Սա տարիներ տևած օսմանա-սեֆյան պատերազմներին վերջ դրած առաջին պաշտոնական հաշտության պայմանագիրն է։ Բաղդադը և Իրաքը մնացին օսմանցիներին, Արևելյան Անատոլիայի սահմանն առաջին անգամ փոխադարձաբար ճանաչվեց. Սեֆյանները պարտավորվեցին դադարեցնել շիայական քարոզչությունը օսմանյան երկրում, իսկ օսմանցիները՝ ապահովել իրանցի ուխտավորների անցման անվտանգությունը։ Պայմանագիրը դարձավ երկու պետությունների հարաբերությունների իրավական շրջանակի առաջին օրինակը։", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Սիգետվար — Քանունիի մահը", "e2917ed2"], "d": ["72-ամյա Քանունին իր տասներեքերորդ արշավանքի ժամանակ պաշարած Սիգետվարի ամրոցի անկումից մի քանի ժամ առաջ մահացավ իր վրանում. Սոքոլլու Մեհմեդ փաշան, որպեսզի բանակը չցրվի, շաբաթներ շարունակ թաքցրեց մահը։ Ամրոցը գրավվեց, սակայն պետությունը կորցրել էր ամենաերկարատև գահակալությամբ և ամենափառահեղ փադիշահին. գահ բարձրացավ նրա որդի Սելիմ II-ը, և պետության կառավարման մեջ սկսեց աճել մեծ վեզիրների կշիռը։", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Կիպրոսի նվաճումը", "e364a2b3"], "d": ["1570 թվականին վենետիկյան կառավարման տակ գտնվող Կիպրոսում ափհանում կատարվեց. Նիկոսիան արագորեն ընկավ, իսկ Ֆամագուստան հանձնվեց միայն տասնմեկամյա պաշարումից հետո՝ 1571 թվականի օգոստոսին։ Արևելյան Միջերկրածովի առևտրի և ուխտագնացության ուղիների անվտանգության տեսանկյունից վճռորոշ կղզին կազմակերպվեց որպես բեյլերբեյություն, և Անատոլիայից բնակչություն բնակեցվեց. նվաճումը նաև դարձավ դեպի Լեպանտո տանող խաչակրաց մեծ դաշինքի պատրվակը։", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Լեպանտոյի (Ինեբահթը) պարտությունը", "6a1d44a9"], "d": ["Կիպրոսի նվաճումից հետո միավորված խաչակիր նավատորմը Լեպանտոյի ծոցում բռնեց օսմանյան նավատորմը և ոչնչացրեց դրա մեծ մասը. կապուդան փաշա Մյուեզզինզադե Ալի փաշան նահատակվեց, փրկվեց միայն Ուլուջ Ալիի նավախումբը։ Աղետից հետո մեծ վեզիր Սոքոլլու Մեհմեդ փաշան Ուլուջ Ալի փաշային նշանակեց կապուդան փաշա, հանձնարարեց նրան հավաքել ցրված նավատորմը և Ստամբուլից մինչև Ալանիա բոլոր նավաշինարաններում սկսեց նոր նավատորմի կառուցումը. սակայն Միջերկրական ծովում բացարձակ գերակայությունը հոգեբանորեն խարխլվել էր։", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Կերեստեշի (Հաչովայի) դաշտային ճակատամարտը", "da308ec5"], "d": ["Երկարատև պատերազմի (1593–1606) ամենամեծ դաշտային ճակատամարտում Մեհմեդ III-ի անձամբ գլխավորած բանակը, հասնելով ցրվելու եզրին, Հոջա Սադեդդին էֆենդիի հորդորով վերախմբվեց և ջախջախեց Հաբսբուրգների բանակը։ Այն համարվում է օսմանցիների տարած վերջին մեծ դասական դաշտային ճակատամարտը. սակայն այն, որ չփոխեց պատերազմի ընդհանուր ընթացքը, դիտվեց նաև որպես ռազմական համակարգի մաշվածության նշան։", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Ժիտվատորոկի պայմանագիրը", "39c01142"], "d": ["Տասներեքամյա հյուծիչ պատերազմին վերջ դրած պայմանագրով հաբսբուրգյան տիրակալն առաջին անգամ «Հռոմեական կայսր» տիտղոսով համարվեց փադիշահին հավասար, և տարեկան խարաջը վերացվեց։ Հողային կորուստը գրեթե աննշան էր. սակայն դիվանագիտական լեզվի այս փոփոխությունը մեկնաբանվում է որպես Եվրոպայի նկատմամբ բացարձակ գերազանցության օսմանյան հավակնության ավարտի խորհրդանիշ։", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Կասրե Շիրինի պայմանագիրը", "c1acf3af"], "d": ["Մուրադ IV-ի կողմից Բաղդադը վերագրավելուց (1638) հետո ստորագրված պայմանագիրը վերջ դրեց ավելի քան հարյուր տարի տևած օսմանա-սեֆյան պատերազմներին։ Բաղդադը և Իրաքը վերջնականապես մնացին օսմանցիներին, Երևանը թողնվեց Սեֆյաններին. գծված սահմանագիծը, փոքր փոփոխություններով, դարձավ այսօրվա Թուրքիա-Իրան սահմանի հիմքը և համարվում է աշխարհի ամենաերկարակյաց սահմաններից մեկը։ Պայմանագիրը Բադրան, Ջասսանը, Մանդալին, Դերթանգը և Դերնեն թողեց օսմանցիներին. սահմանի վրա գտնվող Զենջիր ամրոցը պետք է քանդվեր, նրանից արևմուտք գտնվող գյուղերը մնալու էին օսմանցիներին, արևելքում գտնվողները՝ Իրանին։ Շահրազուրի մոտ գտնվող Զալիմ ամրոցի շրջակայքը և Քըզըլջա ամրոցը մնացին օսմանցիներին, իսկ Ավրոմանն ու Մեհրիվանը՝ Իրանին. Կոտուր, Մակու և Մաղազբերդ ամրոցները պետք է քանդվեին երկու կողմերի կողմից։", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Կրետեի նվաճումն ավարտվեց", "e0d85604"], "d": ["1645 թվականին սկսված Կրետեի պատերազմի վերջին արարը՝ Կանդիայի պաշարումը, ավարտվեց Ֆազըլ Ահմեդ փաշայի եռամյա վճռական գործողություններով. վենետիկյան հրամանատար Մորոզինին քաղաքը հանձնեց պայմանագրով։ Շուրջ քառորդ դար տևած պայքարը պատմության մեջ գրանցվեց որպես օսմանյան պատմության ամենաերկար պաշարումը. Արևելյան Միջերկրածովի վերջին մեծ լատինական ամրոցը ևս անցավ օսմանյան կառավարման տակ։ Կղզու հյուսիսային ափի երեք փոքր ժայռոտ ամրոցները՝ Սուդան, Սպինալոնգան և Գրամվուսան, դեռ մնացին Վենետիկին. քանի որ դրանք կառուցված են առանձին կղզյակների վրա, քարտեզում հնարավոր չէ դրանք ցույց տալ Կրետեի մնացած մասից առանձին։", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Բուչաչի պայմանագիրը — ամենաընդարձակ սահմանները", "b17b6e5a"], "d": ["Լեհաստանի արշավանքում Կամենեցի նվաճումից հետո ստորագրված Բուչաչի պայմանագրով Պոդոլիան միացավ Օսմանյան պետությանը, իսկ Ուկրաինայի մի մասը վերցվեց հովանավորության տակ։ Այսպիսով կայսրությունը հասավ Եվրոպայում իր ամենաընդարձակ սահմաններին. այս կետը համարվում է ընդարձակման դարաշրջանի գագաթնակետը և միաժամանակ վերջին օղակը։", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Վիեննայի երկրորդ պաշարման ջախջախումը", "7d889252"], "d": ["Մերզիֆոնցի Կարա Մուստաֆա փաշայի՝ Վիեննայի երկու ամիս տևած պաշարումը Լեհաստանի թագավոր Յան Սոբեսկիի՝ Կալենբերգի բլուրներից հասցրած հանկարծակի հարվածով վերածվեց ջախջախման. բանակը նահանջեց՝ թողնելով իր գումակը, իսկ Մերզիֆոնցին մահապատժի ենթարկվեց Բելգրադում։ Հաղթանակից հետո կազմված Սրբազան լիգայի դեմ պատերազմը տևեց 16 տարի. օսմանյան պատմության մեջ մեծ անկման սկզբի պահ է համարվում այս ջախջախումը։", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Գրամվուսա ամրոցի նվաճումը — Կրետեում Վենետիկին մնացած ժայռոտ ամրոցներից մեկը", "3ddf9eeb"], "d": ["Թեև 1669 թվականին Կանդիայի հանձնմամբ Կրետեի նվաճումը մեծ մասամբ ավարտված է համարվում, կղզու հյուսիսարևմտյան ծայրի ժայռոտ կղզի-ամրոց Գրամվուսան ևս քսաներեք տարի մնաց Վենետիկի ձեռքում։ 1692 թվականին դրա գրավմամբ մաքրվեց Կրետեում վենետիկյան երեք մնացորդներից մեկը. իսկ Սուդան և Սպինալոնգան սպասելու էին 1715 թվականի Մորեայի արշավանքին։", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Կառլովիցի պայմանագիրը — առաջին մեծ հողային կորուստը", "8f7e2546"], "d": ["Սրբազան լիգայի դեմ տասնվեցամյա պատերազմներին վերջ դրած Կառլովիցի պայմանագրով Հունգարիան և Տրանսիլվանիան թողնվեցին Ավստրիային, Պոդոլիան՝ Լեհաստանին, Մորեան և Դալմաթիայի ափերը՝ Վենետիկին։ Օսմանյան պատմության մեջ առաջին անգամ այս ծավալի հողեր կորսվում էին բանակցությունների սեղանի շուրջ և մշտապես. պայմանագիրը համարվում է Եվրոպայի նկատմամբ կայսրության պաշտպանության անցման նոր դարաշրջանի սկզբնական փաստաթուղթը և նաև օսմանյան դիվանագիտության պատմության շրջադարձային կետն է։ Նույն օրն ատլասում ձեռքից ձեռք անցած բնակավայրեր՝ Կոստայնիցա և Յասենովաց (Օսմանյան պետությունից Հաբսբուրգներին. պայմանագրի տեքստը Castanoviz-ը թողնում է կայսեր ձեռքում, Յասենովացի հանձնման օրը աղբյուրում նշված չէ, գրվել է պայմանագրի օրը) և Պրևեզա (Վենետիկից Օսմանյան պետությանը. TDV karlofca՝ 24 Ռաջաբ 1110 / 1699 թվականի հունվարի 26-ին ստորագրված դրույթի համաձայն՝ Լեպանտոյի ծոցից հյուսիս Վենետիկի օկուպացրած վայրերը վերադարձվեցին)։ Ատլասը նաև Կոստայնիցան (Kostajnica) և Յասենովացը գրում է հաբսբուրգյան կողմում, Աջափնյա Ուկրաինայի Ումանը և Վիննիցան՝ Օսմանյան պետությունից Լեհաստանին (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia՝ 1672-99 թուրքական տիրապետություն), իսկ Դալմաթիայի Նադինը՝ Վենետիկին (բնակավայրին հատուկ հանձնման օրը աղբյուրում նշված չէ, գրվել է պայմանագրի օրը. Նադինի ժամանակաշրջանի ծայրակետերն աղբյուրով չեն հաստատվել՝ հայտարարված մոտավորություն)։ Լեպանտոյի ծոցից հյուսիս գտնվող Վոնիցան ևս Վենետիկից վերադարձվում է օսմանցիներին (TDV karlofca). Դալմաթիայում Վրանան (Ուրանա) Վենետիկին մնացած վայրերի թվում է (ժամանակաշրջանի ծայրակետը չի հաստատվել՝ հայտարարված)։", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Պրուտի հաղթանակը", "2583572f"], "d": ["Պոլտավայի պարտությունից հետո Օսմանյան պետությունում ապաստանած Շվեդիայի թագավորի հարցի պատճառով ծագած պատերազմում ցար Պետրոս I-ի բանակը, Պրուտի ափին շրջապատվելով, ստիպված եղավ հանձնվել։ Ստորագրված պայմանագրով Ազովը հետ վերցվեց. իսկ բանակը չոչնչացնելը և ցարին ազատ արձակելը պատմության մեջ մտան որպես այդ օրից մինչ այսօր վիճարկվող որոշում։", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Սուդա և Սպինալոնգա ամրոցների նվաճումը — Կրետեում Վենետիկի վերջին հետքի ջնջումը", "7261f7ba"], "d": ["1692 թվականին Գրամվուսայի անկումից քսաներեք տարի անց Մորեայի արշավանքի կողմնային թևով նվաճվեցին նաև Կրետեում Վենետիկի վերջին երկու հենակետերը՝ Սուդա և Սպինալոնգա ամրոցները։ Այսպիսով 1645 թվականին սկսված Կրետեի նվաճումը քառասունվեց տարվա վերջում ավարտվեց մինչև կղզու վերջին սանտիմետրը։", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Պատրոնա Խալիլի ապստամբությունը", "100941a4"], "d": ["Իրանական ճակատում անհաջողությունը, հարկերը և պալատական շրջապատի շռայլության դեմ զայրույթը բաղնիքի սպասավոր Պատրոնա Խալիլի գլխավորությամբ վերածվեցին մեծ ապստամբության։ Մեծ վեզիր Իբրահիմ փաշան սպանվեց, Ահմեդ III-ը գահընկեց արվեց, և Կակաչների դարաշրջանն ավարտվեց. ապստամբների՝ ամիսներ շարունակ քաղաքում իշխելը ցայտուն կերպով ցույց տվեց կենտրոնական իշխանության փխրունությունը։", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Բելգրադի պայմանագիրը — Բելգրադի, Սմեդերևոյի և Հյուսիսային Սերբիայի հետգրավումը", "ba7f8e46"], "d": ["Ավստրիայի և Ռուսաստանի դեմ երկու ճակատով վարված պատերազմի (1736–1739) վերջում Բելգրադը և Հյուսիսային Սերբիան հետ վերցվեցին. Ռուսաստանը համաձայնեց ապառազմականացնել Ազովը և Սև ծովում նավատորմ չպահել։ 18-րդ դարի օսմանյան դիվանագիտության և բանակի վերջին մեծ հաջողությունը համարվող պայմանագիրը կայսրությանը պարգևեց քառորդ դարի խաղաղության շրջան։ Նույն օրն ատլասում Ավստրիայից օսմանցիներին վերադարձած այլ բնակավայրեր՝ Հիսարջըք (Գրոցկա) (Բելգրադի ավագ կենտրոնի շղթան. TDV belgrad), Կրայովա (Craiova), Ռիմնիկ (Râmnicu Vâlcea) և Թուռնու Սևերին (Փոքր Վալախիայի վերադարձը օսմանցիներին՝ Վալախիայի վասալությանը)։ Սավայի շերտի Բոսնիական Բրոդը (Bosanski Brod) և Բոսնիական Դուբիցան (Bosanska Dubica) ատլասում օսմանցիներին են վերադառնում 1739 թվականի սեպտեմբերի 28-ին (TDV bosna-hersek; TDV mahmud-i--osmanli՝ 28 սեպտեմբերի 1739)։ Փոքր Վալախիայում Տիրգու Ժիուն ևս նույն օրը վերադառնում է օսմանցիներին։", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Չեշմեի հարձակումը", "840b30bd"], "d": ["Անգլիացիների աջակցությամբ Միջերկրական ծով դուրս եկած ռուսական նավատորմը հրկիզող նավերով հարձակվեց Չեշմեի նավահանգստում ապաստանած օսմանյան նավատորմի վրա և գրեթե ամբողջությամբ այրեց այն։ Ռուսաստանն առաջին անգամ հանդես եկավ Միջերկրական ծովում որպես մեծ ծովային ուժ. աղետը դարձավ 1774 թվականի Քյուչուկ Կայնարջային տանող պատերազմի ճակատագիրը որոշած հարվածներից մեկը և ակնհայտ դարձրեց նավատորմի արմատական բարեփոխման անհրաժեշտությունը։", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Քյուչուկ Կայնարջայի պայմանագիրը", "2776dcdb"], "d": ["1768–1774 թվականների պատերազմին վերջ դրած և օսմանյան պատմության ամենածանր պայմանագրերից համարվող Քյուչուկ Կայնարջայով Ղրիմի խանությանը «անկախություն» տրվեց. փաստացի ստեղծվեց ռուսական ազդեցության գոտի։ Ռուսաստանը հաստատվեց Սև ծովի ափին, ձեռք բերեց իր առևտրական նավերի՝ նեղուցներով անցնելու իրավունք և մշտական դեսպանություն Ստամբուլում. ուղղափառ հպատակների նկատմամբ հովանավորության անորոշ դրույթը կիսաբացեց հաջորդ դարի միջամտությունների պատրվակների դուռը։ Առաջին անգամ մուսուլման բնակչությամբ հող դուրս էր բերվում օսմանյան տիրապետությունից։", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Ղրիմի բռնակցումը Ռուսաստանին", "bdf6faa8"], "d": ["Քյուչուկ Կայնարջայով ստեղծված «անկախ» Ղրիմը, վերջին խան Շահին Գիրեյի ժամանակվա խառնակությունները պատրվակ դարձնելով, Եկատերինա II-ի մանիֆեստով բռնակցվեց Ռուսաստանին։ Օսմանա-ղրիմյան երեք դարի գործընկերությունն ավարտվեց. հյուսիսային տափաստանների կորուստը վերացրեց Ստամբուլի պաշտպանության խորությունը և սկիզբ դրեց տասնյակ հազարավոր Ղրիմի թաթարների՝ օսմանյան հողեր գաղթի առաջին մեծ ալիքին։ Այս օրը Ղրիմ թերակղզին (Ալուշտա, Կաֆա, Սուդակ, Յալթա, Բալակլավա, Ինկերման, Մանգուպ, Արաբաթ) միացավ Ռուսաստանին. Թամանը և Կուբանը նույն բռնակցմամբ ևս անցան Ռուսաստանին (TDV Kırım՝ 8 ապրիլի 1783 հուլյան = 19 ապրիլի գրիգորյան)։", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Սելիմ III-ը և Նիզամ-ը Ջեդիդը", "d53aec21"], "d": ["Պատերազմի թեժ պահին գահ բարձրացած Սելիմ III-ը, տեսնելով, որ պարտությունները կառուցվածքային բնույթ ունեն, «Նիզամ-ը Ջեդիդ» (Նոր կարգ) անունով սկսեց բարեփոխումների ընդգրկուն ծրագիր՝ եվրոպական ձևով մարզված նոր բանակ, այն ֆինանսավորող առանձին գանձարան (Իրադ-ը Ջեդիդ), ինժեներական դպրոցների ուժեղացում և առաջին մշտական դեսպանությունները եվրոպական մայրաքաղաքներում։ Ծրագիրը համարվում է ժամանակակից թուրքական բարեփոխումների ավանդույթի սկիզբը. սակայն զորաբանակների (օջախների) և այանների դիմադրության պատճառով այն տապալվելու էր 1807 թվականին։", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Մալթայի ասպետների վերացումը — ֆրանսիական նավատորմի կանգառը ճանապարհին", "d62f901d"], "d": ["Եգիպտոս մեկնող ֆրանսիական նավատորմն իր ճանապարհին կանգ առավ Մալթայում. Սուրբ Հովհաննեսի (Մալթայի) ասպետները, առանց մեծ դիմադրության, հանձնեցին կղզին։ Այսպիսով վերացավ 1522 թվականին Ռոդոսից վտարված և այստեղ հաստատված ասպետական միաբանության վերջին ամրոցը։ Երկու տարի անց Մալթան անցնելու էր Անգլիայի ձեռքը, իսկ Նապոլեոնը կղզուց ուղղակիորեն շարժվելու էր դեպի Ալեքսանդրիա։", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Նապոլեոնի կողմից Եգիպտոսի գրավումը (օկուպացիան)", "93fede5f"], "d": ["Գեներալ Բոնապարտի բանակը, ափհանվելով Ալեքսանդրիայում, օկուպացրեց Եգիպտոսը. Անգլիայի՝ դեպի Հնդկաստան ճանապարհը թիրախ դարձրած այս արշավանքը եվրոպական ուժի առաջին ուղղակի հարձակումն էր օսմանյան կենտրոնական հողերի վրա։ Նելսոնի՝ Աբուկիրի հարձակումը և Ջեզզար Ահմեդ փաշայի՝ Աքքայի պաշտպանությունը կոտրեցին ֆրանսիական առաջխաղացումը. օկուպացիան ավարտվեց 1801 թվականին, բայց նրա թողած դատարկության մեջ սկսվեցին Կավալացի Մուհամմեդ Ալի փաշայի վերելքը և «Արևելյան հարցի» դարաշրջանը։", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Սենեդ-ի Իթթիֆաք (Դաշինքի ակտ)", "cce49ef5"], "d": ["Մահմուդ II-ին գահ բարձրացրած Ռուսչուկի այան Ալեմդար Մուստաֆա փաշայի նախաձեռնությամբ պալատի և գավառի հզոր այան ընտանիքների միջև ստորագրված փաստաթուղթ. այանները պարտավորվում էին հավատարիմ մնալ փադիշահին և զորքով աջակցել, իսկ պետությունը ճանաչում էր նրանց գոյությունն ու իրավունքները։ Քանի որ սա օսմանյան պատմության մեջ փադիշահի իշխանությունը փաստաթղթով սահմանափակելու առաջին օրինակն է, որոշ պատմաբաններ այն համարում են սահմանադրական ավանդույթի հեռավոր սկիզբը. գործնականում մի քանի ամսվա ընթացքում այն կորցրեց ուժը։", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Սկսվեց հունական ապստամբությունը", "a7293715"], "d": ["Ֆիլիկի Էթերիա կազմակերպության նախապատրաստած ապստամբությունը բռնկվեց նախ Վալախիայում, ապա իր հիմնական ուժով՝ Մորեայում. Թեփեդելենցի Ալի փաշայի հոգսով զբաղված պետությունը առաջին միջամտությունն ուշացրեց։ Եվրոպական հասարակական կարծիքում հույների հանդեպ ուժեղ համակրանքի (ֆիլհելլենիզմի) շնորհիվ ապստամբությունը կարճ ժամանակում վերածվեց միջազգային գործի. այսպես վառվեց ազգայնականության դարաշրջանում օսմանյան հողերում առաջին հաջող անկախության շարժման պատրույգը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Աթենք, Բալյաբադրա (Պատրաս), Իստեֆե (Թեբե), Լիվադիա, Էլևսիս (Ատտիկա), Միսսոլոնգի։", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Առաջին զինված ապստամբությունը Մորեայում", "77e6250f"], "d": ["Պրուտն անցնելուց հետո ապստամբությունը տարածվեց Մորեա. Կալավրիտայում (հուլյան 21 մարտի) սկսված զինված գործողությանը հաջորդեցին Պատրասի, Կալամատայի և Մանիի շարժումները. Մորեան կարճ ժամանակում վերածվեց համընդհանուր ապստամբության, և օսմանյան վարչությունը կորցրեց թերակղզու մեծ մասը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Աթենք, Բալյաբադրա (Պատրաս), Իստեֆե (Թեբե), Լիվադիա, Էլևսիս (Ատտիկա), Միսսոլոնգի։", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Վաքա-ի Խայրիյե — ենիչերիական զորաբանակի վերացումը", "08c9372a"], "d": ["Նորաստեղծ Էշքինջի զորաբանակի վարժանքների դեմ ապստամբած («կաթսան շրջած») ենիչերիները Մահմուդ II-ի նախապես պատրաստած հավատարիմ զորամասերի թնդանոթային կրակով ոչնչացվեցին Էթմեյդանիի իրենց զորանոցներում. զորաբանակը լուծարվեց իր բոլոր ճյուղերով և դրան կապված բեքթաշիական թեքքեներով։ «Բարեբեր իրադարձություն» նշանակող անունով պատմության մեջ մտած այս գործողությունը, վերացնելով չորս դարի հաստատությունը, ճանապարհ բացեց Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյե բանակի և կենտրոնացման հետագա բոլոր բարեփոխումների առաջ։", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Նավարինի հարձակումը", "ee579e7f"], "d": ["Հունական ապստամբությունը ճնշող օսմանա-եգիպտական նավատորմը Նավարինում այրվեց առանց պատերազմ հայտարարելու նավահանգիստ մտած անգլո-ֆրանս-ռուսական միացյալ նավախմբի կողմից. կորսվեցին մոտ վաթսուն նավ և հազարավոր նավաստիներ։ Եվրոպական դիվանագիտության մեջ որպես «դժբախտ դեպք» շրջանցված այս հարձակումը փաստացի երաշխավորեց Հունաստանի անկախությունը և ճանապարհ բացեց 1828–29 թվականների ռուս-թուրքական պատերազմի համար։", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Թանզիմաթի ֆերմանը", "5042ce7b"], "d": ["Գյուլհանեում ընթերցված Խաթթ-ը Հյումայունով առանց կրոնի խտրության բոլոր հպատակների կյանքի, գույքի և պատվի անվտանգությունը վերցվեց պետական երաշխիքի տակ. հռչակվեցին հարկերում արդարության, զինվորական ծառայության մեջ կարգուկանոնի և առանց դատաստանի պատիժ չսահմանելու սկզբունքները։ Մուստաֆա Ռեշիդ փաշայի ստեղծագործությունը եղած ֆերմանը համարվում է օսմանյան արդիականացման սահմանադրական բնույթի առաջին մեծ փաստաթուղթը և իր անունը տվել է «Թանզիմաթի դարաշրջան» (1839–1876) բարեփոխումների ժամանակաշրջանին. կառավարման, իրավունքի, կրթության և ֆինանսների արմատական վերակառուցումը իրականացվեց այս շրջանակում։", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Սկսվեց Ղրիմի պատերազմը", "3b9ca3c8"], "d": ["Սրբավայրերի հարցից և ուղղափառ հպատակների նկատմամբ Ռուսաստանի հովանավորության հավակնությունից սկիզբ առած ճգնաժամը Օսմանյան պետության պատերազմ հայտարարելով վերածվեց բացահայտ ընդհարման. Սինոպի հարձակումից հետո Անգլիան և Ֆրանսիան (ապա Պիեմոնտը) պատերազմի մեջ մտան օսմանցիների կողմում։ Դաշնակից բանակների՝ Ղրիմում ափհանվելով Սևաստոպոլը գրավելով պատերազմը հաղթական ավարտվեց 1856 թվականի Փարիզի պայմանագրով. սակայն պատերազմի տարիներին վերցված առաջին արտաքին պարտքը (1854) կայսրությանը ներքաշեց կես դար տևելիք ֆինանսական կախվածության պարույրի մեջ։", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Բարեփոխումների (Իսլահաթի) ֆերմանը", "78ff234d"], "d": ["Փարիզի հաշտության բանակցություններից առաջ հռչակված ֆերմանը, ընդլայնելով Թանզիմաթի սկզբունքները, ոչ մուսուլման հպատակներին ընձեռեց լայն հավասար իրավունքներ՝ ներառյալ պետական պաշտոն, զինվորական ծառայություն և դպրոց բացելը. վերակարգավորվեցին համայնքային կազմակերպությունները։ Դրանից հետո ստորագրված Փարիզի պայմանագրով Օսմանյան պետությունը պաշտոնապես ընդունվեց եվրոպական պետությունների իրավունքի ընտանիք, և նրա տարածքային ամբողջականությունը վերցվեց մեծ տերությունների համատեղ երաշխիքի տակ. այս երաշխիքը գործնականում դառնալու էր միջամտությունների նոր դուռ։", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Կանուն-ը Էսասի — Առաջին սահմանադրական շրջանը", "0fe052c1"], "d": ["Բալկանյան ճգնաժամը քննարկելու համար Ստամբուլում հավաքված միջազգային խորհրդաժողովի բացման օրը թնդանոթային համազարկերով հռչակվեց օսմանյան առաջին սահմանադրությունը. Միդհաթ փաշայի գլխավորած «Նոր օսմանցիների» շարժման ստեղծագործությունը եղած Կանուն-ը Էսասիով հիմնվեց երկպալատ խորհրդարան։ Մեբուսանների ժողովը (Meclis-i Meb'ûsan) բացվեց 1877 թվականի մարտին. սակայն Աբդուլ Համիդ II-ը, պատճառաբանելով «93 թվականի պատերազմը», 1878 թվականի փետրվարին անորոշ ժամկետով արձակեց ժողովը, և սահմանադրությունը երեսուն տարի մնաց կասեցված։", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["«93 թվականի պատերազմը» (1877–78 թվականների ռուս-թուրքական պատերազմ)", "5bd96af7"], "d": ["Քանի որ համընկնում էր ռումի 1293 թվականին՝ «93 թվականի պատերազմ» անվանված այս պատերազմում ռուսական բանակները հարձակվեցին երկու ճակատով. թեև Ղազի Օսման փաշայի՝ Պլևնայի պաշտպանությունը և Ահմեդ Մուխթար փաշայի կովկասյան մարտերը դարձան լեգենդար, ճակատը փլուզվեց, և ռուսները առաջացան մինչև Եշիլքյոյ (Սան Ստեֆանո)։ Պատերազմը սկիզբ դրեց Բալկաններից և Կովկասից Ստամբուլ ուղղված՝ մուսուլմանների գաղթի մեծ ալիքների, որոնց հետևանքները հասնում են մինչև այսօր. կայսրության ժողովրդագրական և ֆինանսական կառուցվածքը այլևս չվերադարձավ նախկին վիճակին։", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Բեռլինի պայմանագիրը", "47f76a49"], "d": ["Սան Ստեֆանոյի ստեղծած «Մեծ Բուլղարիան» մեծ տերությունների հավասարակշռության անունից վերանայած Բեռլինի վեհաժողովը, այնուամենայնիվ, թողեց ծանր պատկեր. Սերբիան, Չեռնոգորիան և Ռումինիան անկախացան. հիմնվեց Բուլղարիայի ինքնավար իշխանապետությունը. Բոսնիա և Հերցեգովինան թողնվեց ավստրիական օկուպացիային, Կիպրոսը՝ անգլիական կառավարմանը, Կարս-Արդահան-Բաթումը՝ Ռուսաստանին։ Ռումելիում հինգհարյուրամյա օսմանյան կարգը մեծ մասամբ քայքայվեց. «Արևելյան հարցը» դարձավ եվրոպական դիվանագիտության մշտական օրակարգ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ֆիլիպե, Վիդին, Տըռնովո, Վառնա, Շումեն, Սիլիստրա, Ռուսչուկ, Բուխարեստ, Յասսի, Քյոսթենջե։ Ռումինիան Բեսարաբիան Ռուսաստանին տալու դիմաց ստացավ Թուլչան (Tulcea) և Դոբրուջան. Հյուսիսային Դոբրուջայի Թուլչան, Բաբադաղը (Babadag), Մաչինը, Իսակչան (Isaccea), Հըրշովան (Hârșova) և Մանգալիան (Mangalia) անցան Ռումինիային։", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Թունիսի օկուպացիան և Օսմանյան պետական պարտքի վարչությունը (Դյույուն-ը Ումումիյե)", "c7e25598"], "d": ["Ֆրանսիան, պատրվակ դարձնելով Ալժիրի սահմանի դեպքերը, օկուպացրեց Թունիսը և Բարդոյի պայմանագրով վերցրեց իր հովանավորության տակ. Հյուսիսային Աֆրիկայում օսմանյան ներկայությունը սահմանափակվեց Տրիպոլիտանիայով։ Նույն տարում ընդունված Մուհառամի հրամանագրով սնանկացած արտաքին պարտքերի կառավարման համար հիմնվեց Պետական պարտքի վարչությունը, որտեղ ներկայացված էին պարտատերերը. աղը, ծխախոտը, մետաքսը և այլ հիմնական եկամուտներ ուղղակիորեն կապվեցին այս օտար վարչությանը, և ֆինանսական ինքնիշխանությունը ծանր կերպով սահմանափակվեց։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Քայրուան, Գաբես, Սֆաքս, Ջերբա (Djerba)։", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Եգիպտոսի անգլիական օկուպացիան", "f1269768"], "d": ["Եգիպտոսում ֆինանսական սնանկության և օտարերկրյա վերահսկողության դեմ բարձրացած Ուրաբի փաշայի շարժումը ճնշվեց Ալեքսանդրիայի ռմբակոծությունից հետո ափհանված անգլիական բանակի՝ Թել ալ-Քեբիրի հաղթանակով, և Կահիրեն օկուպացվեց։ Եգիպտոսը իրավաբանորեն շարունակեց կապված մնալ Օսմանյան պետությանը, սակայն փաստացի անցավ անգլիական կառավարման տակ. Սուեզի ջրանցքի վերահսկողությունը տեղավորվեց Բրիտանական կայսրության ռազմավարության կենտրոնում։", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Երկրորդ սահմանադրական շրջանի հռչակումը", "95ee2fd2"], "d": ["«Միություն և առաջադիմություն» կոմիտեին կապված սպաների՝ Մակեդոնիայում լեռներ բարձրանալով մեծացած շարժման դեմ Աբդուլ Համիդ II-ը կրկին ուժի մեջ դրեց Կանուն-ը Էսասին. «ազատության հռչակումը» դիմավորվեց խանդավառությամբ, և անցկացվեցին ընտրություններ։ Սակայն կայունությունը չեկավ. մարտի 31-ի դեպքը (1909 թվականի ապրիլ) ճնշելուց հետո Աբդուլ Համիդը գահընկեց արվեց. Բուլղարիայի անկախությունը, Բոսնիայի բռնակցումը և Կրետեի՝ դեպի Հունաստան թեքվելը ևս տեղի ունեցան այս խռովահույզ ամիսներին։", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Տրիպոլիտանիայի պատերազմը", "ed441994"], "d": ["Գաղութներ փնտրող Իտալիան պատերազմ հայտարարեց Օսմանյան պետության վերջին հյուսիսաֆրիկյան հողին՝ Տրիպոլիտանիային, և օկուպացրեց ափերը. քանի որ նավատորմ չունեցող պետությունը չկարողացավ կանոնավոր բանակ ուղարկել, երիտասարդ սպաներ, ինչպիսիք էին Մուստաֆա Քեմալը և Էնվեր բեյը, գաղտնի անցան շրջան և սանուսի ցեղերի հետ կազմակերպեցին արդյունավետ դիմադրություն։ Բալկանյան պատերազմի բռնկման պատճառով ստորագրված Ուշիի պայմանագրով (1912 թվականի հոկտեմբերի 18) Լիբիան թողնվեց Իտալիային. Իտալիան նաև օկուպացրեց Ռոդոսը և Դոդեկանեսը (Տասներկու կղզիները)։", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Լոնդոնի պայմանագիրը — Ռումելիի կորուստը", "f3f976df"], "d": ["Բալկանյան առաջին պատերազմին վերջ դրած Լոնդոնի պայմանագրով կորսվեցին Միդիա-Էնոս գծից արևմուտք գտնվող բոլոր հողերը և Էգեյան կղզիները. Ալբանիան անկախացավ։ Ավելի քան հինգ հարյուր տարի կայսրության ժողովրդագրական, տնտեսական և մշակութային ծանրության կենտրոնը եղած Ռումելիից մնալու էր միայն Արևելյան Թրակիան (Էդիրնեն հետ վերցվեց Բալկանյան երկրորդ պատերազմում). կորուստն արմատապես կոշտացրեց իթթիհադական կառավարության պատերազմի և բնակեցման քաղաքականությունը։ Միդիա-Էնոս գծից արևմուտք մնացած հետևյալ վայրերը ձեռքից դուրս եկան՝ Սկոպյե, Քյոփրյուլյու (Վելես), Իշտիպ (Štip), Ուստրումջա, Դոյրան, Գևգիլի (Gevgelija), Մանաստիր, Օհրիդ, Դեբրե (Dibra), Պրիզրեն, Պրիշտինա, Պեչ (Pejë), Ենիփազար (Novi Pazar), Կոսովոյի դաշտ (Kosovo Polje). Սերեզ, Դրամա, Կավալա, Պետրիչ, Նևրոկոփ, Իսքեչե, Գյումյուլջինե, Դեդեաղաչ, Դիմոտիկա, Չիրմեն, Ֆերեջիկ (Feres), Սոֆուլու (Soufli), Օրեստիադա (Կումչիֆթլիղի), Պրավիշտե (Eleftheroupoli), Stérna, Távri, Ումուր Ֆաքիհ (Fakia), Մալաք Դերվենթ (Lalkovo). Կրետեում՝ Խանիա, Կանդիա, Կրետե (Ռեսմո), Սիտիա (Sitia) և Իսֆաքիյե (Sfakia)։", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Մուտքը Առաջին համաշխարհային պատերազմ", "05a0252e"], "d": ["Անգլիացիներից փախած «Գյոբեն» և «Բրեսլաու» զրահանավերը, ներկայացվելով որպես գնված, ներս թողնվեցին Բոսֆոր, ինչը քայլ առ քայլ պետությանը տարավ Գերմանիայի կողմը. ծովակալ Սուշոնի հրամանատարությամբ նավատորմի կողմից ռուսական նավահանգիստների ռմբակոծումով (հոկտեմբերի 29) պատերազմը փաստացի սկսվեց, իսկ փոխադարձ հայտարարությունները եղան նոյեմբերի սկզբին։ Չնայած Մեծ ջիհադի (Cihâd-ı Ekber) հռչակմանը՝ սպասված ազդեցությունը չառաջացավ. կայսրությունը չորս տարի շարունակ Կովկասից Պաղեստին՝ հինգ առանձին ճակատներում, գոյության պատերազմի մեջ մտավ։", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Չանաքքալեի (Դարդանելի) հաղթանակը", "95d888e8"], "d": ["Ստամբուլը գցելու և Ռուսաստանի հետ կապ հաստատելու նպատակ ունեցող դաշնակից արմադան մարտի 18-ին ականապատ գծերի և ամրությունների կրակով ետ շպրտվեց նեղուցից. «Նուսրեթ» ականակիրի դրած ականային գիծը որոշեց մարտի ճակատագիրը։ Ապրիլին սկսված Գելիբոլուի ցամաքային գործողությունը ևս կանգնեցվեց Անաֆարթալարում և Ջոնքբայըրըում. դաշնակիցները 1916 թվականի հունվարին ամբողջությամբ դատարկեցին թերակղզին։ Փոխգնդապետ Մուստաֆա Քեմալի անունը լսելի դարձավ այս ճակատում. շուրջ քառորդ միլիոն նահատակների և կորուստների գնով տարած այս հաղթանակը համարվում է այն վայրը, որտեղ ծնվեցին Ազգային պայքարի կադրերն ու ոգին։", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Շերիֆ Հուսեյնի ապստամբությունը", "75f7c58c"], "d": ["Մեքքայի էմիր Շերիֆ Հուսեյնը, անգլիացիների հետ վարած գաղտնի նամակագրությունից հետո, ապստամբեց անկախ արաբական թագավորության խոստումով. Հիջազի երկաթուղին դարձավ հարձակումների թիրախ։ Թեև Ֆահրեդդին փաշայի՝ Մեդինայի լեգենդար պաշտպանությունը, որ շարունակվեց մինչև զինադադարից հետո, մնաց որպես դիմադրության խորհրդանիշ, ապստամբությունը, միանալով Պաղեստինի ճակատում անգլիական առաջխաղացմանը, արագացրեց արաբական վիլայեթներում օսմանյան տիրապետության քայքայումը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Խուրմա, Թուրաբա։", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Մուդրոսի զինադադարը", "9e87c767"], "d": ["Բուլղարիայի փլուզմամբ ճակատներն իրարից կտրված Օսմանյան պետությունը դուրս եկավ պատերազմից «Ագամեմնոն» զրահանավի վրա ստորագրված զինադադարով։ Նեղուցների բացումը և հատկապես 7-րդ հոդվածը, որը հնարավորություն էր տալիս գրավել անվտանգությանը սպառնացող վայրերը, կարճ ժամանակում դարձան փաստացի բաժանման իրավական քող. օկուպացվեցին Մոսուլը, Ալեքսանդրետը, ապա Իզմիրը և Ստամբուլը։ Զինադադարը համարվում է կայսրության փաստացի ավարտի փաստաթուղթը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Համա, Դամասկոս, Հոմս։", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Մուստաֆա Քեմալը Սամսունում — Ազգային պայքարը", "09a8f784"], "d": ["Իզմիրի օկուպացիայի առաջացրած զայրույթի մթնոլորտում 9-րդ բանակի տեսուչի կարգավիճակով Սամսունում ափ իջած Մուստաֆա Քեմալ փաշան իր պաշտոնական հանձնարարությունը վերածեց Անատոլիայում դիմադրության կազմակերպման։ Ամասիայի շրջաբերականը և Էրզրումի ու Սեբաստիայի վեհաժողովները այս քայլի շարունակությունն են. «ազգի անկախությունը կփրկի դարձյալ ազգի հաստատակամությունն ու որոշումը» սկզբունքը դարձավ Ազգային պայքարի քաղաքական ծրագրի միջուկը։", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Թուրքիայի Ազգային մեծ ժողովի բացումը և Սևրը", "2008feec"], "d": ["Ստամբուլի պաշտոնական օկուպացիայի և Մեբուսանների ժողովի ցրման առիթով 1920 թվականի ապրիլի 23-ին Անկարայում բացվեց Ազգային մեծ ժողովը. արտակարգ լիազորություններն իր ձեռքում կենտրոնացրած ժողովը դարձավ ազգային կամքի վրա հիմնված նոր պետության միջուկը։ Օգոստոսին Ստամբուլի կառավարության ստորագրած Սևրի պայմանագիրը բաժանում էր Անատոլիան. Ազգային մեծ ժողովը պայմանագիրը ստորագրողներին հայտարարեց հայրենիքի դավաճաններ, և Սևրը երբեք չկիրառվեց։", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Սաքարիայի դաշտային ճակատամարտը", "f2f970a6"], "d": ["Անկարային մինչև 50 կիլոմետր մոտեցած հունական հարձակումը կոտրվեց 22 օր ու 22 գիշեր տևած ճակատամարտում, որը վարվեց գերագույն հրամանատարի լիազորությունն ստանձնած Մուստաֆա Քեմալ փաշայի «չկա պաշտպանության գիծ, կա պաշտպանության տարածք» հրամանով։ Հունական բանակն առաջին անգամ անցավ ռազմավարական պաշտպանության. հաղթանակը Մուստաֆա Քեմալին բերեց ղազիի կոչում և մարշալի աստիճան, բացեց Անկարայի համաձայնագրի (Ֆրանսիայի հետ) և արտաքին ճանաչման դուռը։", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Մեծ հարձակումը և Իզմիրի ազատագրումը", "172a50c4"], "d": ["Օգոստոսի 26-ի առավոտյան Քոջաթեփեից սկսված հարձակումը օգոստոսի 30-ին Դումլուփընարում Գերագույն հրամանատարի դաշտային ճակատամարտով հասավ հունական հիմնական ուժերի ոչնչացմանը. «Բանակներ, ձեր առաջին նպատակակետը Միջերկրական ծովն է, առա՛ջ» հրամանով շարունակվող հետապնդմամբ սեպտեմբերի 9-ին Իզմիրը ազատագրվեց։ Մուդանիայի զինադադարով (հոկտեմբերի 11) Արևելյան Թրակիան հետ վերցվեց առանց պատերազմի. ռազմական հաղթանակը որոշեց Լոզանում ստեղծվելիք նոր պետության ուժը բանակցային սեղանի շուրջ։", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Սուլթանության վերացումը", "9f36a9f6"], "d": ["Լոզանի բանակցություններին նաև Ստամբուլի կառավարությանը հրավիրելու առիթով Ազգային մեծ ժողովը 1922 թվականի նոյեմբերի 1-ին, իրարից բաժանելով սուլթանությունը և խալիֆայությունը, վերացրեց սուլթանությունը. 623-ամյա օսմանյան հարստության կառավարումը իրավաբանորեն ավարտվեց։ Մեհմեդ VI Վահիդեդդինը նոյեմբերի 17-ին անգլիական զրահանավով լքեց երկիրը. խալիֆայության աթոռին Ազգային մեծ ժողովի որոշմամբ նշանակվեց Աբդուլմեջիդ էֆենդին, և այդ աթոռը ևս վերանալու էր 1924 թվականի մարտի 3-ին։", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Լոզանի պայմանագիրը", "38c27f7d"], "d": ["Ութ ամիս տևած ծանր բանակցությունների վերջում ստորագրված Լոզանի հաշտության պայմանագրով միջազգային մակարդակում ճանաչվեցին նոր թուրքական պետության սահմանները, լիակատար անկախությունը և ինքնիշխանությունը. վերացվեցին կապիտուլյացիաները, Պետական պարտքի վարչությունը մտավ լուծարման գործընթաց, կարգավորվեց բնակչության փոխանակությունը։ Սևրը փաստացի անվավեր դարձրած Լոզանը համարվում է Ազգային պայքարի դիվանագիտական հաղթանակը և Հանրապետության հիմնադիր արտաքին փաստաթուղթը։", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Հանրապետության հռչակումը", "d5bfcdfb"], "d": ["Ազգային մեծ ժողովի՝ սահմանադրության փոփոխությամբ «Թուրքիայի պետության կառավարման ձևը հանրապետությունն է» դրույթն ընդունելով հռչակվեց Հանրապետությունը. Մուստաֆա Քեմալ փաշան ընտրվեց առաջին նախագահ։ Այսպիսով ավարտվեց 1299 թվականին որպես սահմանամերձ բեյլիք սկսված 624-ամյա օսմանյան ուղին, և կայսրության ժառանգության վրա հիմնվեց նոր պետություն, որտեղ ինքնիշխանությունն անվերապահորեն պատկանում է ազգին։", "f5cabb8c"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["Կարաֆերիեի (Վերիա) անցումը օսմանյան տիրապետության տակ", "b0ece3f3"], "d": ["1387 թվականին Սալոնիկի հանձնվելու հետ նույն տարում օսմանյան տիրապետության տակ անցավ նաև Ստորին Մակեդոնիայի ներքին մասի Կարաֆերիեն։ Քաղաքը Սալոնիկի և Թեսալիայի միջև ճանապարհի հանգուցակետն էր։", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["Ալբրեխտ IV Վիտելսբախը հրապարակեց պրիմոգենիտուրայի կանոնադրությունը. Բավարիայի դքսությունները միավորվեցին և դարձան անբաժանելի մեկ դքսություն", "86ee6f77"], "d": ["Լանդսհուտի ժառանգական պատերազմից (1503-1505) հետո Բավարիայի դքսությունները կրկին մեկ ձեռքում հավաքած դուքս Ալբրեխտ IV-ը 1506 թվականի հուլիսի 8-ին հրապարակեց պրիմոգենիտուրայի կանոնադրությունը, որը նախատեսում էր երկրի անբաժանելիությունը և գահի անցումը ավագ արու զավակին։ Այսպիսով վերջ գտան 1255 թվականից շարունակվող Բավարիայի բաժանումները. Մյունխեն կենտրոնով Բավարիան գերմանական պետությունների շարքում շարունակեց որպես անբաժանելի մեկ դքսություն։", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["Ամիր II-ը սպանվեց Սանաայի մոտ. Թահիրյան հարստության վախճանը", "713ae406"], "d": ["Թահիրյանների վերջին տիրակալ Ամիր II-ը, մամլուքների նավատորմի հետ հարաբերությունների վատթարացման պատճառով սկսված պատերազմում, երբ եմենյան ցեղերն ու զեյդիները աջակցեցին մամլուքներին, նախ պարտվեց Զաբիդի մոտ (1516 թ. նոյեմբեր), ապա զոհվեց Սանաայի մոտ տեղի ունեցած ճակատամարտում։ Այսպիսով ավարտվեց 1454 թվականից Եմենը կառավարող Թահիրյան հարստությունը. հարստության քաղաքները (ներառյալ Թաիզը) այլևս ենթակա չէին Թահիրյան տիրակալությանը։", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["Լուգոշ (Լուգոժ) և Կարանշեբեշ ամրոցների նվաճումը՝ Թեմեշվարի արշավանքի շարունակությունը", "1af5a2be"], "d": ["Թեմեշվարի ամրոցը երեք շաբաթ դիմադրելուց հետո 1552 թվականի հուլիսի 26-ին հանձնվեց։ Օգոստոսին գրավվեցին նաև Լուգոշի և Կարանշեբեշի ամրոցները. Մուրեշի հովտի երկայնքով գրավվեց տասնհինգ ամրոց, և ստեղծվեց Թեմեշվար կենտրոնով նոր բեյլերբեյություն։", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["Հիմնադրվեց Եկատերինբուրգի երկաթի գործարան-ամրոցը՝ Ուրալի հանքային շրջանի կենտրոնը", "c416e12e"], "d": ["Իսետ գետի վրա Տատիշչևի ընտրած տեղում դե Գենինի ավարտին հասցրած երկաթի գործարանի դարբնամուրճերը գործարկվեցին. Եկատերինբուրգն այս օրն է համարում իր հիմնադրման թվականը։ Ուրալի հանքերի ու երկաթի շրջանի կենտրոն դառնալիք բնակավայրը դարձավ Ռուսական թագավորության՝ դեպի Սիբիր տանող ճանապարհի դարպասը։", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["Զարիան (Զազաուն) անցավ բրիտանական վարչական վերահսկողության տակ. Սոկոտոյի խալիֆայության Զարիայի ամիրայությունը կապվեց Հյուսիսային Նիգերիայի պրոտեկտորատին", "c2e4131e"], "d": ["Սոկոտոյի խալիֆայությանը ենթակա Զարիայի ամիրայությունը 1902 թվականի մարտին առնվեց Անգլիայի Հյուսիսային Նիգերիայի վարչության տակ. անգլիացիները Զարիայում տեղակայեցին ռեզիդենտ և կայազոր։ Ամիր Կվասաուն 1902 թվականի հուլիսին անձնատուր եղավ, իսկ սեպտեմբերին պաշտոնանկ արվեց։", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["Անգլիացիները գրավեցին Կանոն. Սոկոտոյի խալիֆայության ամենամեծ ամիրայությունն անցավ Հյուսիսային Նիգերիայի պրոտեկտորատին", "0484009d"], "d": ["Հյուսիսային Նիգերիայի բարձր կոմիսար Լուգարդի ենթակայության տակ գտնվող գնդապետ Մորլենդի զորաջոկատը, Զարիայից շարժվելով, 1903 թվականի փետրվարին գրավեց Կանոն. Սոկոտոյի խալիֆայությանը ենթակա Կանոյի ամիրայությունն անցավ բրիտանական կառավարման տակ։ Սոկոտոն գրավվեց մեկ ամիս անց՝ 1903 թվականի մարտի 15-ին։", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["Պրիշտինայի անցումը սերբական բանակի ձեռքը", "2ef111c0"], "d": ["Բալկանյան առաջին պատերազմում Կոսովո մտած սերբական բանակը գրավեց Պրիշտինան, և քաղաքում վերսկսվեց սերբացման քաղաքականությունը։ Պրիշտինայի անկումը Կոսովոյի վիլայեթում օսմանյան դիմադրության փլուզման առաջին օղակներից է։", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["Մոնաստիրի գրավումը սերբական ուժերի կողմից", "db9b3353"], "d": ["Բալկանյան առաջին պատերազմում Մակեդոնիայի կարևորագույն վարչական և ռազմական կենտրոններից մեկը՝ Մոնաստիրը, հինգ օր տևած մարտերից հետո անցավ սերբական ուժերի ձեռքը։ Քաղաքի կորուստը նշանակում էր Մակեդոնիայում Օսմանյան պետության ներկայության փաստացի ավարտը։", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["Ալբանիայի անկախության հռչակումը. Իսմաիլ Քեմալին Վլյորայում", "2cdbd4d9"], "d": ["Մինչ Բալկանյան պատերազմի բանակները մտնում էին ալբանական վիլայեթները, Իսմաիլ Քեմալին Վլյորայում հռչակեց Ալբանիայի անկախությունը։ Այսպիսով Դուրեսից, Էլբասանից, Բերատից, Գիրոկաստրայից և Կրույայից մինչև Սարանդա ձգվող ծովափնյա և ներքին շրջանները դուրս եկան օսմանյան կառավարումից և կազմեցին նոր ալբանական պետության կորիզը։", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["Օսմանյան տիրապետության վախճանը Օհրիդում և Դիբրայում", "5273f1ec"], "d": ["Մոնաստիրի անկումից տասնմեկ օր անց սերբական բանակը մտավ արևմտյան Մակեդոնիայի լճերի շրջանը. Օհրիդում ավարտվեց հինգդարյա օսմանյան տիրապետությունը, և հյուսիսում գտնվող Դիբրան ևս նույն գործողության ընթացքում դուրս եկավ ձեռքից։", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["Շկոդրայի գրավումը չեռնոգորցիների կողմից", "db704247"], "d": ["Բալկանյան առաջին պատերազմի ամենաերկար պաշարումներից մեկը տեղի ունեցավ Շկոդրայում. ամիսներ տևած դիմադրությունից հետո քաղաքը հանձնվեց Չեռնոգորիայի ուժերին։ Շկոդրան այն վերջին օսմանյան ամրոցներից էր, որոնք դիմադրեցին մինչև պատերազմի ավարտը։", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["Չեռնոգորիան դուրս բերեց ուժերը Շկոդրայից. մեծ տերությունների միջազգային զորամիավորումը մտավ քաղաք", "8a6593e9"], "d": ["Մեծ տերությունների ճնշման տակ Չեռնոգորիան 1913 թվականի ապրիլի 23-ին գրաված Շկոդրան 1913 թվականի մայիսի 14-ին դատարկեց. քաղաք մտավ միջազգային զորամիավորումը, և այն դարձավ Ալբանիայի հիմնադիր վարչակարգի մաս։", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["Իբն Սաուդը գրավեց Լահսան. Օսմանյան տիրապետության վախճանը Պարսից ծոցի ափին", "505f26d5"], "d": ["Նեջդի ամիր Աբդուլ Ազիզ բ. Սաուդը, դուրս մղելով օսմանյան կայազորը, գրավեց Լահսայի շրջանը և հաստատվեց կենտրոն Հուֆուֆում։ Քաթիֆի և Ուքայրի նավամատույցների հետ միասին Ծոցի արևմտյան ափն անցավ Սաուդյան կառավարմանը. ավարտվեց Օսմանյան պետության հիսնամյա կառավարումը շրջանում։", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["Բուխարեստի պայմանագիր. Արևմտյան Թրակիան և Կավալայի ավազանը Բուլղարիայից անցան Հունաստանին", "56123a58"], "d": ["Բալկանյան երկրորդ պատերազմն ավարտվեց Բուլղարիայի և Սերբիայի, Հունաստանի ու Չեռնոգորիայի միջև ստորագրված Բուխարեստի պայմանագրով։ Առաջին պատերազմում Բուլղարիայի ձեռքն անցած Կավալայի, Դրամայի և Սերեսի ավազանն այս պայմանագրով թողնվեց Հունաստանին։ Այս պայմանագրով Տուտրականը (Թուրթուքայա) անցավ Ռումինիային։", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["Շաթթ ալ-Արաբի դեսանտը. Բասրայի անկումը և Իրաքի ճակատի բացումը", "c0a87d5d"], "d": ["Առաջին համաշխարհային պատերազմի սկզբում Հնդկաստանից եկած բրիտանական արշավախմբային ուժերը ափ իջան Շաթթ ալ-Արաբի գետաբերանին գտնվող Ֆավում և կարճ ժամանակում գրավեցին Բասրան։ Քաղաքի անկումը նշանակում էր Իրաքի ճակատի բացումը և Ծոցի հյուսիսային ծայրի անցումը բրիտանական վերահսկողության տակ։", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["Վրաստանը հռչակեց անկախություն. Անդրկովկասի սեյմը ցրվեց", "6c79a8c7"], "d": ["Բրեստ-Լիտովսկից հետո ստեղծված Անդրկովկասի սեյմից դուրս եկած Վրաստանը հռչակեց անկախություն, և ստեղծվեց Վրաստանի դեմոկրատական հանրապետությունը։ Քութայիսիի հետ միասին արևմտյան Վրաստանն անցավ այս նոր պետության կառավարմանը։ Այս հռչակմամբ Սուխումը, Փոթին, Զուգդիդին, Գորին, Թելավին և Դուշեթին անցան Վրաստանի դեմոկրատական հանրապետությանը։", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["Հռչակվեց Ադրբեջանի դեմոկրատական հանրապետությունը", "8baecec3"], "d": ["Վրաստանի անջատումից երկու օր անց հռչակվեց Ադրբեջանի դեմոկրատական հանրապետությունը. առաջին կենտրոնը դարձավ Գանձակը։ Նույն օրը Երևանում ստեղծվեց նաև Հայաստանի Հանրապետությունը, և Անդրկովկասը բաժանվեց երեք առանձին պետությունների։ Այս հռչակմամբ Շամախին, Կաբալան, Էրեշը, Շաբրանը, Սալյանը, Կուբան, Շաքին և Բարդան անցան Ադրբեջանի դեմոկրատական հանրապետությանը։", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["Հալեպի գրավումը արաբական և բրիտանական ուժերի կողմից", "00efb2da"], "d": ["Պաղեստինյան ճակատի փլուզումից հետո դեպի հյուսիս առաջացող ուժերը մտան Հալեպ. քաղաքը նախ անցավ արաբական, ապա բրիտանական զորամասերի ձեռքը։ Մուդրոսի զինադադարից երեք օր առաջ տեղի ունեցած այս գրավումը փաստացի վերջ դրեց Սիրիայում Օսմանյան պետության չորսդարյա կառավարմանը։", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["Կարմիր բանակը գրավեց Ադրբեջանը. դեմոկրատական հանրապետության վախճանը", "ebbb4566"], "d": ["Կարմիր բանակը, մտնելով Ադրբեջան, ցրեց խորհրդարանն ու կառավարությունը. ավարտվեց երկամյա Ադրբեջանի դեմոկրատական հանրապետությունը։ Բաքվի նավթային ավազանը և Գանձակն այսպիսով անցան խորհրդային կառավարմանը։ Այս գրավմամբ Շամախին, Կաբալան, Էրեշը, Շաբրանը, Սալյանը, Կուբան, Շաքին և Բարդան անցան Խորհրդային Ռուսաստանի վերահսկողության տակ։", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["Խան Մեյսալուն. ավարտվեց Ֆեյսալի շրջանը, Սիրիան անցավ ֆրանսիական մանդատի տակ", "80a932b0"], "d": ["Բեյրութ-Դամասկոս ճանապարհի Խան Մեյսալունում ֆրանսիացիները ծանր պարտության մատնեցին սիրիական ուժերին, և վերջ գտավ Ֆեյսալի Արաբական թագավորությունը Դամասկոսում։ Ֆրանսիան փաստացի հաստատեց Սան Ռեմոյում իրեն տրված մանդատային իրավասությունը. Հալեպից Դամասկոս, Ալեքսանդրետից Դեր Զոր ձգվող շրջանը ենթարկվեց ֆրանսիական մանդատային վարչությանը։", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["Ստեղծվեց Անդրհորդանանի ամիրայությունը. Աբդուլլահ բ. Հուսեյնը հռչակեց իր ամիրությունը", "5ef520c2"], "d": ["Շերիֆ Հուսեյնի որդի Աբդուլլահը, Մաանի վրայով գալով դեպի հյուսիս, հռչակեց Անդրհորդանանի ամիրայությունը. Անգլիան կարճ ժամանակ անց այս վարչությունը ճանաչեց մանդատի շրջանակում։ Ամմանը դարձավ ամիրայության կենտրոնը, և Հորդանանի սարահարթը, ներառյալ Քարաքը, կապվեց այս նոր վարչությանը։", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["Իտալիան Լյուբլյանայի գավառը բռնակցեց թագավորությանը. Լյուբլյանան պոկվեց Հարավսլավիայից", "c451f492"], "d": ["1941 թվականի ապրիլին Հարավսլավիայի փլուզմամբ Լյուբլյանան և Սլովենիայի արևմտյան կեսը գրաված Իտալիան 1941 թվականի մայիսի 3-ի հրամանագրով շրջանը «Լյուբլյանայի գավառ» անվամբ բռնակցեց թագավորությանը. բարձր կոմիսար դարձավ Գրացիոլին։ Լյուբլյանան դուրս եկավ Հարավսլավիայից և անցավ իտալական կառավարման տակ (մինչև 1943 թվականի սեպտեմբերը)։", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["Հայլե Սելասիեն վերադարձավ Ադիս Աբեբա. Հաբեշստանը անջատվեց Իտալական Արևելյան Աֆրիկայից", "42470af3"], "d": ["Այն բանից հետո, երբ անգլո-հաբեշական ուժերը ապրիլի սկզբին գրավեցին Ադիս Աբեբան, կայսր Հայլե Սելասիեն 1941 թվականի մայիսի 5-ին հաղթական վերադարձավ մայրաքաղաք. իտալական օկուպացիայի (1936-41) պաշտոնական ավարտը համարվում է այս օրը։ Ատլասն այս օրն օգտագործում է որպես Հաբեշստանի՝ Իտալական Արևելյան Աֆրիկայից վերադառնալու սահմանագիծ։", "b9c24f62"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["Կոկոսյան (Քիլինգ) կղզիները հանվեցին Սինգապուրի գաղութից և փոխանցվեցին Ավստրալիային", "5c2d70c7"], "d": ["Բրիտանիայի 1955 թվականի Cocos Islands Act-ի համաձայն հրապարակված Order in Council-ի և Ավստրալիայի Cocos (Keeling) Islands Act 1955-ի հռչակագրի (Proclamation) օրը՝ 1955 թվականի նոյեմբերի 23-ին, կղզիները դադարեցին լինել Սինգապուրի գաղութի մաս և անցան Ավստրալիայի Համագործակցության իրավասության տակ։ Հոմ Այլենդը (Home Island, Կլունիս-Ռոս ընտանիքի սեփականությունը և կոկոս-մալայական բնակավայրը) այդ օրվանից հետո ավստրալական կառավարման տակ է։", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["Սուրբ Ծննդյան կղզին Բրիտանիայից փոխանցվեց Ավստրալիային", "c971c518"], "d": ["Բրիտանիայի The Christmas Island (Transfer to Australia) Order in Council 1958-ը 1958 թվականի հոկտեմբերի 1-ին ուժի մեջ մտավ. կղզու ինքնիշխանությունը բրիտանական Սինգապուրի գաղութից անցավ Ավստրալիայի Համագործակցությանը։ Flying Fish Cove-ը կղզու բնակավայրի և նավահանգստի կենտրոնն է։", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["Վուկովարը ընկավ. ՀԺԲ-ն և սերբական զորամասերը եռամսյա պաշարումից հետո գրավեցին քաղաքը", "30db2698"], "d": ["Պաշարված Վուկովարի մնացած խորվաթ պաշտպանները 1991 թվականի նոյեմբերի 18-ին անձնատուր եղան. քաղաքն անցավ Հարավսլավիայի ժողովրդական բանակի և սերբական ուժերի ձեռքը։ Հետագայում քաղաքն անցավ ՄԱԿ-ի Արևելյան Սլավոնիայի անցումային վարչակազմի (UNTAES) ժամանակաշրջանը։", "09aa356a"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Սենուսիների անապատային կենտրոն Ջաղբուբի կապումը օսմանյան կարգին. Աբդուլմեջիդի ազատման ֆիրմանը", "039fce6d"], "d": ["Երկար տարիներ Մեքքայում մնացած Մուհամմադ բ. Ալի աս-Սենուսին, Տրիպոլիտանիա վերադառնալուց հետո, հաստատվեց Եգիպտոսի սահմանին գտնվող Ջաղբուբի օազիսում և գերիշխող ժայռի վրա մեծ զավիե կառուցել տվեց. մի քանի խրճիթից բաղկացած վայրը կարճ ժամանակում վերածվեց քաղաքի։ 1856 թ. սուլթան Աբդուլմեջիդի ֆիրմանով միաբանության անդամներին պատկանող գույքը ազատվեց հարկերից, և մուրիդներին տրվեց զաքաթ հավաքելու իրավասություն։ Այս ֆիրմանը Արևմտյան Աֆրիկան և Սուդանը Կահիրեին կապող քարավանային ճանապարհի վրա գտնվող օազիսը դարձրեց օսմանյան ֆինանսական և վարչական կարգի մաս և ամրապնդեց Ջաղբուբը որպես առևտրի կենտրոն։ Շրջանի բնակչության հավատարմությունը խալիֆին հաստատում է նաև 1884 և 1893 թթ. այստեղ եղած գնդապետ Սադըք ալ-Մուայյեդի ճանապարհորդագրությունը։", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Սուեզի ջրանցքի փորման սկիզբը և Պորտ Սաիդի հիմնումը", "cef0be8d"], "d": ["Բաբը Ալիի (Բարձր Դռան) 1856 թ. հունվարի 5-ին հավանություն տված Լեսեփսի նախագծի փորման աշխատանքները սկսվեցին 1859 թ. ապրիլի 25-ին. ջրանցքն ավարտվելու էր տասը տարի անց՝ 1869 թ. նոյեմբերի 16-ին։ Փորման միջերկրածովյան ծայրին՝ Մանզալա լճի և ծովի միջև ընկած ափային շերտի վրա, բանվորների համար կառուցված հինգ տնից բաղկացած խրճիթային գյուղը դարձավ Պորտ Սաիդի միջուկը։ Քաղաքին այս անունը, «Սաիդի նավահանգիստ» իմաստով, 1860 թ. տվեցին ջրանցքի ընկերության պաշտոնյաները՝ ի պատիվ ժամանակի Եգիպտոսի կուսակալ Սաիդ փաշայի։ Այսպիսով, օսմանյան քարտեզի վրա նոր նավահանգիստ ծնվեց մի ափային շերտի վրա, որտեղ նախկինում ոչ մի բնակավայր չի եղել։", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Սուլթան Աբդուլազիզի այցը Եգիպտոս և Իսմաիլիայի հիմնումը Սուեզի պարանոցում", "bcfacf38"], "d": ["Սուլթան Աբդուլազիզը մեծ վեզիր Յուսուֆ Քամիլ փաշայի խրախուսմամբ 1863 թ. ապրիլի 3-ին մեկնեց Եգիպտոս և դիմավորվեց մեծ ցույցերով. նպատակն էր ամրապնդել կենտրոնին ենթակայությունը այն վիլայեթի, որը Կավալալի Մեհմեդ Ալի փաշայի ապստամբությունից ի վեր սկսել էր փաստացի վերածվել առանձին պետության։ Նույն տարում պարանոցում՝ Թիմսահ լճի ափին գտնվող Թիլալ ալ-Ջիսրի բլուրների վրա, հիմնվեց ջրանցքի ընկերության կառավարման կենտրոնը. նախ ինժեներների համար հաստատվեց Քարյաթ ութ-Թիմսահ, ապա բանվորների համար՝ Քարյաթ ուլ-Արաբ գյուղը։ Երբ խեդիվ Իսմայիլ փաշան անձամբ հետաքրքրվեց քաղցրահամ ջրի ջրանցքով և այդ բլրի վրա իր համար ամառանոց կառուցել տվեց, բնակավայրը նրա անունով կոչվեց Իսմաիլիա։ Քաղաքի հիմնումը թվագրվում է 1863 թ.. ճշգրիտ օրը հայտնի չէ։", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Միդհաթ փաշայի Բաղդադի կուսակալությունը և ցեղերի բնակեցումը. Ռամադիի և Նասիրիայի հիմնումը", "0fa98f06"], "d": ["Պետական խորհրդի (Շյուրա-յը Դևլեթ) նախագահությունից հեռացված և Ստամբուլից հեռու ուղարկված Միդհաթ փաշան 1869-1872 թթ. լայն իրավասություններով կառավարեց Բաղդադի վիլայեթը, որն ընդգրկում էր նաև Մոսուլն ու Բասրան, միաժամանակ ղեկավարելով նաև Վեցերորդ բանակը։ Այստեղ կիրառելով Հողային օրենսգիրքը և վիլայեթների նոր օրենքը՝ նա հողերը բաժանեց տապուով (սեփականության վկայականով) և քոչվոր ցեղերը կապեց նստակյաց կյանքին և պետական իշխանությանը։ Այս բնակեցման քաղաքականության արդյունքում 1869 թ. Եփրատի ափին Դուլայմ ցեղի համար հիմնվեց Ռամադին, իսկ հարավում Մունթաֆիքի մութասարրիֆ Նասիր փաշա աս-Սաադունի ձեռքով՝ Նասիրիան. երկուսն էլ ծնվեցին այն կետերում, որտեղ մինչ այդ բնակավայր չէր եղել, և քարտեզ մտան առաջին անգամ այդ ժամանակ։", "7babb36f"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Հիմնադրվեց Պանաման՝ Խաղաղ օվկիանոսի ափի առաջին եվրոպական քաղաքը", "c0d86c22"], "d": ["Դարիենի կուսակալ Պեդրարիաս Դավիլան պարանոցի խաղաղօվկիանոսյան ափին հիմնեց Պանամա քաղաքը և գաղութային վարչությունը Կարիբյան ափից տեղափոխեց այստեղ։ Քաղաքը դարձավ դեպի հարավ ուղղվելիք հետախուզական և նվաճողական արշավանքների ելման նավահանգիստը. Ֆրանսիսկո Պիսարոյի Պերուի արշավանքներն այստեղից են հանդերձվել։", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["Հիմնադրվեց Սան Ֆրանսիսկո դե Կիտոն՝ իսպանական կարգ ինկերի հյուսիսային մայրաքաղաքում", "7bb9f316"], "d": ["Ինկերի զորավար Ռումինյաուին, նախքան հյուսիսի մայրաքաղաք Կիտոն իսպանացիներին թողնելը, այրեց այն։ Սեբաստիան դե Բենալկասարը ավերակների վրա հիմնեց Սան Ֆրանսիսկո դե Կիտոն. այսպիսով Կուսկոյից հետո ինկերի պետության երկրորդ կենտրոնը ևս ենթարկվեց իսպանական կառավարմանը, և Հյուսիսային Անդերի նվաճումը ղեկավարվեց այստեղից։", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Հիմնադրվեց Լիման. իսպանական Պերուի մայրաքաղաքը տեղափոխվեց Ռիմակի հովիտ", "1f15658c"], "d": ["Քանի որ լեռներում գտնվող Կուսկոն հեռու էր Իսպանիայի հետ ծովային կապից, Ֆրանսիսկո Պիսարոն ծովափնյա Ռիմակի հովտում հիմնեց Սյուդադ դե լոս Ռեյեսը (Լիմա)։ Քաղաքը կարճ ժամանակում դարձավ Պերուի փոխարքայության մայրաքաղաքը և Հարավային Ամերիկայում իսպանական կառավարման կենտրոնը։", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Հիմնադրվեց Պոպայանը՝ կամուրջ Կիտոյի և մուիսկաների երկրի միջև", "bf451979"], "d": ["Կիտոյից դեպի հյուսիս շարժվող Բենալկասարը Կաուկայի հովտում հիմնեց Պոպայանը։ Քաղաքը դարձավ Պերուից եկող իսպանական առաջխաղացման հյուսիսային ծայրակետը և հաջորդ տարի բացեց մուիսկաների երկրում Կեսադայի հետ հանդիպմանը տանող ճանապարհը։", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["Հունսայի գրավումը. սակե Կեմուենչատոչայի պարտությունը", "e8c1b661"], "d": ["Մագդալենա գետից սարահարթ բարձրացած Գոնսալո Խիմենես դե Կեսադան հարձակվեց մուիսկաների համադաշնության երկու գլխավոր կենտրոններից մեկի՝ սակե տիտղոսակրի իշխանության (սակասգո) կենտրոն Հունսայի վրա և գերեց սակե Կեմուենչատոչային։ Քաղաքում ձեռք գցված ոսկին դարձավ այն հիմնական ավարը, որը սնեց Էլդորադոյի մասին ասեկոսեները. այսպիսով մուիսկաների երկրի հյուսիսային կեսն անցավ իսպանական տիրապետության տակ։", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Հիմնադրվեց Ասունսիոնը՝ իսպանական հենակետ Պարագվայ գետի վրա", "9a6dfa42"], "d": ["Երբ Ռիո դե լա Պլատայի արշավախումբը չկարողացավ ամրանալ Բուենոս Այրեսում, իսպանացիները նահանջեցին գետն ի վեր, և Խուան դե Սալասար դե Էսպինոսան, հենվելով գուարանի համայնքների հետ կնքված դաշինքի վրա, հիմնեց Նուեստրա Սենյորա դե լա Ասունսիոնը։ Ավանը մեկ դար շարունակ մնաց Ռիո դե լա Պլատայի ավազանում իսպանական կառավարման կենտրոնը։", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Հիմնադրվեց Սանտա Ֆե դե Բոգոտան՝ իսպանական մայրաքաղաք մուիսկաների երկրում", "3ed6c301"], "d": ["Կեսադան սիպայի կենտրոն Բակատայի կողքին հիմնեց Սանտա Ֆե դե Բոգոտան։ Հիմնադրումից անմիջապես հետո երեք տարբեր ուղղություններից եկած նվաճողական ջոկատները՝ Կեսադան, Բենալկասարը և գերմանացի հրամանատար Ֆեդերմանը, հանդիպեցին նույն սարահարթում և պայմանավորվեցին իրենց իրավունքների պահանջները լուծել Իսպանիայում։ Քաղաքը դարձավ Նոր Գրանադայի թագավորության մայրաքաղաքը։", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["Հիմնադրվեց Սան Խուան դե լա Ֆրոնտերա դե Ուամանգան՝ Լիմա-Կուսկո ճանապարհի բանալին", "3f1cfdbf"], "d": ["Մանկո Ինկայի՝ Վիլկաբամբայից ղեկավարած դիմադրությունը կտրում էր Լիմայի և Կուսկոյի միջև ճանապարհը։ Ֆրանսիսկո Պիսարոն այս ճանապարհն ապահովելու համար երկու մայրաքաղաքների միջև հիմնեց Սան Խուան դե լա Ֆրոնտերա դե Ուամանգան. ավանի անվան «frontera» (սահմանագիծ) բառն ուղղակիորեն ասում է նրա հիմնադրման նպատակը։", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Տունխան վերահիմնադրվեց որպես իսպանական քաղաք", "c3a12867"], "d": ["Կեսադայի Իսպանիա վերադառնալուց հետո Գոնսալո Սուարես Ռենդոնը սակեի կենտրոն Հունսայի տեղում իսպանական կարգով վերահիմնադրեց Տունխա քաղաքը։ Այսպիսով մուիսկաների երկրի հյուսիսային կեսը, Բոգոտայի կեսի նման, կապվեց քաղաքային մշտական ինքնակառավարման և էնկոմիենդայի կարգի հետ։", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Հիմնադրվեց Սանտյագո դել Նուևո Էքստրեմոն. սկսվեց Չիլիի նվաճումը", "04cd7c3b"], "d": ["Պերուից դեպի հարավ շարժվող Պեդրո դե Վալդիվիան Մապոչոյի հովտում հիմնեց Սանտյագո դել Նուևո Էքստրեմոն։ Ավանը նույն տարվա սեպտեմբերին Միչիմալոնկոյի գլխավորած բնիկների հարձակման հետևանքով այրվեց և վերակառուցվեց. այդուհանդերձ, Չիլիի իսպանական նվաճումը ղեկավարվեց հենց այս կետից։", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Հիմնադրվեց Վիլյա դե Օրոպեսան՝ Պոտոսին կերակրող հացահատիկային հովտի բնակեցումը", "d6821cbf"], "d": ["Փոխարքա Ֆրանսիսկո դե Տոլեդոյի հրամանով Կոչաբամբայի հովտում հիմնադրվեց Վիլյա դե Օրոպեսան։ Հովտի բերրի հողը կազմակերպվեց որպես հացահատիկային շրջան, որը պետք է կերակրեր Պոտոսիի արծաթի հանքերի բազմամարդ աշխատուժը. ավանը դարձավ գաղութային Վերին Պերուի շտեմարանը։", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["Վիլկաբամբայի անկումը. անկախ ինկերի պետության վախճանը", "31b5a95d"], "d": ["1533 թվականին Կուսկոյի անկումից հետո Մանկո Ինկան և նրա հաջորդները Վիլկաբամբայի լեռներում քառասուն տարի պահպանեցին ինկերի անկախ պետություն։ Փոխարքա Ֆրանսիսկո դե Տոլեդոյի կազմակերպած արշավանքը գրավեց լքված մայրաքաղաքը. փախուստի դիմած վերջին տիրակալ Տուպակ Ամարուն բռնվեց, բերվեց Կուսկո և այնտեղ մահապատժի ենթարկվեց։ Այսպիսով Անդերի աշխարհում ավարտվեց ինկերի չորսդարյա հարստության քաղաքական գոյությունը։", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["Հիմնադրվեց Սան Ֆրանսիսկո դե Բորխան. իսպանական տիրապետություն Մայնասում", "7ee32d19"], "d": ["Դիեգո Վակա դե Վեգան Մարանյոն գետի Պոնգո դե Մանսերիչե կիրճից ներքև հիմնեց Սան Ֆրանսիսկո դե Բորխան և Մայնասի շրջանը կապեց իսպանական կառավարմանը։ Ավանը դարձավ ելման կետ ճիզվիտական առաքելությունների ցանցի համար, որը Վերին Ամազոնում գործելու էր ողջ հաջորդ դարը։", "83ae5281"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Անկարայի պարտությունից հետո Վալախիայի վոյևոդ Միրչան վերագրավեց Դոբրուջան. Սիլիստրա, Կոնստանցա, Բաբադագ, Իսակչա", "5eaefc68"], "d": ["Անկարայում Յըլդըրըմ Բայազիդի՝ Լենկթեմուրից կրած պարտությունը ցնցեց օսմանյան տիրապետությունը Դանուբի ափին։ Վալախիայի վոյևոդ Միրչան, օգտվելով այս դատարկությունից, կրկին մտավ Դոբրուջա. Սիլիստրան, Կոնստանցան, Բաբադագի շրջակայքը և Դանուբի ափի Իսակչան Ֆեթրեթի (գահակալական կռիվների) տարիներին մնացին նրա ձեռքում։ Միրչան աջակցեց Մուսա Չելեբիին Մեհմեդ Չելեբիի դեմ։ Սիլիստրան նա պահեց մինչև իր մահը՝ 1418 թ.։", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Բաբադագի և նրա շրջակայքի անցումը Օսմանյան պետությանը. Միրչան և նրա որդի Միհայլը պարտվեցին", "bfda2c60"], "d": ["Մեհմեդ Չելեբին Վալախիայի վոյևոդ Միրչային և նրա որդի Միհայլին հաղթելուց հետո Հյուսիսային Դոբրուջայում գտնվող Բաբադագը և շրջակայքը վերցրեց օսմանյան տիրապետության տակ։ Բաբադագը Սալթուկ Բաբայի անունը կրող և 13-րդ դարի թուրքմենական բնակավայրով հիմնված ավան էր։ Իսկ շրջակա Սիլիստրան, Կոնստանցան և Դոբրուջայի մյուս բերդերը մինչև 1419 թ. մնացին Վալախիային. այսինքն՝ Բաբադագը երեք տարի երևում է որպես օսմանյան հողից կտրված կղզի (էքսկլավ)։", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Սիլիստրայի և Դոբրուջայի վերագրավումը. Միրչայի մահից հետո", "73eb6ae9"], "d": ["Վալախիայի վոյևոդ Միրչայի 1418 թ. մահից հետո Վալախիայում բռնկված խառնակությունը Սուլթան Մեհմեդ Չելեբիին Սիլիստրան և Դոբրուջան հետ գրավելու հնարավորություն տվեց։ 1419 թ. գարնանը Սիլիստրան, Կոնստանցան և Դոբրուջայի մեծ մասը կրկին անցան օսմանյան կառավարման տակ. Ենիսալեի (Enisala) և Իսակչայի բերդերը նորոգվեցին և դարձան սահմանային բերդեր (սերհադ). դրանից հետո Դոբրուջան մինչև 1878 թ. մնաց օսմանյան։", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Ստորին Դանուբի փակումը. Ջուրջուի, Տուրնուի և Օրշովայի բռնակցումը", "331a0b68"], "d": ["Գահակալական կռիվների շրջանի ավարտից հետո Մեհմեդ Չելեբիի՝ դանուբյան գիծը կարգի բերելու քայլը 1420 թ. պտուղ տվեց։ Ջուրջուի (Յերկյոկյու) բերդը, որը Վալախիայի վոյևոդ Միրչա Մեծը կառուցել էր իր հողի վրա՝ ծախսը հոգալով աղի վաճառքից, այդ տարում անցավ օսմանյան ձեռքը (Դոբրուջան հետ էր գրավվել մեկ տարի առաջ՝ 1419 թ. գարնանը. TDV silistre), և բռնակցվեցին Դանուբի աջ ափին գտնվող Տուրնուն (Կուլե/Խոլովնիկ) և Օրշովան՝ հետագայում Ֆեթհյուլիսլամ անունով։ Այսպիսով, գետի երկու ափերը միաժամանակ վերահսկողության տակ առնվեցին։ Ջուրջուի կարևորությունը բխում է նրա աշխարհագրությունից. այն Դանուբի ձախ, այսինքն՝ վալախական ափին հիմնված օսմանյան բերդ է և հակառակ ափի Ռուսչուկի հետ միասին պահում է նույն անցման երկու ծայրերը։ Օսմանյան փաստաթղթերը այս երկակիությունը բացահայտորեն գրում են. Ռուսչուկի համար ասվում է «Yergöğü beri yaka» (Յերկյոկյուի այս ափը), իսկ Ջուրջուի համար՝ «Yergöğü öte yaka» (Յերկյոկյուի մյուս ափը)։ Բերդը 1427 թ. հետ էր վերցվելու վալախների կողմից, 1449 թ. կրկին անցնելու օսմանյան վերահսկողության տակ, և Ջուրջուի կազան, ենթարկվելով Նիկոպոլիսի սանջակին, դառնալու էր վոյևոդության ներսում անմիջականորեն կառավարվող կղզի։ Այն հարցի պատասխանը, թե ինչու է քարտեզում Վալախիայի դանուբյան ափը մուգ գույնի, սկսվում է այստեղից։", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["Տոպլիցայի շրջանը (Կուրշումլիա, Պրոկուպլիե) անցավ օսմանյան տիրապետության տակ", "e22e690d"], "d": ["Հավանական է համարվում, որ Մուրադ II-ի՝ Մարա Բրանկովիչի հետ նշանադրության ժամանակ Դուբոչիցայի և Տոպլիցայի շրջանը (Լեսկովացի, Կուրշումլիայի և Պրոկուպլիեի շրջակայքը) անցել է օսմանյան տիրապետության տակ. 1445-1447 թթ. թահրիրի (հարկացուցակի) գրառումը ցույց է տալիս, որ շրջանը որպես թիմար տրվել է օսմանյան սիփահիներին։ Քարտեզում Կուրշումլիան և Պրոկուպլիեն այդ տարվանից ի վեր գտնվում են օսմանյան կառավարման տակ։", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Սարայի հարթավայրի բռնակցումը. Բոսնիայի ներսում օսմանյան սահմանային հենակետի հիմնումը", "be5c0f00"], "d": ["Երբ Բոսնիայի թագավորները 1428-1429 թթ. հարկատու դարձան, օսմանցիները սկսեցին մշտապես հաստատվել թագավորության ներսում։ 1428-1435 թթ. գրավվեց Հոդիդյեդ ավանը. 852 (1448) թ. Հոդիդյեդի վիլայեթը Սարայի հարթավայրի հետ ամբողջությամբ անցավ օսմանյան կառավարման տակ։ Սա Բոսնիայի գրավումից տասնհինգ տարի առաջ թագավորության մեջտեղում ստեղծված սահմանային շրջան է, որը կառավարել է վոյևոդի տիտղոսը կրող Սկոպյեի բեյ Իսա բեյը. քանի որ շրջակայքում դեռ կային օսմանյան հպատակ բոսնիացի բեյեր, շրջանը գտնվում էր երկկողմանի վերահսկողության տակ։ Քաղաքն ինքնին նույնպես ծնվեց այդ շրջանում. 1462 թ. առաջ Իսհակ բեյը կամ նրա որդի Իսա բեյը հիմնեց առաջին մուսուլմանական թաղամասը, 862 (1458) թ. Ֆաթիհի անունով կառուցվեց Հյունքյարի մզկիթը, և Բրոդեց գյուղի արտերը կառուցապատվելով ի հայտ եկավ Սարայ ավանը։ 1463 թ. նվաճումը վերացրեց Բոսնիայի թագավորությունը. իսկ Սարայի հարթավայրը այդ ժամանակ արդեն տասնհինգ տարի օսմանյան հող էր։", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Պոդգորիցայի միացումը օսմանյան հողերին. Զետայի հարթավայրի վերահսկողության տակ առնելը", "46e401c5"], "d": ["Շկոդրայի լճից քսան կիլոմետր հյուսիս՝ Մորաչա և Ռիբնիցա գետերի միախառնման հարթավայրում հիմնված ավանը աղբյուրներում առաջին անգամ հիշատակվում է 1216 թ. Ռիբնիցա, իսկ 1326 թ.՝ Պոդգորիցա անունով։ 1457 թ. այն միացավ օսմանյան հողերին, և այդպիսով Զետայի հարթավայրի վերահսկողությունը դուրս եկավ Բալշիչ-Չեռնոևիչ հարստությունների ձեռքից։ Ֆաթիհ Սուլթան Մեհմեդը 1474-1478 թթ. երկու գետերի միախառնման զառիթափ ժայռերի վրա բերդ և մզկիթ կառուցել տվեց. 1479 թ. Շկոդրայի գրավումից հետո շրջանը կցվեց նորաստեղծ Շկոդրայի սանջակին։ 1485 թ. թահրիրում քառասուն տնից բաղկացած քրիստոնյա ավան եղած Պոդգորիցան 1529-30 թթ. ուներ 800 բնակիչ և բերդի ներսում դիզդարի (բերդապետի) հրամանատարությամբ երեսուներկու հոգանոց կայազոր, իսկ 1582 թ. հասավ 322 տան։ Էվլիյա Չելեբին 1662 թ. Ֆաթիհի բերդում հաշվեց երեք հարյուր տուն, ամբարներ, զինապահեստներ և յոթ հարյուր պահակ։ Այս գրառումները ցույց են տալիս նաև Զետայի հարթավայրի և լեռների միջև տարբերությունը. հարթավայրը հաշվառված, հարկվող և կայազոր ունեցող օսմանյան կազա է, մինչդեռ 18-րդ դարում քաղաքը ստիպված է լինելու, Չեռնոգորիայի լեռների ցեղերի հարձակումները կանխելու համար, ամրանալ վեց ամրությամբ և երեք դարպասով պարիսպներով։ Պոդգորիցան 1876-1878 թթ. պատերազմի վերջում անցավ Չեռնոգորիայի ձեռքը և Բեռլինի պայմանագրով մնաց նրան։", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Ֆոչայի գրավումը. Հերցեգովինայի դքսություն առաջին մուտքի բացումը", "f098a9e6"], "d": ["1463 թ. Բոսնիայի թագավորությունը վերացնելուց հետո հերթը հասավ թագավորությունից անջատված և իր դքսությունն ստեղծած Ստեփան Վուկչիչ-Կոսաչայի հողերին։ Դրինայի հովտում՝ Ստամբուլը Դուբրովնիկին կապող առևտրական ճանապարհի խաչմերուկին գտնվող Ֆոչան 1465 թ. անցավ օսմանյան կառավարման տակ։ Քաղաքի կարևորությունը անմիջապես հասկացվեց. 1470 թ. այն դարձվեց նորաստեղծ Հերցեգովինայի սանջակի կենտրոն, այսինքն՝ Հերցեգովինայի վարչական միջուկը հիմնվեց Ֆոչայում դեռ դքսության կործանումից առաջ։ Դքսության ամբողջական բռնակցումը տևելու էր մինչև 1483 թ.։ Դրանից հետո Ֆոչան, բարենպաստ կլիմայի և ճանապարհային խաչմերուկի դիրքի շնորհիվ, զարգացավ որպես առևտրի և կառավարման կենտրոն։ Քարտեզում այս թիվը այն օրն է, երբ Բոսնիայի գրավումից հետո սկսվեց դեպի հարավ երկրորդ ալիքը։", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Լիվնոյի և արևմտյան Բոսնիայի վերջնական բռնակցումը. վենետիկյան սահմանի հաստատումը", "c14d4283"], "d": ["Լիվնոյի հարթավայրի վրա իշխող բարձրավանդակի բերդը 1448-1454 թթ. գտնվում էր Հերցեգովինայի դքսության հիմնադիր Ստեփան Վուկչիչ-Կոսաչայի ձեռքում։ 1463 թ. բոսնիական արշավանքում այն կարճ ժամանակով օկուպացվել էր օսմանյան ուժերի կողմից, բայց նույն տարում հետ վերցվել. 1466 թ. քաղաքի տերը Իվանիշ Վլատկովիչն է։ TDV-ի խոսքով՝ վերջնական օսմանյան տիրապետությունը մեծ հավանականությամբ իրագործվել է 1468-1469 թթ., և 1485 թ. թահրիրը Լիվնոն արդեն գրանցում է որպես օսմանյան հող։ Սա բոսնիական նվաճման արևմտյան ծայրի փակումն է. Լիվնոն դարձավ վտանգավոր սահմանային ավան՝ հարթ հարթավայրի երկայնքով ընդամենը երեսունվեց կիլոմետր հեռու գտնվող վենետիկյան հողերի հարևանությամբ, և այս դիրքը պահպանեց մինչև 1521-1522 թթ., երբ Բոսնիայի կուսակալ Ղազի Հյուսրև բեյը գրավեց վենետիկյան բերդերը։", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Շաբացի (Բյոյուրդելեն) կորուստը հունգարներին. Սավայի գծի առաջին ճեղքը", "129fe8f2"], "d": ["Ֆաթիհ Սուլթան Մեհմեդի ժամանակ օսմանյան ձեռքն անցած և նախկինում Զասլոն անունով հիշվող վայրում 1471 թ. կառուցվել էր փայտից և հողից ամրոց։ Քանի որ այն գտնվում էր Բելգրադին սպառնացող կետում, և այստեղից հեշտությամբ կարելի էր հարձակումներ գործել Հունգարիայի և Ավստրիայի հարավային շրջանների վրա, բերդը անունն էլ ստացել էր այդ գործառույթից. «Բյոյուրդելեն» նշանակում է «կողից խփող ամրություն»։ Հունգարիայի թագավոր Մաթիաս Կորվինը 1475 թ. վերջին պաշարեց բերդը և 1476 թ. փետրվարին գրավեց այն։ Պաշարումը պատմող «Szabács viadala» անունով հունգարական էպոսը 15-րդ դարի հունգարական պատմական բանաստեղծությունների՝ մեր օրերը հասած ամենաերկար նմուշներից է։ Հունգարները շրջանում ստեղծեցին բանություն և, բերդը քարով վերաամրացնելով, այն դարձրին սահմանային բերդաշղթայի օղակ։ Օսմանցիները 1492 թ. փորձեցին հետ գրավել այն և չկարողացան. բերդը քառասունհինգ տարի մնաց հունգարների ձեռքում։", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Իոնական կղզիների նվաճումը. Տոկկոյի դքսության վախճանը՝ Այա Մավրա, Կեֆալոնիա, Զակինթոս, Իթակա", "07b27251"], "d": ["Նույն տարվա հունվարին Վենետիկի հետ ստորագրված Ստամբուլի պայմանագիրը Շկոդրան և ալբանական ափը թողել էր Օսմանյան պետությանը. իսկ Իոնական կղզիները գտնվում էին ոչ թե Վենետիկի, այլ Կեֆալոնիա-Զակինթոսի կոմսությունն իր ձեռքում պահող Տոկկոների ընտանիքի կառավարման ներքո և գրավվեցին առանձին գործողությամբ։ Ըստ TDV-ի «Այա Մավրա» հոդվածի՝ վերջին դուքս Լեոնարդո Տոկկոն նախ, ամուսնանալով Ֆաթիհի ազգական Միլիցա Բրանկովիչի հետ, պահպանել էր իր հավատարմությունը, իսկ 1464 թ. կնոջ մահից հետո, 1477 թ. ամուսնանալով Նեապոլի հարստության ներկայացուցիչ Ֆրանչեսկա Մարցանոյի հետ, վիրավորել էր փադիշահին։ Երկու տարի անց Ավլոնիայի բեյ Գեդիք Ահմեդ փաշայի հրամանատարությամբ նավատորմը գրավեց Այա Մավրան և հարավում գտնվող Կեֆալոնիան. Լեոնարդոն և Ֆրանչեսկան փախան Իտալիա։ «Գեդիք Ահմեդ փաշա» հոդվածը նշում է, որ նույն գործողության ընթացքում գրավվեց նաև Զակինթոսը (Զանտա). Կեֆալոնիայի կոմսությանը ենթակա Իթական նույնպես այս փոխանցումով անցավ օսմանյան կառավարման տակ։ Այսպիսով, Ադրիատիկի մուտքից մինչև Մորեա ձգվող ծովային ճանապարհն ամբողջությամբ վերահսկողության տակ առնվեց։ Կղզիներից Զակինթոսը երեք տարի անց թողնվելու էր Վենետիկին, Կեֆալոնիան և Իթական կորսվելու էին 1500 թ., և միայն Այա Մավրան երկու հարյուր տարի մնալու էր Օսմանյան պետության ձեռքում։", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Չեռնոևիչների Զետայի հպատակությունը և Ցետինեի կենտրոն դառնալը", "59d20267"], "d": ["1479 թ. Շկոդրայի Օսմանյան պետության ձեռքում մնալով՝ նրա «հետնաբակի» Զետայի լեռնային շրջանն էլ ընկավ կայսրության սահմանների մեջ։ Շրջանն իր ձեռքում պահող Չեռնոևիչների ընտանիքը, ճանաչելով Ֆաթիհի մահից հետո գահ բարձրացած Բայազիդ II-ի իշխանությունը և հարկատու դառնալով, ազատ մնաց իր ներքին գործերում. Իվան Չեռնոևիչը իր կենտրոնը հարթավայրից տեղափոխեց Լովչեն լեռան ստորոտի Ցետինե և հիմնեց քաղաքը։ Երկու տարի անց այստեղ կառուցել տված վանքը դարձավ շրջանի կրոնական կենտրոնը։ Այսպիսով, Չեռնոգորիան քարտեզում երևում է ոչ թե որպես անմիջական օսմանյան հող, այլ որպես բաց երանգով հպատակ շրջան։ TDV-ի «Չեռնոգորիա» հոդվածը հիշատակում է հարստությունը և Ցետինեի եպիսկոպոսությունը և գրում, որ 1514 թ. Իսքենդեր բեյի (Չեռնոևիչների տոհմից, օսմանյան պալատում դաստիարակված) ձեռքով իշխանությունը վերածվեց առանձին սանջակի. իսկ 1482 թվականը TDV-ում չի հիշատակվում, դա չեռնոգորական պատմագրության տված թվականն է։ Աշխարհագրական դաժան պայմանների պատճառով այստեղ կառավարումը երբեք այնքան խիստ չգործեց, որքան հարթավայրերում։", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Կիլիա բերդի նվաճումը. Դանուբի գետաբերանի բանալին", "ef4eca73"], "d": ["Մոլդովան 1455 թ. սեպտեմբերից տարեկան երկու հազար ոսկի հարկ վճարող հպատակ վոյևոդություն էր, բայց դեպի Սև ծով բացվող նրա երկու նավահանգիստները դեռ վոյևոդի ձեռքում էին, և Դանուբից եկող առևտուրն անցնում էր այնտեղով։ Բայազիդ II-ը իր գահակալության առաջին մեծ արշավանքն ուղղեց այս երկու նավահանգիստների դեմ։ Տասն օր շարունակ գիշեր-ցերեկ ռմբակոծված Կիլիա բերդի հրամանատարը ստիպված եղավ հանձնվել։ Բերդը անցավ օսմանյան անմիջական կառավարման տակ և դարձվեց սանջակի բեյություն. 16-րդ դարի երկրորդ կեսին կազակական վտանգի պատճառով այն դարձվեց կազա և ենթարկվեց Ռումելիի բեյլերբեյությանը ենթակա Աքքերմանի սանջակին։ Այդ ժամանակից Մոլդովան քարտեզում երևում է երկու աստիճանով. ներսում վոյևոդությունը ներկայացվում է որպես բաց երանգով հպատակ հող, իսկ ափի երկու նավահանգիստները՝ մուգ երանգով որպես անմիջական օսմանյան սանջակ։ TDV-ի «Մոլդովա» հոդվածը այս երկուսը անվանում է «Մոլդովայի բանալիներն ու դարպասները» և գրում, որ շրջանը վերջնականապես կապվեց Օսմանյան պետությանը Բայազիդ II-ի օրոք։", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Աքքերմանի նվաճումը. Դնեստրի գետաբերանը և Մոլդովայի սևծովյան դարպասի փակումը", "7cb20feb"], "d": ["Կիլիայի հանձնումից քսան օր անց բանակը հասավ Դնեստրի գետաբերանի Աքքերմանի առջև, և բերդը գրավվեց օգոստոսի 4-ին։ Քաղաքը Մոլդովայի ամենաաշխույժ նավահանգիստն էր. Ֆաթիհի օրոք, երբ վոյևոդ Պետրու III-ը 1455 թ. ճանաչեց օսմանյան տիրապետությունը, Աքքերմանի առևտրականներին առևտրի թույլտվություն էր տրվել, իսկ այժմ նավահանգիստը դարձավ անմիջապես պետությանը։ Նվաճումից հետո Ռումելիի բեյլերբեյությանը ենթակա սանջակ դարձված Աքքերմանը 1593 թ. միացվեց նորաստեղծ Օզիի էյալեթին։ Այսպիսով, Մոլդովայի արտաքին պատյանը, որը հյուսիսից շրջապատված էր Խոտինով, իսկ հարավից՝ Կիլիայով և Աքքերմանով, սկսեց անցնել օսմանյան անմիջական վերահսկողության տակ. վոյևոդությունը ներքին գործերում ազատ մնաց, բայց այլևս ծով ելք չուներ։ Քարտեզում դրանց միջև դատարկ շրջան չկա. մուգ երանգով նավահանգստային սանջակները և բաց երանգով վոյևոդության հողը հպվում են միմյանց. դրանց միջև ընկած Բուջակի տափաստանը մինչև 1538 թ. դեռ վոյևոդության մաս է։", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Նավպակտոսի (Իներահտը) հանձնումը. Կորնթոսի ծոցի մուտքը վերցվում է Վենետիկից", "2cfe0777"], "d": ["Նավպակտոսը 1407 թ. ի վեր Վենետիկի ձեռքում էր և պահում էր Կորնթոսի ծոցի մուտքը. ծոցի ներսի ամբողջ ափը կախված էր այս բերդի հրաձգության հեռահարությունից։ 1499 թ. արշավանքում բերդը պաշարվեց ցամաքից, իսկ Նավպակտոսի բաց ծովում վենետիկյան նավատորմի հետ կռիվ մղող օսմանյան նավատորմը ծովից օգնեց պաշարող ուժերին։ Բերդի վենետիկցիները օգոստոսի 26-ին ավանը հանձնեցին օսմանցիներին։ Դրանից հետո քաղաքը հարյուր ութսունութ տարի մնաց Օսմանյան պետության ձեռքում, 1687 թ. Մորեայի կորստով կրկին անցավ Վենետիկին և 1715 թ. հետ գրավվեց։ Նույն ամռան ծովամարտը և այս հանձնումը երկու տարբեր իրադարձություններ են. նավատորմի բախումը տեղի ունեցավ Մորեայի արևմտյան ծայրին՝ Սապիենցա-Զոնկիոյի ջրերում, իսկ Նավպակտոսն ընկավ Կորնթոսի ծոցի մուտքին՝ ցամաքային պաշարմամբ։", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Սրեբրենիկի բանության բռնակցումը. հյուսիսային Բոսնիայում հունգարական գծի առաջին ճեղքը", "6d98c725"], "d": ["1463 թ. Բոսնիայի թագավորության կործանումից հետո Մաթիաս Կորվինը անցել էր հակահարձակման և թագավորության հյուսիսում ստեղծել երկու բանություն, որոնք կասեցնում էին օսմանյան առաջխաղացումը. արևմուտքում՝ Յայցեն, հյուսիս-արևելքում՝ Սրեբրենիկը։ Դրանք Հունգարիայի առաջավոր պաշտպանական գիծն էին Բոսնիայում և փակում էին Սավայի և Բոսնիայի միջև միջանցքը։ Սրեբրենիկի բանությունը գրավվեց 1512 թ.. այսպիսով, փլուզվեց գծի արևելյան թևը, և Զվորնիկի սանջակը կարողացավ ընդարձակվել դեպի հյուսիս։ Իսկ արևմտյան թևի Յայցեն դիմանալու էր ևս տասնվեց տարի և կարող էր գրավվել միայն Մոհաչից հետո՝ 1528 թ.։", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Շաբացի (Բյոյուրդելեն) գրավումը. Կանունիի գրաված առաջին բերդը և Բելգրադի վերաբերյալ որոշման կայացման վայրը", "85177a90"], "d": ["Կանունի Սուլթան Սուլեյմանի հունգարական առաջին արշավանքի ժամանակ շրջան ուղարկված Ռումելիի բեյլերբեյ Ահմեդ փաշայի ուժերը, կատաղի պաշարումից հետո, 1521 թ. հուլիսի 7-ին գրավեցին բերդը։ Շաբացը Կանունիի գահակալության ընթացքում գրավված առաջին բերդն է։ Նվաճումից հետո փադիշահը անձամբ մտավ բերդ և հրամայեց կառուցապատել քաղաքը. Բելգրադի գրավման վերաբերյալ որոշումները նույնպես ընդունվեցին այնտեղ, այսինքն՝ 1521 թ. օգոստոսի 29-ին ընկնելիք Բելգրադի ծրագիրը կազմվեց Շաբացում։ Այդ ժամանակից ի վեր բերդը գրեթե երկու հարյուր տարի մնաց օսմանյան ձեռքում. նախ ենթարկվեց Ռումելիի, 1580 թվականից՝ Բոսնիայի էյալեթին, ապա կարճ ժամանակով Սմեդերևոյի և վերջապես Զվորնիկի սանջակին։ Քարտեզում այս թիվը այն օրն է, երբ Սավայի գիծը փակվեց հօգուտ Օսմանյան պետության։", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Սկսվում է երեք վոյևոդությունների ապստամբությունը. Տրանսիլվանիան անցավ Սրբազան լիգա, օսմանամետ բոյարները ձերբակալվեցին", "68a33800"], "d": ["Երկարատև պատերազմի երկրորդ տարում Կենտրոնական Եվրոպայում Օսմանյան պետության վասալական գոտին միանգամից քայքայվեց։ Հռոմի պապ Կղեմես VIII-ի հովանավորությամբ ստեղծված Սրբազան լիգային ամռան վերջում միացան Մոլդովան և Տրանսիլվանիան. Մոլդովայի վոյևոդ Արոն Վոդան 1594 թ. օգոստոսի 16-ին քրիստոնյա կողմին իր միանալը պաշտոնականացրեց փաստաթղթով, իսկ Տրանսիլվանիայի իշխան Ժիգմոնդ Բատորին 1594 թ. օգոստոսի 28-ին վերացրեց պատերազմի դեմ հանդես եկող օսմանամետ բոյարներին և կոտրեց ներքին ընդդիմությունը։ Վալախիայի վոյևոդ Միհայ Քաջը նույն տարվա աշնանը միացավ լիգային։ Այսպիսով, Դանուբից հյուսիս գտնվող օսմանյան երեք հպատակ իշխանությունները՝ հարյուր հիսուն տարի հարկ վճարող և Ստամբուլի կողմից հաստատվող վոյևոդներ ունեցող երեք վոյևոդությունները, նույն աշնանը միանգամից անցան հակառակ կողմ։ Որոշումը պաշտոնականացվեց 1595 թ. հունվարի 28-ին Պրահայում ստորագրված պայմանագրով։ Սա Բալկաններից հյուսիս օսմանյան անուղղակի կառավարման կարգի կրած ամենածանր ցնցումն էր. ապստամբությունը ճնշվելու էր, բայց երեք իշխանությունների հավատարմությունը այլևս երբեք այնքան ամուր չէր լինելու, որքան 1526-1593 թթ.։", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Բուխարեստի ապստամբությունը և հարձակումը դանուբյան բերդերի վրա", "18971100"], "d": ["Սրբազան լիգայի որոշումը մեկ ամիս անց իրագործվեց արյունով. Միհայ Քաջը Բուխարեստում սրի քաշեց օսմանյան պահակազորը և քաղաքի լևանտացի պարտատերերին։ Ապստամբությունը նույն ձմռանը տարածվեց Դանուբի գծով. վալախական ուժերը հարձակվեցին Ջուրջուի (Յերկյոկյու), Բրաիլայի, Հըրշովայի և Սիլիստրայի վրա, իսկ Մոլդովայի կողմից Արոն Վոդան նույնպիսի հարձակում կատարեց Բենդերի օսմանյան պահակների վրա։ Հարվածված վայրերի ընտրությունը պատահական չէ. դրանք բոլորը ոչ թե վոյևոդության հող էին, այլ Դանուբի երկայնքով օսմանյան անմիջական կառավարմանը ենթակա բերդեր և կազաներ. Ջուրջուի կազան ենթարկվում էր Նիկոպոլիսի սանջակի բեյությանը, Բրաիլան 1538 թ. ի վեր՝ անմիջապես պետությանը, Բենդերը, դարձյալ 1538 թ. ի վեր, Բուջակի սանջակին։ Այսինքն՝ ապստամբությունը հարվածել էր ոչ թե վասալ ներքին շրջանից, այլ այդ շրջանը շրջապատող անմիջական օսմանյան պատյանին։ Առանց այս պատյանը ծակելու Տրանսիլվանիա-Վալախիա-Մոլդովա եռանկյունին հնարավոր չէր միացնել Հաբսբուրգյան ճակատին։", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Կալուգերանի ճակատամարտը. Քոջա Սինան փաշայի վալախական արշավանքը", "201210a1"], "d": ["Երեք վոյևոդությունների միանգամից կորստի պատճառով մեծ վեզիր Քոջա Սինան փաշան մեծ բանակով անցավ Դանուբը և շարժվեց Վալախիան կրկին հնազանդեցնելու համար։ Միհայ Քաջը, իմանալով, որ բաց պատերազմում չի կարող դիմադրել, բանակին սպասեց Նեյաժլովի ճահճոտ անցումում՝ Կալուգերանում, և նեղ տարածքում խցկված ուժերի վրա հանկարծակի հարձակվեց։ Հարձակումից հետո, չկարողանալով դիմակայել թվաքանակով գերազանցող օսմանյան բանակին, նա նահանջեց հյուսիս՝ լեռները. Սինան փաշան, օկուպացնելով Բուխարեստը և Թըրգովիշտեն, փորձեց Վալախիան ենթարկել անմիջական կառավարմանը։ Այդ պատճառով Կալուգերանը օսմանցիների համար պարտություն չէր, այլ հանկարծակի հարձակում, որը հետաձգեց արշավանքի ավարտը. սակայն այն, որ Միհայը կարողացել էր պահպանել իր բանակը, հնարավորություն տվեց մի քանի շաբաթ անց Տրանսիլվանիայից ստացված օգնությամբ անցնել հակահարձակման։", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Նահանջ Վալախիայից և Ջուրջուի հանկարծակի հարձակումը. ճնշման արշավանքի անարդյունք մնալը", "118806e1"], "d": ["Տրանսիլվանիայի իշխանի ուժերի հետ միավորված Միհայ Քաջի հակահարձակման պատճառով Սինան փաշան դատարկեց Թըրգովիշտեն և Բուխարեստը և նահանջեց դեպի Դանուբ։ Նահանջի ամենաթանկ պահը տեղի ունեցավ անցման մոտ. 1595 թ. հոկտեմբերին Վալախիայից վերադարձող բանակին հետապնդող ակընջիները Ջուրջուի մոտ ենթարկվեցին Միհայի հանկարծակի հարձակմանը։ Արշավանքն այսպես ավարտվեց՝ չհասնելով Վալախիան անմիջական կառավարմանը ենթարկելու նպատակին, և վոյևոդությունը փաստացի մնաց կորսված։ Օսմանյան իշխանությունը այս եռանկյունում կարողացավ վերականգնվել միայն տարիների ընթացքում և մաս առ մաս. Տրանսիլվանիայի վերադարձը հնազանդության սպասելու էր 1604 թ. Բոչկաի ապստամբությանը, իսկ ճակատի լիովին փակումը՝ 1606 թ. Ժիտվատորոկի պայմանագրին։", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Խոտինի անջատումը Մոլդովայից. օսմանյան անմիջական սանջակ վոյևոդության մեջտեղում", "947517cb"], "d": ["Պրուտի արշավանքի ժամանակ Մոլդովայի վոյևոդ Դիմիտրիե Կանտեմիրի անցումը Ռուսաստանի կողմը ցույց տվեց, որ վոյևոդության հյուսիսային սահմանն այլևս չի կարելի թողնել վոյևոդին։ Դրա հիման վրա Խոտինը 1711 թ. հետո վերցվեց Մոլդովայից և դրվեց օսմանյան անմիջական կառավարման տակ. նախ նրան տրվեց նահիեի, ապա սանջակի կարգավիճակ։ 1713 թ. ժամանակավոր ռուսական օկուպացիայից հետո բերդը Ստամբուլից ուղարկված օսմանյան և ֆրանսիացի տեխնիկական պատվիրակության հսկողությամբ կրկին վերանորոգվեց և ընդարձակվեց և դարձավ Դանուբից հյուսիս օսմանյան ամենահզոր ամրությունը։ Այդ ժամանակից ի վեր քարտեզում Խոտինի դուրս գալը հպատակ վոյևոդության երանգից և անմիջական օսմանյան գույն ստանալը, ինչպես նաև այն, որ հպատակ Մոլդովայի մեջտեղում այն կանգնած է միայնակ կղզու նման, հենց այս վարչական անջատման արտացոլումն է, այլ ոչ թե գծագրման սխալ։ Նույն կառուցվածքն արդեն գոյություն ուներ Բուջակում 1538 թ., Կիլիայում և Աքքերմանում՝ 1484 թ. ի վեր. վոյևոդությունը ազատ էր ներքին գործերում, իսկ սահմանային բերդերը պետությանն էին։", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Շաբացի երկրորդ ավստրիական օկուպացիան. Սավայի ճակատի բացումը", "063b3ad0"], "d": ["1788 թ. փետրվարի 9-ին Ավստրիայի՝ Ռուսաստանի կողքին պատերազմի մեջ մտնելուց հետո Սավայի գիծը կրկին ճակատ դարձավ, և Շաբացը 1788 թ. ապրիլի 24-ին անցավ ավստրիական տիրապետության տակ։ Բերդը ավելի վաղ՝ 1717 թ. օգոստոսի 17-ին, առանց պատերազմի զիջվել էր Ավստրիային և նրա ձեռքում էր պահվել մինչև Բելգրադի պայմանագիրը (1739). այդ ժամանակ նրա բնակչությունն այնքան էր նվազել, որ քաղաքում մնացել էր երեսունչորս քրիստոնյա տուն, իսկ մուսուլման ոչ մեկը չէր մնացել։ 1739-1788 թթ. օսմանյան շրջանում բնակչությունը կրկին հասել էր 1500-2000-ի։ Երկրորդ օկուպացիան ավարտվելու էր Սվիշտովի պայմանագրով (1791 թ. օգոստոսի 4), և բերդը վերադարձվելու էր օսմանցիներին։", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Շաբացի հանձնումը Կարա Յորգիին. առաջին բերդը Սերբական առաջին ապստամբության ժամանակ", "5c913eb4"], "d": ["1804 թ. Բելգրադում դեյիների և յամաքների ճնշման դեմ ի պատասխան սկսված և հետագայում ազգայնական բնույթ ստացած առաջին սերբական ապստամբության ժամանակ Շաբացի բերդը 1806 թ. հունվարի 26-ին հանձնվեց Կարա Յորգիին։ Սավայի ափի այս բերդը ապստամբների գրաված առաջին խոշոր օսմանյան ամրությունն է և ավետում է Բելգրադի անկումը։ Երբ 1813 թ. ապստամբությունը ճնշվեց և Բելգրադը հետ գրավվեց, բերդն էլ վերադարձավ օսմանյան կառավարման տակ. սակայն 1830 թ. ֆիրմանի կայազորի պայմանով Շաբացը, Բելգրադի, Սմեդերևոյի և Ֆեթհյուլիսլամի հետ միասին, սահմանվեց որպես ինքնավար Սերբիայի ներսում օսմանյան զորքի մնացած չորս բերդերից մեկը և այդ կարգավիճակով մնաց մինչև 1867 թ., երբ կայազորը դուրս բերվեց։", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Լամիան (İzdin) մնաց Հունաստանի սահմանների ներսում. Արտա-Վոլոս գիծը", "930f63b8"], "d": ["Անկախ հունական պետության հյուսիսային սահմանը 1832 թ. գծվեց Արտայի ծովածոցից մինչև Վոլոսի ծովածոց ձգվող գծով։ Օսմանյան շրջանում (1424-1832) Էվբեայի սանջակին ենթակա կազայի կենտրոն եղած Լամիան, այդ գծից հարավ մնալով, անցավ Հունաստանին. Թեսալիայի մնացած մասը (Լարիսա, Տրիկալա) մինչև 1881 թ. մնաց Օսմանյան պետությանը։", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Ռուսաստանի պատերազմի հայտարարությունը. «93-ի պատերազմի» սկիզբը", "ac548ab8"], "d": ["1876 թ. բուլղարական ապստամբության ճնշումը մեծ զայրույթ էր առաջացրել եվրոպական հասարակական կարծիքում, և Ռուսաստանը դա լիովին օգտագործել էր Բաբը Ալին (Բարձր Դուռը) մեկուսացնելու համար։ Երբ Օսմանյան պետությունը մերժեց Ստամբուլի (նավաշինարանի) համաժողովի՝ Բուլղարիան երկու ինքնավար էյալեթի բաժանելու առաջարկը և ապա 1877 թ. մարտի 31-ի Լոնդոնի արձանագրությունը, Ռուսաստանը 1877 թ. ապրիլի 24-ին պատերազմ հայտարարեց, և նրա բանակը մտավ իր կողմը գրաված Ռումինիայի իշխանության տարածք (քարտեզը Վալախիա-Մոլդովան այդ պահից մինչև Ադրիանապոլսի զինադադարը ցույց է տալիս ռուսական առաջխաղացման շտրիխավորված ծածկույթով)։ Քանի որ ռումի օրացույցով այն համընկնում էր 1293 թ.-ին, պատերազմը հիշվում է «93-ի պատերազմ» անունով։ Գործողությունն ընթացավ երկու ճակատով՝ դանուբյան և Արևելյան Անատոլիայի. Դանուբում 180.000-անոց օսմանյան բանակը գետի ձախ ափը համարել էր առաջին, իսկ Բալկանյան լեռները՝ երկրորդ պաշտպանական գիծ. արևելքում Ահմեդ Մուխթար փաշայի 55.000 զինվորը դիրքավորված էր Արդահանի և Դողուբայազիթի միջև։ Քարտեզում այս պատերազմը այն իրադարձությունն է, որ սկիզբ դրեց օսմանյան Ռումելիի փլուզմանը. Բուլղարիայի, Սերբիայի, Չեռնոգորիայի և Ռումինիայի ներկայիս բոլոր սահմանները այս տասնհինգ ամիսների արդյունքն են։", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Ռումինիան հռչակում է անկախություն. Վալախիա-Մոլդովայի հպատակության վախճանը", "bdd164b3"], "d": ["«93-ի պատերազմի» հայտարարությունից երկու շաբաթ անց Ռումինիայի իշխանությունը հռչակեց անկախություն և պատերազմի մեջ մտավ Ռուսաստանի կողմից. Պլևնայի պաշարման մեջ նրա մասնակցությունը վճռորոշ եղավ օսմանյան պարտության համար։ Այսպիսով, Վալախիայի և Մոլդովայի ավելի քան չորսհարյուրամյա հպատակությունը փաստացի ավարտվեց. անկախությունը միջազգային ճանաչում ստացավ Բեռլինի վեհաժողովում (1878)։ Քարտեզը այդ ժամանակից ի վեր Ռումինիան ցույց է տալիս ոչ թե որպես հպատակ, այլ սեփական գույնով անկախ պետություն։ Անկախության հռչակմամբ Վալախիան և Մոլդովան ամբողջությամբ (Յասի, Գալաց, Բրաիլա, Ջուրջու, Կալաֆաթ, Բոտոշան և այլն) դարձան անկախ Ռումինիա։", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Ռուսական բանակը անցնում է Դանուբը. Սվիշտովի և Տառնովոյի անկումը", "811367b1"], "d": ["Պատերազմի սկսվելուն պես Ռումինիայի տարածք մտած և այդ իշխանությունը իրենց կողմը գրաված ռուսները առաջ շարժվեցին երկու ուղղությամբ՝ մեկը դեպի Դոբրուջա, մյուսը՝ դեպի Բուխարեստ։ Դանուբն անցան Ռուսչուկի և Նիկոպոլիսի միջև, հունիսի 27-ին գրավեցին Սվիշտովը, իսկ հուլիսի 1-ին՝ բուլղարական նախկին մայրաքաղաք Տառնովոն։ Թեև հրամայված էր դատարկել, բայց դրան ուշադրություն չդարձվեց, և Նիկոպոլիսը նույնպես որոշ ժամանակ դիմադրելուց հետո հանձնվեց։ Առաջին պաշտպանական գծի մեկ շաբաթվա ընթացքում ճեղքվելը Ստամբուլում մեծ խուճապ առաջացրեց. անգամ լուրեր տարածվեցին, թե սուլթանության կենտրոնը տեղափոխվելու է Բուրսա, և պատերազմի ղեկավարումը հանձնվեց մայրաքաղաքում ստեղծված ռազմական խորհրդին։", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Շիպկայի լեռնանցքի դատարկումը. բալկանյան գծի ճեղքումը", "1f45e50a"], "d": ["Բալկանյան լեռները հատող լեռնանցքներից ամենառազմավարականը հանդիսացող Շիպկայի օսմանյան ուժերը կատաղի կերպով դիմակայեցին ռուսական հարձակումներին. սակայն համոզվելով, որ պարտվելու են՝ հուլիսի 19-ին գաղտնի դատարկեցին լեռնանցքը։ Այսպիսով, բացվեց նաև երկրորդ պաշտպանական գիծը, և գեներալ Գուրկոն հուլիսի 22-ին գրավեց Ստարա Զագորան։ Չեռնոգորիայի կողմից հասած Սուլեյման փաշան, թեև պարտության մատնելով Գուրկոյին, հետ գրավեց Բալկաններից հարավ օկուպացված վայրերը, օգոստոսի 21-ից ամիսներ շարունակ տևած հարձակումներին չնայած՝ Շիպկան հետ գրավել չկարողացավ։ Քարտեզում սա նշանակում է, որ Բալկանյան լեռնաշղթայի հյուսիսի և հարավի միջև պաշտպանական ամբողջականությունը այլևս չվերականգնվեց. դանուբյան ճակատի պայքարն այսուհետ հանգուցվելու էր Պլևնայում։", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Լովեչը (Լոֆչա) օկուպացվեց ռուսական բանակի կողմից", "70e54611"], "d": ["«93-ի պատերազմում» Լովեչը 1877 թ. հունիսի 5-ին օկուպացվել էր ռուսների կողմից, հունիսի 15-ին Ռիֆաթ փաշայի հրամանատարությամբ օսմանյան ուժերը հետ էին մղել ռուսներին. օգոստոսի 23-ին օսմանցիները լքեցին քաղաքը, և այն կրկին անցավ ռուսական օկուպացիայի տակ։ Քարտեզը Լովեչը այդ օրից մինչև Բեռլինի պայմանագիրը ցույց է տալիս ռուսական օկուպացիայի տակ (շտրիխավորված). իրավաբանորեն այն շարունակում է լինել օսմանյան հող։", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Կարսի անկումը. արևելյան ճակատի քայքայումը և Ազիզիեի ամրությունները", "53fc3bf5"], "d": ["Արևելյան Անատոլիայում Կարսի, Դողուբայազիթի և Արդահանի ուղղությամբ երեք թևով առաջացող ռուսները ապրիլի 30-ին գրավել էին Դողուբայազիթը և մտել Արդահան, բայց Էրզրումի վրա շարժվելիս հուլիսի 15-ին պարտվելով դուրս էին մղվել սահմանից։ Ահմեդ Մուխթար փաշային «Ղազի» տիտղոսը վաստակեցրած այս հաջողությունը օգոստոսին գեներալ Լազարևի կրկին հարձակման անցնելով հակառակ ընթացք ստացավ, և նոյեմբերի 18-ին Կարսն ընկավ։ Ավելի հարմար պաշտպանության համար Էրզրում նահանջած օսմանյան ուժերը Ազիզիեի ամրություններում, Նենե Հաթունի կողմից բնակչության քաջալերմամբ, մեծ դիմադրություն ցույց տվեցին։ Կարսը, Արդահանը և Բաթումը ութ ամիս անց Բեռլինում ռազմատուգանքի մի մասի դիմաց զիջվելու էին Ռուսաստանին։", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Բալկանյան առաջին պատերազմի սկիզբը. Չեռնոգորիայի պատերազմի հայտարարությունը", "c0c2697e"], "d": ["Բալկանյան պետությունները, այն բանից հետո, երբ «Միություն և առաջադիմություն» կոմիտեն 1911 թ. հուլիսի 3-ի օրենքով լուծեց եկեղեցիների հարցը, վերացրին իրենց միջև ամենամեծ խոչընդոտը և Ռուսաստանի դրդմամբ 1912 թ. ընթացքում միմյանց հետ դաշինքի պայմանագրեր ստորագրեցին (մարտի 13-ին՝ Սերբիա-Բուլղարիա, մայիսի 29-ին՝ Բուլղարիա-Հունաստան, օգոստոսին՝ Չեռնոգորիա-Բուլղարիա, հոկտեմբերի 6-ին՝ Չեռնոգորիա-Սերբիա)։ Բաբը Ալին դա չնկատեց. նույնիսկ, վստահելով Ռուսաստանի երաշխիքին, զորացրեց Ռումելիի 120 վարժեցված գումարտակները։ Չորս պետությունները հոկտեմբերի 3-ին համատեղ նոտա տալով՝ պահանջեցին ինքնավարություն Մակեդոնիայի, Ալբանիայի և Կրետեի համար. պատասխան չստանալով՝ 1912 թ. հոկտեմբերի 8-ին Չեռնոգորիայի պատերազմի հայտարարությամբ սկսվեց գործողությունը։ Հոկտեմբերի 13-ին Սերբիայի և Բուլղարիայի դեսպաններին հանձնվեցին նրանց անձնագրերը, հաջորդ օրը այս երկու պետությունները, ապա Հունաստանը պատերազմ հայտարարեցին։ Պատերազմի ընթացքում բանակի ներսում քաղաքական հայացքների տարաձայնությունները մեծ դեր խաղացին պարտության մեջ։", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Ռոդոպներում Քըրջալիի զորախումբը ջախջախվեց, Քըրջալին ընկավ", "8cf59b7f"], "d": ["Բուլղարիայի պատերազմի հայտարարությունից հետո Ռոդոպներից իջնող բուլղարական ուժերը, հաղթելով Մեհմեդ Յավեր փաշայի Քըրջալիի զորախմբին, մտան Քըրջալի։ Ջախջախված զորախումբը նահանջեց Կոմոտինիի ուղղությամբ. Ռոդոպների արևելյան հատվածը կորսվեց պատերազմի առաջին շաբաթում։", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Արևելյան բանակի ջախջախումը և նահանջը Չաթալջայի գիծ. Կումանովոյի և Սալոնիկի կորուստը", "cf95591a"], "d": ["Օսմանյան Արևելյան բանակը 1912 թ. հոկտեմբերի 23-ին, պարտվելով իրենից երեք անգամ բազմաքանակ բուլղարական բանակին, նահանջեց մինչև Ստամբուլից երեսուն կիլոմետր արևմուտք ընկած Չաթալջայի գիծը. մայրաքաղաքը պատերազմի առաջին ամսում ընկավ անմիջական սպառնալիքի տակ։ Նույն օրերին Արևմտյան բանակը հոկտեմբերի 23-24-ին Կումանովոյում պարտվեց սերբերին, և Թահսին փաշան իր 35.000-անոց բանակով Սալոնիկում անձնատուր եղավ հույներին։ Այս ջախջախումների հետևանքով հոկտեմբերի 29-ին Ղազի Ահմեդ Մուխթար փաշայի կաբինետը հրաժարական տվեց. Սալոնիկում աքսորական կյանք վարող Աբդուլհամիդ II-ը նոյեմբերի 1-ին տեղափոխվեց Ստամբուլ։ Չաթալջայի գիծը պահվեց մինչև պատերազմի ավարտը. Ռումելիի հինգհարյուրամյա օսմանյան աշխարհագրությունը մի քանի շաբաթում սեղմվեց այս նեղ գոտու մեջ։", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Նովի Պազարի սանջակի կենտրոն մտավ իշխան Ալեքսանդարը", "326d0616"], "d": ["Սերբական ուժերը պատերազմի առաջին շաբաթում գրավեցին Նովի Պազարը և միացան արևմուտքից եկող չեռնոգորական ուժերին։ Այսպիսով, Սերբիան և Չեռնոգորիան հարյուր տարի բաժանող Նովի Պազարի սանջակը վերածվեց երկու դաշնակիցների միջև կամրջի։", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Քըրքքիլիսեի ճակատամարտից հետո Քըրքլարելին կորսվեց", "eda4c759"], "d": ["Արևելյան Թրակիայում Արևելյան բանակի՝ Քըրքքիլիսեի ճակատամարտում պարտվելուց հետո Քյոլեմեն Աբդուլլահ փաշայի պաշտպանած քաղաքը թողնվեց բուլղարական ուժերին։ Քաղաքը իննամսյա օկուպացիայից ազատագրվեց միայն Բալկանյան երկրորդ պատերազմում՝ 1913 թ. հուլիսի 21-ին։", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Կոսովոյի վիլայեթի կենտրոն Սկոպյեն լքվեց առանց դիմադրության", "455d9b71"], "d": ["Կումանովոյի պարտությունից (հոկտեմբերի 23-24) հետո Կոսովոյի վիլայեթի կենտրոն Սկոպյեն մնաց անպաշտպան։ Քանի որ ժողովուրդը չէր ցանկանում կռիվ քաղաքի շուրջ, հյուպատոսների միջոցով հրավիրված իշխան Ալեքսանդարի հրամանատարությամբ սերբական ուժերը հոկտեմբերի 26-ի երեկոյան առանց դիմադրության մտան քաղաք։", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Վարդարի երկայնքով Վելեսը (Քյոփրյուլյու) կորսվեց", "73d20b7d"], "d": ["Սկոպյեի անկումից երկու օր անց Վարդարի երկայնքով դեպի հարավ իջնող սերբական բանակը գրավեց Վելեսը։ Այսպիսով, Վարդարի հովտի՝ դեպի Սալոնիկ բացվող դարպասը անցավ սերբերի ձեռքը։", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Բրեգալնիցայի ավազան. գեներալ Ստեֆանովիչը մտավ Շտիպ", "70a84256"], "d": ["Գեներալ Ստեֆանովիչի հրամանատարությամբ սերբական զորամասերը առանց դիմադրության հանդիպելու գրավեցին Շտիպը. քաղաք նախ մտան անկանոն ջոկատները։ Կումանովոյից հետո արևելյան Մակեդոնիայի Բրեգալնիցայի ավազանը անցավ սերբական վերահսկողության տակ։", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Սարանդապորոյի լեռնանցքից հետո Վերիան (Կարաֆերիե) անցավ հունական տիրապետության տակ", "02a68e02"], "d": ["Թեսալիայից դեպի հյուսիս առաջացող հունական բանակը, հաղթահարելով Սարանդապորո (Քըրքգեչիթ) լեռնանցքը, տիրեց Վերիային։ Քաղաքի մուսուլման բնակչության մի մասը այդ ժամանակ լքեց շրջանը։", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Սալոնիկ-Մոնաստիր (Բիթոլա) երկաթուղու վրա գտնվող Վոդենան կորսվեց", "fc15b917"], "d": ["Սալոնիկ-Մոնաստիր երկաթուղու վրա գտնվող Վոդենան անցավ հունական բանակի ձեռքը։ Սլավոնական և թուրք բնակչության բռնի հեռացմամբ քաղաքի բնակչությունը կարճ ժամանակում լրջորեն նվազեց։", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Ենիջեի ճակատամարտը. Ենիջե-ի Վարդարի անցումը հույներին", "8f6cb76e"], "d": ["Հասան Թահսին փաշայի 8-րդ համակցված կորպուսը Սալոնիկից արևմուտք գտնվող Ենիջեում պարտվեց հունական բանակին և նահանջեց Սալոնիկի շրջան։ Ճակատամարտի ընթացքում ավանի մեծ մասն այրվեց. դեպի Սալոնիկ ճանապարհը բացվեց հունական բանակի առաջ։", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Պրիզրենը Կոսովոյի հարավ-արևմուտքում հանձնվեց", "bae6b1b9"], "d": ["Կոսովոյի հարավ-արևմուտքում գտնվող Պրիզրենը հանձնվեց սերբական ուժերին։ Քաղաք մտած զորամասերի վերաբերմունքը մուսուլման բնակչության նկատմամբ արձանագրվեց որպես Կոսովոյում պատերազմի ամենածանր էջերից մեկը։", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Գնդապետ Միտովը Ստրումիցայում ռազմական դրություն հայտարարեց", "bcad75cc"], "d": ["Բուլղարացի գնդապետ Միտովը, մտնելով Ստրումիցա, ռազմական դրություն հայտարարեց. հաջորդ օրը հեռանալիս ավանը թողեց բուլղարացի կայմակամի և սերբ հրամանատարի։ Ստրումիցան պատերազմի ողջ ընթացքում ձեռքից ձեռք անցավ դաշնակիցների միջև և 1913 թ. միացվեց Բուլղարիային։", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Հասան Թահսին փաշան Սալոնիկը թողեց հույներին", "1738933c"], "d": ["Ենիջեի պարտությունից հետո Սալոնիկ նահանջած Հասան Թահսին փաշան, երբ բուլղարական բանակը մոտենում էր հյուսիսից, քաղաքը թողեց հույներին. հունական բանակը քաղաք մտավ նոյեմբերի 8-ի կեսօրին։ Այսպիսով, կորսվեց օսմանյան Ռումելիի ամենամեծ նավահանգստային քաղաքը և «Միություն և առաջադիմություն» կոմիտեի ծննդավայր Սալոնիկը։", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Արևմտյան Թրակիայի կենտրոն Կոմոտինին բացվեց բուլղարների առաջ", "96eec25f"], "d": ["Քըրջալիից նահանջած Յավեր փաշայի զորախմբի՝ Ֆերեի ուղղությամբ հետ քաշվելուց հետո Կոմոտինին հանձնվեց բուլղարական ուժերին։ Արևմտյան Թրակիայի կենտրոնը պատերազմի վերջում Բուլղարիային թողնվելիք հողերի գլխին էր։", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Էլբասան հասած սերբերը նույն օրը մտան Դիբրա", "16720246"], "d": ["Մոնաստիրից դեպի արևմուտք առաջացող սերբական ուժերը այն օրը, երբ հասան Էլբասան, մտան նաև Դիբրա և իջան դեպի Ադրիատիկ։ Նույն օրը Ավլոնիայում հռչակվում էր Ալբանիայի անկախությունը։", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Լենկթեմուրը երկրորդ անգամ օկուպացրեց Բաղդադը. քաղաքի աբբասյան թաղամասերը քանդվեցին", "04b68a24"], "d": ["Լենկթեմուրը ութ տարվա ընդմիջումով երկու անգամ գրավեց Բաղդադը։ 1393 թ. առաջին օկուպացիայի ժամանակ քաղաքը շատ վնաս չէր կրել. իսկ 1401 թ. երկրորդը համարվում է Բաղդադի մշակութային կյանքին հասցված երկրորդ ծանր հարվածը. ժողովուրդը սրի քաշվեց, աբբասյան ժամանակաշրջանից մնացած թաղամասերի և շենքերի մեծ մասը ավերվեց։ Ջալայիրյան տիրակալ Ահմեդը, թեև 1405 թ. քաղաք վերադառնալով փորձեց նորոգել քանդված պարիսպները և շուկաները, ժամանակ չունեցավ. Բաղդադը 1410 թ. անցավ Կարա-Կոյունլու թուրքմենների ձեռքը։ Այս երկու օկուպացիաները Անկարայի ճակատամարտին տանող ճանապարհին ամենաշոշափելի քայլերից են, որոնք ցույց են տալիս, թե որքան էր Լենկթեմուրը մոտեցել օսմանյան և մամլուքյան սահմաններին։", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Ջյունեյդ բեյը վերադարձավ Այդընի երկրի գլուխ. Այդընօղուլները կրկին անկախ են", "63281658"], "d": ["Մեհմեդ Չելեբին 1414-15 թթ., գրավելով Իզմիրը և Ջյունեյդ բեյին ուղարկելով Նիկոպոլիսի սանջակի բեյության, Այդընի երկիրը կապել էր օսմանյան կառավարմանը։ Ջյունեյդը Մեհմեդ Չելեբիի մահից հետո կրկին բեմ դուրս եկավ Մուստաֆա Չելեբիի կողքին, որին Բյուզանդիան առաջ էր քաշել որպես գահի հավակնորդ, և նույնիսկ նրա վեզիրն էր։ Մուրադ II-ը, խոստանալով վերադարձնել նրա նախկին բեյությունը, անջատեց նրան այդ դաշինքից. Ջյունեյդն էլ, վերադառնալով Իզմիր, գրավեց Այասուլուկը և, սպանելով Այդընօղլու Մուստաֆա բեյին, անցավ բեյության գլուխ։ Այսպիսով, Այդընի երկիրը ծնվեց որպես Կեղծ Մուստաֆայի ճգնաժամի ընթացքում օսմանյան կառավարումից դուրս եկած երկիր։", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Ջյունեյդ բեյի և նրա ընտանիքի մահապատիժը. Այդընօղուլների բեյության վախճանը", "efa684ba"], "d": ["Այդընի երկրում կրկին իշխանություն ձեռք բերած Ջյունեյդ բեյը գրգռում էր Անատոլիայի բեյերին և կապ էր փնտրում Վենետիկի հետ. դրա պատճառով Մուրադ II-ը նրա դեմ ուղարկեց Անատոլիայի բեյլերբեյ Համզա բեյին։ Երբ նրա որդի Կուրդ Հասանը Ակհիսարի մոտ պարտվեց և գերի ընկավ, Ջյունեյդը նահանջեց Սամոս կղզու դիմաց գտնվող Իփսիլի. Կարամանօղլուից սպասած օգնությունը չգալուց և օսմանցիների հետ գործող ջենովացիների կողմից ծովից շրջափակվելուց հետո նա ստիպված եղավ անձնատուր լինել և իր ողջ տոհմով վերացվեց։ Այսպիսով, Այդընօղուլների հողերն ամբողջությամբ անցան օսմանյան կառավարման տակ։", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Էրզրումը և Վանի գոգավորությունը անցան Սեֆյաններին. փլուզվեց Ակ-Կոյունլուների հյուսիսային թևը", "b418875f"], "d": ["Շարուրում Էլվենդ բեյին հաղթած և 1501 թ. ամռանը Թավրիզ մտած Շահ Իսմայիլը հաջորդ տարի, առաջանալով հյուսիս-արևմտյան ուղղությամբ, իր տիրապետության տակ առավ Էրզրումից մինչև Վանա լճի գոգավորությունը ձգվող գիծը։ Ակ-Կոյունլու պետությունը Ուզուն Հասանի մահից հետո արդեն գահակալական կռիվներով բաժանվել էր երկուսի. Էլվենդ բեյը պահում էր Ատրպատականը և Դիարբեքիրը, իսկ նրա հորեղբորորդի Մուրադը՝ Պարսկական Իրաքը և Ֆարսը։ Այս բաժանումը հեշտացրեց սեֆյան առաջխաղացումը. շրջանը տասը գրառման չափով մեկ տարում ձեռքից ձեռք անցավ։ Էրզրումը դրանից հետո տասնվեց տարի մնաց սեֆյան ձեռքում և օսմանյան տիրապետության տակ անցավ միայն Չալդըրանից հետո՝ 1518-19 թթ.։ Այդ տարում (1502) Աշկալեն և Բասենը (Հասանկալե), Էրզրումի շրջանի հետ միասին, Ակ-Կոյունլուներից անցան Սեֆյաններին (օրը հաստատված չէ)։", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Մուրադ բեյի պարտությունը Համադանում. Պարսկական Իրաքը և Ֆարսը անցան Սեֆյաններին", "8de07a31"], "d": ["Ակ-Կոյունլու գահի երկրորդ հավակնորդ Սուլթան Մուրադը Համադանի մոտ Շահ Իսմայիլի դեմ տեղի ունեցած ճակատամարտում ծանր պարտություն կրեց և փախավ Բաղդադ։ Այս մեկ ճակատամարտով Պարսկական Իրաքը, Ֆարսը և Քերմանի շրջանները անցան սեֆյան կառավարման տակ. քարտեզում այս շրջանները միաժամանակ ձեռքից ձեռք են անցնում։ Սա Ակ-Կոյունլու պետության կազմալուծման ամենամեծ միակ քայլն է. Թավրիզի կորուստը հարստությունը թողել էր առանց մայրաքաղաքի, իսկ Համադանի պարտությունը՝ առանց հողի։", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Շահ Իսմայիլը մտավ Յազդ. ընկավ Ակ Կոյունլուների մնացորդի վերջին ամրոցը Կենտրոնական Իրանում", "6f9835df"], "d": ["Թեև 1503 թ. Համադանի պարտությունից հետո Իրաք-ի Աջեմն ու Ֆարսն անցել էին Սեֆյաններին, Յազդը դեռ առանձին մնում էր Ակ Կոյունլու հարստությունից սերած Բայընդըրլը Մուրադ բեյի ձեռքին։ Քաղաքն ընկավ մեկամսյա պաշարումից հետո, և փակվեց Կենտրոնական Իրանում Ակ Կոյունլուների վերջին կղզյակը։ TDV-ի գրառումը. «Շահ Իսմայիլը մեկամսյա պաշարումից հետո քաղաք մտավ հիջ. 910 թ. Ջումադա աս-սանիյա ամսի 28-ին (1504 թ. դեկտեմբերի 6)»։", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Շահ Իսմայիլի Դիարբեքիրի արշավանքը. ընկան Ակ Կոյունլուների վերջին կենտրոնները", "b6d8504e"], "d": ["Ատրպատականն ու Իրանական սարահարթը գրաված Շահ Իսմայիլը 1507 թ. ուղղվեց դեպի արևմուտք՝ Դիարբեքիրի շրջան, որտեղ ծնվել էր Ակ Կոյունլու հարստությունը։ Ամիդից Մարդին և Ուրֆայից Խարբերդ ձգվող գիծը երկու հարվածով անցավ սեֆյան կառավարման տակ, և Ակ Կոյունլուները փաստացի վերացան։ Այս արշավանքը միաժամանակ առաջին անգամ սեֆյան սահմանը հասցրեց օսմանյան և մամլուքյան սահմաններին. այդպես ձևավորվեց դեպի Չալդըրան տանող լարվածության աշխարհագրական հիմքը։", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Բաղդադն անցավ Սեֆյաններին. Իրաք-ի Արաբը ձեռքից ձեռք անցավ", "39730186"], "d": ["Համադանի պարտությունից հետո Բաղդադում ապաստանած Ակ Կոյունլու սուլթան Մուրադի հետևից Շահ Իսմայիլը 1508 թ. մտավ Իրաք-ի Արաբ և գրավեց Բաղդադը։ Քարբալայի և Նաջաֆի սրբավայր-դամբարանների անցումը սեֆյան կառավարման տակ շարժման կրոնադավանական հավակնության տեսանկյունից նույնքան կարևոր էր, որքան Թավրիզի գրավումը։ Քարտեզում Իրաք-ի Արաբը ձեռքից ձեռք է անցնում նույն օրը. սա փլուզման վերջին և աշխարհագրորեն ամենալայն քայլն է։ Բաղդադը Սեֆյանների ձեռքին մնաց մինչև 1534 թ.՝ Կանունի Սուլեյմանի «երկու Իրաքների» արշավանքը։", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Մերվի ճակատամարտը. ուզբեկները ծանր պարտություն կրեցին, գրավվեցին Մերվն ու Հերաթը", "f8e45aaf"], "d": ["Արևմուտքում Ակ Կոյունլուների ժառանգությունն ամբողջացրած Շահ Իսմայիլը շարժվեց արևելք՝ Խորասան, և Մերվի մատույցներում ծանր պարտության մատնեց ուզբեկներին. Շեյբանի խանը զոհվեց ռազմադաշտում։ Մերվն ու Հերաթն անցան սեֆյան տիրապետության տակ, և Սեֆյան պետությունը հասավ Եփրատից մինչև Ամու Դարիա ձգվող սահմաններին։ Այսպիսով, 1501 թ. ամռանը Թավրիզ մտնելով սկսված ընթացքն ավարտվեց ինը տարում. Ակ Կոյունլուների ժառանգությունն ամբողջությամբ անցավ սեֆյան կառավարման տակ, և Օսմանյան պետությունն արևելքում հարևան դարձավ իր չափի երկրորդ պետությանը։", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Զաբիդի վերջնական անցումը օսմանյան տիրապետության տակ", "ddd971c7"], "d": ["1538 թ. նոյեմբերի 5-ին Դիուի պաշարումը վերացրած նավատորմը վերադարձի ճանապարհին կանգ առավ Եմենի ափին, և Զաբիդը վերջնականապես կապվեց օսմանյան կառավարմանը. Հադըմ Սուլեյման փաշան քաղաքից մեկնեց 1539 թ. մարտի 10-ին և ապրիլի 1-ին հասավ Ջիդդա։ 1517 թվականից քաղաքը Օսմանյան պետության անունից կառավարում էին նախկին մամլուք բեյերը. այս թվականից այն անցավ ուղղակի կառավարման տակ։", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Իբերիական միություն. Պորտուգալիայի թագն անցավ Իսպանիայի թագավորին", "1cc6dfdc"], "d": ["Կարդինալ-թագավոր Էնրիկեի անժառանգ մահով բացված գահաժառանգության վեճը Ալկանտարայի ճակատամարտում (1580 թ. օգոստոսի 25) վերջացավ հօգուտ Իսպանիայի, և Տոմարում հավաքված Պորտուգալիայի կորտեսը 1581 թ. ապրիլի 16-ին Ֆիլիպ II-ին ճանաչեց Պորտուգալիայի թագավոր։ Տոմարի պայմանների համաձայն՝ Պորտուգալիան պահպանելու էր իր հաստատությունները, դրամն ու լեզուն, կառավարման պաշտոններում նշանակվելու էին միայն պորտուգալացիներ, իսկ Մադրիդում լինելու էր առանձին Պորտուգալական խորհուրդ. այսինքն՝ միավորումը անձնական ունիա էր, ոչ թե բռնակցում։", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Վերականգնում (Restauração). Պորտուգալիան վերականգնեց իր անկախությունը", "64ec0738"], "d": ["Այն օրերին, երբ Կատալոնիայի ապստամբությունը զբաղեցնում էր Իսպանիային, Լիսաբոնում մի խումբ ազնվականներ, հարձակվելով պալատի վրա, տապալեցին իսպանական կառավարումը և Բրագանսայի դուքսին Ժուան IV անունով թագավոր հռչակեցին։ Այսպես ավարտվեց վաթսուն տարի տևած Իբերիական միությունը. սակայն Սեուտան ընտրեց մնալ Իսպանիայի կազմում, և դա ճանաչվեց 1668 թ. Լիսաբոնի պայմանագրով։ Այս ժամանակահատվածը, երբ Պորտուգալիան ներքաշված էր Հաբսբուրգների պատերազմների մեջ, նաև Ասիայում նրա կորուստների շրջանակն է. Որմուզը կորսվեց 1622 թ., Մալաքան՝ 1641 թ., Կոլոմբոն՝ 1656 թ., իսկ Տանժերն ու Բոմբեյը, որպես անկախության գին, տրվեցին Անգլիային։ Աղբյուր՝ Britannica, History of Portugal — Restoration։", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Տանժերը հանձնվեց Անգլիային", "1f7cad6d"], "d": ["Պորտուգալիայի անկախության պատերազմում անգլիական աջակցությունն ապահովելու համար կնքված ամուսնական պայմանագրի (1661 թ. հունիսի 23) երկրորդ հոդվածով Տանժերը որպես Եկատերինա Բրագանսացու օժիտ անցնում էր Անգլիային։ Սենդվիչի կոմսի նավատորմը խարիսխ գցեց 1662 թ. հունվարի 29-ին, և հաջորդ օրը Պիտերբորոյի կոմսի ղեկավարած արարողությամբ կատարվեց պաշտոնական հանձնումը։ Անգլիացիները քաղաքը լքելու էին 1684 թ.։", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Նադիր շահի սպանությունը. Աֆշարների իշխանության քայքայումը", "19c218c0"], "d": ["Սեֆյան գահին վերջ դրած և 1736 թ. իր անունով թագավորություն հռչակած, հնդկական արշավանքով մինչև Դելի հասած, Օսմանյան պետության դեմ երեք պատերազմ մղած և 1746 թ. Քերդենի պայմանագրով հաշտություն կնքած Նադիր շահը իր վրանում սպանվեց սեփական թիկնապահների ձեռքով։ Դրանից հետո Իրանն այլևս հնարավոր չեղավ կառավարել մեկ կենտրոնից. քառասունինը տարի երկիրը բաժանված էր Խորասանում Աֆշարների մնացորդի, հարավում Զենդերի և հյուսիսում վերելք ապրող Ղաջարների միջև։ Օսմանյան արևելյան սահմանն այս մասնատվածության շնորհիվ երկար ժամանակ հանգիստ մնաց։ Նադիր շահը սպանվեց 1747 թ. հունիսի 20-ին. ըստ TDV-ի՝ Երևանի խանությունը հիմնվեց նույն տարում (1747), օրը հաստատված չէ։", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Ղաջար հարստության հաստատվելը Իրանի վրա", "744b48c5"], "d": ["Ղաջար ցեղի առաջնորդ Աղա Մուհամմեդ խանը, տապալելով Զենդերի իշխանությունը և կոտրելով նաև Խորասանում Աֆշարների վերջին դիմադրությունը, Իրանը կրկին միավորեց մեկ իշխանության ներքո և Թեհրանը դարձրեց մայրաքաղաք։ Այսպես փակվեց քառասունինը տարի տևած մասնատվածության շրջանը. այսուհետ մինչև 1923 թ. Օսմանյան պետության արևելյան հարևանը լինելու էր Ղաջարների Իրանը։ Մաշհադում, ըստ TDV İslâm Ansiklopedisi-ի, 1796 թ. Աղա Մուհամմեդ շահին դիմավորեց Աֆշար տիրակալ Շահռուխը, և քաղաքն անցավ Ղաջարների տիրապետության տակ (օրը աղբյուրում նշված չէ)։", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ֆերդինանդը գրավեց Բուդան. Սապոյայիին դուրս մղեցին մայրաքաղաքից", "99f77c29"], "d": ["Մոհաչից հետո հունգարական գահին երկու թագավոր հայտնվեց. ազնվականների մի մասն ընտրել էր Յանոշ Սապոյայիին, մյուս մասը՝ Ֆերդինանդ Հաբսբուրգին։ 1527 թ. Ֆերդինանդը գրավեց Բուդան և Սապոյայիին դուրս մղեց մայրաքաղաքից. Սապոյայիը օգնություն խնդրեց սուլթան Սուլեյմանից։ Սա է պատճառը, որ 1529 թ. Վիեննայի արշավանքի առաջին թիրախը Բուդան էր։", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Բարբարոսի արշավանքը Էգեյան կղզիների դեմ. Նաքսոսի դքսությունն անցավ օսմանյան վերահսկողության տակ", "722b2fea"], "d": ["1207 թվականից Վենետիկի խնամակալությամբ լատին դուքսերի կառավարած Նաքսոսի դքսությունը Բարբարոս Հայրեդդին փաշայի կղզիական արշավանքով անցավ օսմանյան վերահսկողության տակ։ Կղզու կարգավիճակին ձեռք չտվեցին. դքսությունը շարունակեց գոյատևել որպես Օսմանյան պետությանը ենթակա, իսկ 1540 թ. օսմանա-վենետիկյան պայմանագրով տիրապետության իրավունքը պաշտոնապես փոխանցվեց օսմանցիներին։", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Խաչակրաց նավատորմը գրավեց Ջերբան. Թուրգութ փաշայի հենակետը ձեռքից գնաց", "f41b3f2a"], "d": ["Իսպանիայի, Պապական պետության, Մալթայի, Ջենովայի և Ֆլորենցիայի նավերից կազմված խաչակրաց նավատորմը թիրախ դարձրեց Ջերբան, որը Թուրգութ ռեիսը 1551 թվականից օգտագործում էր որպես ասպատակությունների հենակետ։ Փոթորիկների և համաճարակի պատճառով նավատորմը կղզու մատույցներ կարողացավ հասնել միայն 1560 թ. սկզբին. 1560 թ. մարտի 12-ին այն գրավեց կղզին և բերդ կառուցեց։ Լուրն առնելով՝ Փիյալե փաշան մարտի 28-ին 120 գալերայից կազմված նավատորմով դուրս եկավ Ստամբուլից։ Գրավումը երկար չտևեց. օսմանյան նավատորմը մայիսին Ջերբայի առջև հաղթեց դաշնակիցներին, իսկ բերդը հետ առնվեց հուլիսի վերջին։ Այս արշավանքը Պրևեզայից հետո Միջերկրական ծովում օսմանյան գերակշռությունն ամրապնդած երկրորդ խոշոր ծովային գործողության սկիզբն է։", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Ջերբայի բերդի անկումը. կղզին անցավ օսմանյան կառավարման տակ", "f1efc0df"], "d": ["1560 թ. մայիսի 14-ին Փիյալե փաշայի ծովային հաղթանակից հետո խաչակրաց ուժերը փակվեցին կղզում իրենց կառուցած բերդում. Տրիպոլիի (Լիբիա) բեյլերբեյ Թուրգութ փաշայի ուժերը այն պաշարեցին ցամաքից։ Երկու ամիս տևած պաշարումն ավարտվեց 1560 թ. հուլիսի 30-ին բերդի անկմամբ, և կղզին կապվեց Տրիպոլիի բեյլերբեյությանը։ Ծովային հաղթանակի և բերդի գրավման միջև յոթանասունյոթ օր կա. կղզին փաստացի ձեռքից ձեռք անցավ ոչ թե մայիսի 14-ին, այլ հուլիսի 30-ին։", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Դանցիգում ավարտվեց ռուս-պրուսական երկիշխանությունը. Նապոլեոնի ազատ քաղաքը վերադարձավ Պրուսիային", "1ccda4d2"], "d": ["Թիլզիտի հաշտությամբ (1807 թ. հուլիսի 9) Պրուսիայից անջատված և ֆրանսիական հովանավորության տակ ազատ քաղաք դարձած Դանցիգը Նապոլեոնի ուժերը լքեցին 1813 թ. պաշարումից հետո։ 1814 թ. հունվարի 2-ից փետրվարի 4-ը քաղաքում տևեց ռուս-պրուսական երկիշխանությունը. երբ Ալեքսանդր ցարը հրաժարվեց Դանցիգն ու Վիստուլայի գետաբերանը վերցնելու ծրագրից, քաղաքն անցավ պրուսական կառավարման տակ։", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["Վիեննայում Կրակովը հռչակվեց ազատ, անկախ և չեզոք քաղաք", "19eea839"], "d": ["Վիեննայի վեհաժողովում Ռուսաստանը, Ավստրիան և Պրուսիան Կրակով քաղաքն իր շրջակայքով դարձրին ազատ պետություն՝ երեք տերությունների պաշտպանության ներքո. Վիեննայի եզրափակիչ ակտն ամրագրեց այս կարգը։", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Բորնուն անցավ Ռաբիհ իբն Զուբեյրի տիրապետության տակ", "8be4ca96"], "d": ["Բագիրմին և Վադաին ցնցած սուդանցի զորավար Ռաբիհ իբն Զուբեյրը գրավեց Բորնուն. մինչև 1896 թ. նա տիրեց ամբողջ երկրին և Դիկվան դարձրեց իր կենտրոնը։", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Ռաբիհ իբն Զուբեյրը պարտվեց ֆրանսիացիներին և սպանվեց. Բորնուում նրա իշխանությունը քայքայվեց", "fb5a3ace"], "d": ["Ֆրանսիական գաղութային բանակից պարտված Ռաբիհը սպանվեց. նրա որդին թեև ցանկացավ շարունակել իշխանությունը, չկարողացավ դիմանալ, և 1902 թ. Բորնուն բաժանվեց Ֆրանսիայի, Անգլիայի և Գերմանիայի միջև։", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Հռչակվեց Արևմտյան Թրակիայի ժամանակավոր կառավարությունը՝ Կոմոտինի կենտրոնով", "974b2e28"], "d": ["Երբ Բուխարեստի պայմանագիրը (1913 թ. օգոստոսի 10) Արևմտյան Թրակիան թողեց Բուլղարիային, շրջանի թուրք բնակչությունը հռչակեց Կոմոտինի կենտրոնով ժամանակավոր կառավարություն. Ալեքսանդրուպոլիսի (Դեդեաղաչի) գրավումից հետո կառավարությունն իր անկախությունն ազդարարեց «Արևմտյան Թրակիայի անկախ կառավարություն» անունով։ Մեծ տերությունների միջամտության հետևանքով օսմանյան կառավարությունը նրան չաջակցեց. 1913 թ. սեպտեմբերի 29-ի Կոստանդնուպոլսի պայմանագիրը Արևմտյան Թրակիան թողեց բուլղարներին, և կառավարությունը մինչև 1913 թ. հոկտեմբերի 25-ը գոյատևեց ընդամենը հիսունյոթ օր։", "86d3bfee"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Պորտուգալիան գրավեց Արզիլան. երկրորդ հենակետը Մարոկկոյի ափին", "83444a11"], "d": ["Աֆոնսու V-ը 30.000 հոգանոց ուժով և 400 նավից բաղկացած նավատորմով անձամբ ափ իջավ Մարոկկոյում և 1471 թ. օգոստոսի 24-ին գրավեց Վատասյանների կառավարման տակ գտնվող Արզիլան։ Քաղաքի անկումը կոտրեց Տանժերի դիմադրությունը. չորս օր անց՝ օգոստոսի 28-ին, Տանժերը հանձնվեց առանց կռվի։ Այսպիսով Պորտուգալիան Սեուտայից (1415) և Կասր աս-Սղիրից (1458) հետո Մարոկկոյի Ատլանտյան ափին հաստատեց իր երրորդ և չորրորդ դիրքերը. այս արշավանքից հետո թագավորն իր տիտղոսին ավելացրեց «Աֆրիկայի տիրակալ» արտահայտությունը։", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Սաֆիի անցումը պորտուգալական ազդեցության տակ", "765e703e"], "d": ["Ատլանտյան ափի հացահատիկի և ձկնորսության ամենաբանուկ նավահանգիստ Սաֆին 1488 թ. անցավ պորտուգալական ազդեցության տակ. որոշ ժամանակ քաղաքը կառավարվեց տեղացի իշխանավորների ձեռքով՝ պորտուգալական հովանավորության ներքո, իսկ 1508 թ. ուղղակիորեն գրավվեց։ Քանի որ աղբյուրներն այս երկու փուլին տարբեր կշիռ են տալիս, սկզբի թվականը տատանվում է 1488 և 1508 թվականների միջև. երկուսն էլ նույն ընթացքի ծայրակետերն են։ Սաֆին հիսուներեք տարի մնաց Պորտուգալիայի ձեռքին և դատարկվեց 1541 թ.՝ Ագադիրի անկումից հետո։", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Santa Cruz do Cabo de Gué-ի հիմնումը. պորտուգալական բերդը Ագադիրում", "cc22c433"], "d": ["Սուսի ափին, մի կետում, ուր մինչ այդ Պորտուգալիան չէր հասել, մասնավոր նախաձեռնությամբ հիմնված Santa Cruz do Cabo de Gué բերդը կառուցվեց 1505 թ. և 1513 թ. փոխանցվեց Պորտուգալիայի թագին։ Վերահսկելով Սուսի հովտի շաքարի և ոսկու առևտուրը՝ բերդը փակում էր Մարաքեշի հարավարևմտյան ելքը. ուստի այն դարձավ Սաադյան շարժման առաջին խոշոր թիրախը։ 1533 թ. պաշարումը ետ մղվեց, իսկ 1541 թ. պաշարումը հաջողության հասավ և սկիզբ դրեց Մարոկկոյում Պորտուգալիայի փլուզմանը։", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Ազեմմուրի գրավումը. Ումմ ար-Ռաբիի գետաբերանի վերահսկողությունը", "232acd4b"], "d": ["Բրագանսայի դուքս Ժայմեի հրամանատարությամբ պորտուգալական բանակը 1513 թ. սեպտեմբերի 3-ին առանց դիմադրության մտավ Ումմ ար-Ռաբի գետի գետաբերանի մոտ գտնվող Ազեմմուր։ Քաղաքի գրավումը ապահովեց ինչպես գետաբերանի, այնպես էլ դեպի ներքին շրջաններ տանող հացահատիկի ճանապարհի վերահսկողությունը և հաջորդ տարի ճանապարհ բացեց նրանից 12 կմ հարավ-արևմուտք Մազագան բերդի հիմնման համար։ Ազեմմուրը քսանութ տարի մնաց Պորտուգալիայի ձեռքին։", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Մազագան բերդի հիմնումը. պորտուգալական դիրքը, որ ամենաերկարը կմնա Մարոկկոյում", "786cdb40"], "d": ["Ազեմմուրի գրավման հաջորդ տարի՝ 1514 թ. ամռանը, ափին կառուցվեց Մազագանի ամրոցը։ 1541 թ. ընդհանուր փլուզումից հետո Պորտուգալիան, լքելով Մարոկկոյում իր բոլոր դիրքերը, Մազագանը չլքեց. ընդհակառակը, բերդը հիմքից վերակառուցել տվեց իտալական ոճի բաստիոններով, և քաղաքը պահվեց երկու հարյուր հիսունհինգ տարի։ 1562 թ. մեծ պաշարումն էլ ետ մղվեց։ Մազագանը՝ Մարոկկոյում Պորտուգալիայի վերջին դիրքը, դատարկվելու էր 1769 թ.։", "fe42a1e2"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Ագադիրի անկումը. սկսվում է Սաադյանների կողմից Պորտուգալիայի արտամղումը Մարոկկոյից", "bb1568f6"], "d": ["Սաադյան սուլթան Մուհամմեդ աշ-Շեյխը 1541 թ. փետրվարի 16-ին պաշարեց Սանտա Կրուզ բերդը և մարտի 12-ին գրավեց այն. գերի ընկան մոտ վեց հարյուր պորտուգալացի, այդ թվում կուսակալ Գուտերե դե Մոնրոյը։", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Սաֆիի և Ազեմմուրի դատարկումը. Պորտուգալիան նահանջում է Ատլանտյան ափից", "4cb6099a"], "d": ["1541 թ. մարտի 12-ին Ագադիրի անկման և Մարոկկոյի սուլթանի հետ հուսացած դաշինքը չկայանալու պատճառով Ժուան III-ը հրամայեց դատարկել Ատլանտյան ափի երկու խոշոր դիրքերը. Սաֆիի և Ազեմմուրի տարհանումն ավարտվեց 1541 թ. աշնանը՝ սեպտեմբեր-հոկտեմբեր ամիսներին։ Այսպիսով մեկ տարվա ընթացքում ձեռքից գնաց երեք դիրք, և Մարոկկոյի ափին Պորտուգալիայի հիսնամյա ընդարձակումը շրջվեց հակառակ ուղղությամբ. մնացին Սեուտան, Տանժերը, Արզիլան, Կասր աս-Սղիրը և նոր ամրացված Մազագանը։", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Արզիլայի դատարկումը. Պորտուգալիան նեղացնում է իր ներկայությունը հյուսիսային ափին", "b5d18373"], "d": ["Ֆինանսական ճգնաժամի և Սաադյանների ճնշման միաժամանակյա ազդեցությամբ Ժուան III-ը դատարկեց 1471 թվականից պահվող Արզիլան։ Այսպիսով Մարոկկոյում Պորտուգալիայի ներկայությունը սահմանափակվեց Սեուտայով, Տանժերով և Մազագանով։ 1577 թ. Արզիլան կարճ ժամանակով կրկին գրավվելու էր, իսկ 1589 թ. վերջնականապես լքվելու էր։", "36c1d8e6"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Ուլուջ Ալի փաշան վերցրեց Թունիսը. Հաֆսյան-իսպանական կարգի վերջը", "d4498698"], "d": ["Երբ 1535 թ. Կարլոս V-ը գրավեց Թունիսը, նա քաղաքն ինքը չկառավարեց, այլ Հաֆսյան սուլթան Մևլայ Հասանին կրկին նստեցրեց գահին. TDV-ի ձևակերպմամբ՝ Թունիս քաղաքը «մինչև 1569 թ. օսմանցիների երկրորդ միջամտությունը» մնաց «իսպանացիների հովանավորության ներքո և Մևլայ Ահմեդ III-ի կառավարման տակ»։ 1568 թ. հունիսի 27-ին Ալժիրի բեյլերբեյ նշանակված Ուլուջ Ալին ցամաքով շարժվեց Թունիսի վրա, Բեջայում հաղթեց Հաֆսյան սուլթանին և մտավ քաղաք. Մևլայ Ահմեդն ապաստանեց իսպանական Գուլետ (Հալկ ալ-Վադի) պրեսիդիոյում։ Այսպիսով ծովածոցը բաժանվեց երկու մասի՝ քաղաքը օսմանյան, նավահանգստի բերդը՝ իսպանական, և այս բաժանումը տևեց չորս տարի։", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Դոն Խուան Ավստրիացին վերագրավեց Թունիսը. Լեպանտոյի միակ արձագանքը ցամաքում", "a6f044ee"], "d": ["Թեև Լեպանտոյից (1571) հետո Սրբազան դաշինքը քայքայվել էր, Իսպանիան միայնակ ճնշում գործադրեց Հյուսիսային Աֆրիկայի վրա. TDV-ի ձևակերպմամբ՝ «1573 թ. հոկտեմբերի 10-ին իսպանացիները Թունիսում վերահսկողություն հաստատելու նպատակով նոր գործողություն ձեռնարկեցին։ Գրավեցին Թունիսը և այնտեղ թողեցին 8000 զինվոր»։ Դոն Խուան Ավստրիացու հրամանատարությամբ այս գործողությունը միակ տեղն է, որտեղ Լեպանտոյի հաղթանակը արձագանք գտավ ցամաքում. սակայն այն կայուն չեղավ, և տասնմեկ ամիս անց քաղաքը հետ առնվեց։ Գրավման տապալածը արդեն հաստատված օսմանյան կառավարումն էր. հիջ. 980 թ. Զու-լ-հիջջա ամսի 2-ին (1573 թ. ապրիլի 5) Թունիսի հրամանատարը Քըլըչ Ալի փաշան էր, կայմակամը՝ Ռամազան փաշան, բեյլերբեյը՝ Հայդար փաշան։", "f7f9ab56"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Մազագանի դատարկումը. ընկավ Պորտուգալիայի վերջին դիրքը Մարոկկոյում", "f9e9749d"], "d": ["Ալավյան սուլթան Մուհամմեդ III իբն Աբդալլահի 1769 թ. սկզբին սկսած պաշարման դեմ 592 հոգանոց կայազորը չկարողացավ դիմանալ. փետրվարի 1-ին Լիսաբոնից դուրս եկած տարհանման նավատորմը 1769 թ. մարտի 11-ին նավ բարձրացրեց վերջին զինվորներին, իսկ քաղաքը վերջինը լքեց կուսակալ Դինիշ Գրեգորիոն։ Այսպիսով 1415 թ. Սեուտայի գրավմամբ սկսված Պորտուգալիայի ներկայությունը Մարոկկոյում ավարտվեց երեքուկես դար անց։ Մազագանը 1541 թ. ընդհանուր փլուզումից հետո պահված միակ դիրքն էր Ատլանտյան ափին և իր երկու հարյուր հիսունհինգ տարով դարձավ Մարոկկոյում Պորտուգալիայի ամենաերկար պահած վայրը։", "c0ad57bc"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Օսմանյան առաջին ակչեի հատումը", "38d2d638"], "d": ["Օրհան Ղազիի անունով հատված առաջին արծաթե ակչեն բեյլիքի անկախ գերիշխանության դրամական հռչակումն է. ակչեն հինգ դար մնաց որպես հիմնական դրամական միավոր։", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Հիմնվեց Ռումելիի բեյլերբեյությունը", "ffa16089"], "d": ["Եվրոպական ափի նվաճումները հավաքվեցին մեկ ռազմավարչական տանիքի տակ. բեյլերբեյությունների կարգը դարձավ կայսրության գավառական վարչական կազմակերպության ողնաշարը։", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Յըլդըրըմ Բայազիդ – Դեսպինա խաթուն ամուսնությունը", "4b10dc6c"], "d": ["Կոսովոյից հետո Սերբական դեսպոտության հետ հաստատված վասալությունը կնքվեց Լազարի դստեր Օլիվերայի՝ Բայազիդի հետ ամուսնությամբ. վաղ շրջանի ամուսնական դիվանագիտության բնորոշ օրինակ։", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Հիմնվեց Անատոլիայի բեյլերբեյությունը", "5ef8d3a7"], "d": ["Բռնակցված բեյլիքների հողերի կառավարման համար կազմակերպվեց Անատոլիայի բեյլերբեյությունը. ամբողջացավ Ռումելի-Անատոլիա երկթև վարչական կարգը։", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Ավարտվեց Բուրսայի Ուլու մզկիթը", "27bcc4a5"], "d": ["Նիկոպոլիսի ավարով կառուցված քսան գմբեթով մեծ մզկիթը վաղ օսմանյան ճարտարապետության մոնումենտալ օրինակն է և գեղագրության արվեստի բաց թանգարանը։", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Չանդարլը Հալիլ փաշայի պաշտոնազրկումը և մահապատիժը", "5e19438f"], "d": ["Նվաճումից հետո մահապատժի ենթարկվեց պաշարման նկատմամբ զսպվածություն ցուցաբերած հինավուրց Չանդարլը ընտանիքից սերող մեծ վեզիրը. առաջին անգամ մեծ վեզիրը սպանվում էր փադիշահի հրամանով, բացվում էր դևշիրմե ծագմամբ վեզիրների դարաշրջանը։", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Մոլդովայի խարաջատու դառնալը", "25bd3693"], "d": ["Մոլդովայի վոյևոդությունը համաձայնեց խարաջ վճարել. Վալախիայի և Տրանսիլվանիայի հետ միասին Դանուբից հյուսիս եռակի վասալական գոտին դարձավ կայսրության հյուսիսային բուֆերը։ Նույն ամսաթվին միացած այլ վայրեր՝ Յասսի։", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Դուբրովնիկի (Ռագուզա) խարաջը", "d127c78a"], "d": ["Վաճառական հանրապետություն Ռագուզան խարաջի դիմաց երաշխավորեց իր ինքնավարությունն ու առևտրային արտոնությունները. որպես Ադրիատիկ ծովում օսմանյան պատուհան՝ հարստացավ։ Հանրապետության հողը եղած Մլյետ կղզին (Mljet) ևս կիսում էր այս կարգավիճակը։", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Վալախիայի արշավանքը՝ Ցցահանող վոյևոդը", "fd4530bb"], "d": ["Խարաջ վճարել մերժած և դեսպաններին սպանած Վլադ Ցեպեշի դեմ կազմակերպված արշավանքով Վալախիան վերադարձվեց վասալության. գիշերային հարձակումն ու ցցահանման սարսափելի տեսարանները Եվրոպայում դարձան լեգենդ։ Նույն ամսաթվին միացած այլ վայրեր՝ Բուխարեստ։", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Բացվեց Ֆաթիհի համալիրը", "a150ea55"], "d": ["Իր ութ մեդրեսեներով (Սահն-ը Սեման) համալիրը Ստամբուլը իսլամական աշխարհի գիտական կենտրոնի վերածելու ծրագրի առաջին մեծ քայլն էր։", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ալի Քուշչուն Ստամբուլում", "8508229d"], "d": ["Սամարղանդի աստղադիտարանի վերջին մեծ ներկայացուցիչ Ալի Քուշչուն Ֆաթիհի հրավերով դարձավ Այա Սոֆիայի մեդրեսեի դասախոս (մյուդեռիս). Ստամբուլում հիմնեց մաթեմատիկա-աստղագիտության ավանդույթը։", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Ֆաթիհի կանունամեն", "b08944c9"], "d": ["Պետական կառույցը, արարողակարգը և պատիժները ամփոփող առաջին ընդգրկուն սովորութային կանունամեն. «աշխարհի կարգի համար» եղբայրասպանությունը թույլատրող իր հայտնի հոդվածով մինչև այսօր վիճարկվում է։", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Հատվեց առաջին օսմանյան ոսկեդրամը (սուլթանի)", "2fd5c0dd"], "d": ["Հատվեց վենետիկյան դուկատին համարժեք առաջին օսմանյան ոսկեդրամը. կայսրության ֆինանսները միացան միջազգային դրամական կարգին։", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Տեղափոխություն Թոփքափի պալատ", "b9cd6a5e"], "d": ["Նոր պալատի (Թոփքափի) ավարտով պետական կառավարման կենտրոնը տեղափոխվեց այստեղ. պալատը չորս դար մնաց որպես կայսրության ուղեղը։", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Ֆլորենցիայի Հանրապետությունը վերածվեց դքսության — Ալեսանդրո դե Մեդիչի", "c08764e1"], "d": ["Պապ Կլեմենտ VII-ի ճնշմամբ Ֆլորենցիայի կառավարող հանձնաժողովը (Balìa) ընդունեց նոր սահմանադրություն. հնգադարյա հանրապետական կարգը վերացավ, Ալեսանդրո դե Մեդիչին հռչակվեց ժառանգական դուքս և մայիսի 1-ին փաստացի գահ բարձրացավ։ Այսպիսով Ֆլորենցիան անկախ քաղաք-հանրապետությունից վերածվեց Մեդիչի հարստության ժառանգական դքսության։", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Քանունի – Հյուրեմ Սուլթան ամուսնությունը", "abc05f26"], "d": ["Քանունիի՝ Հյուրեմի հետ պաշտոնական ամուսնությունը արմատապես փոխեց պալատական ավանդույթը. ծնվեց «Հասեքի սուլթան» հաստատությունը, և հարստության քաղաքականության մեջ բացվեց կանանց դարաշրջանի դուռը։", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Առաջին ընդգրկուն կապիտուլյացիաները Ֆրանսիային", "e2264e48"], "d": ["Որպես հաբսբուրգյան սեղմման դեմ ֆրանսիական դաշինքի մաս՝ Ժան դը լա Ֆորեի և Մաքբուլ Իբրահիմ փաշայի միջև ստորագրվեցին առևտրային արտոնություններ. այն ժամանակ դիվանագիտական միջոց եղած կապիտուլյացիաները դարերի ընթացքում վերածվելու էին ֆինանսական կախվածության դռան։", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Հնդկական օվկիանոսի արշավանքը՝ Դիուի պաշարումը", "fcd1217a"], "d": ["Սուեզից դուրս եկած նավատորմը անցավ Կարմիր ծովը և պաշարեց Գուջարաթի Դիուն. թեև ամրոցը չգրավվեց, օսմանյան ուժն առաջին անգամ հասավ Հնդկական օվկիանոս, և պորտուգալական մենաշնորհը խարխլվեց։", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Սեյդի Ալի Ռեիսի հնդկական ճանապարհորդությունը", "e5da3b2c"], "d": ["Բասրայի նավատորմը Եգիպտոս բերելու հանձնարարություն ստացած Սեյդի Ալի Ռեիսը փոթորիկների հետևանքով քշվեց Հնդկաստան. վերադարձի արկածները պատմող «Միրաթ ալ-մամալիք»-ը օսմանյան առաջին ուղեգրություններից է։", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Պիրի Ռեիսի մահապատիժը", "63026444"], "d": ["Հորմուզի արշավանքից նավատորմը Բասրայում թողած և վերադարձած մեծ ծովագնաց-քարտեզագիրը 84 տարեկանում մահապատժի ենթարկվեց. մեր գիտության պատմության ամենավիճելի որոշումներից մեկը։", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Բացվեց Սուլեյմանիե համալիրը", "1c6458b2"], "d": ["Ճարտարապետ Սինանի՝ «իմ ենթավարպետության գործը» անվանած համալիրը իր մեդրեսեներով, հիվանդանոցով և գրադարանով դարձավ դասական շրջանի ամենամեծ կրթաբարեգործական համալիրը։", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Մալթայի պաշարումը", "f57f6a85"], "d": ["Միջերկրական ծովի բանալի Մալթան չորս ամիս պաշարվեց. Թուրգութ Ռեիսը նահատակվեց, պաշարումը վերացվեց։ Սա դարձավ Քանունիի շրջանի ծովագնացության առաջին մեծ հետընթացը։", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Ավարտվեց Սելիմիե մզկիթը", "3b0484e1"], "d": ["Սինանի՝ «իմ վարպետության գործը» անվանած Սելիմիեն, որտեղ մեկ գմբեթը տիրում է տարածքին, համարվում է օսմանյան դասական ճարտարապետության գագաթնակետը (ՅՈՒՆԵՍԿՕ-ի համաշխարհային ժառանգություն)։", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Հիմնվեց Ստամբուլի աստղադիտարանը", "169bdf5d"], "d": ["Թաքիյուդդինի՝ ժամանակի ամենալավ սարքավորված դիտարաններից մեկը եղած աստղադիտարանը 1577 թվականի գիսավորից հետո ծագած վեճերի հետևանքով 1580 թվականին քանդվեց. ինստիտուցիոնալ աստղագիտությունը ուշացավ երեք դար։", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Չըլդըրի հաղթանակը — սկսվեց արևելյան պատերազմը", "13125a54"], "d": ["Չըլդըրում Սեֆյան բանակի պարտությամբ բացվեցին Կովկասի դարպասները. գրավվեց Թիֆլիսը, և Վրաստանն անցավ օսմանյան տիրապետության տակ։", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Ջահերի ճակատամարտը — Շիրվանը վերջնականապես օսմանյան է", "3bbc23bc"], "d": ["Քանի որ գիշերը ջահերի լույսով էլ շարունակվեց՝ այս անունով հիշվող ճակատամարտում Սեֆյանները վճռական պարտություն կրեցին. ամրապնդվեց օսմանյան տիրապետությունը Շիրվանում և Բաքվում։", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Մեծ արժեզրկումը — ակչեի ճգնաժամը", "9205c3d4"], "d": ["Երկարատև պատերազմների և ամերիկյան արծաթի ճնշման տակ ակչեի արծաթի պարունակությունը կրճատվեց կիսով չափ. գների հեղափոխությունը սնեց սիփահիական կարգի քայքայումը և ջալալիական խառնակությունը։", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Թավրիզի նվաճումը", "6506bdb9"], "d": ["Սերդար Օզդեմիրօղլու Օսման փաշան մտավ Թավրիզ. Սեֆյանների նախկին մայրաքաղաքն անցավ օսմանյան կառավարման տակ։ Օսման փաշան մի քանի շաբաթ անց մահացավ ռազմակայանում։", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Ֆերհադ փաշայի պայմանագիրը — արևելքում ամենաընդարձակ սահմանները", "c429972f"], "d": ["Շահ Աբբասի դեսպան Հայդար Միրզայի՝ Ստամբուլ գալուց (1590 թվականի հունվարի 18) հետո, այն պայմանով, որ նվաճված վայրերը մնային օսմանցիներին, կնքված և 12-ամյա պատերազմին վերջ դրած պայմանագրով Թավրիզը, Ղարաբաղը, Շիրվանը, Վրաստանը և Լուրիստանը մնացին օսմանցիներին. կայսրությունը արևելքում հասավ իր պատմության ամենաընդարձակ սահմաններին։", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Սկսվեց օսմանա-սեֆյան պատերազմը (1603-1612) — Շահ Աբբասի հակահարձակումը, Թավրիզի կորուստը", "abf27dd8"], "d": ["Իր բանակը վերակազմած Շահ Աբբասը, օգտվելով ջալալիական խառնակություններից, անցավ հարձակման. ընկավ Թավրիզը, կովկասյան ձեռքբերումները մի քանի տարվա ընթացքում ձեռքից գնացին։ Նույն արշավանքում և դրանից հետո ձեռքից դուրս եկած այլ բնակավայրեր՝ Նախիջևան, Խոյ, Մարանդ, Սալմաստ. Ղարաջադաղի (Ahar) և մուքրի բեյերը ևս անցան Սեֆյան կողմը։", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Ծնվեց Էվլիյա Չելեբին", "2b6051ff"], "d": ["Իր ավելի քան հիսուն տարվա ճանապարհորդությունները տասնհատորյա «Սեյահաթնամե»-ում ամփոփած Էվլիյա Չելեբին թողեց 17-րդ դարի օսմանյան աշխարհի եզակի համապատկերը։", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Նասուհ փաշայի պայմանագիրը", "bb69e388"], "d": ["1603 թվականից շարունակվող պատերազմին վերջ դրած պայմանագրով հրաժարվեցին 1590 թվականի ձեռքբերումներից և վերադարձան 1555 թվականի Ամասիայի սահմանին. արևելյան ճակատում հավասարակշռությունը վերականգնվեց։", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Բացվեց Սուլթան Ահմեդի մզկիթը", "e39dfd43"], "d": ["Իր վեց մինարեներով և կապույտ իզնիկյան ջնարակապատ սալիկներով «Կապույտ մզկիթը» դասական շրջանի վերջին մեծ սուլթանական համալիրն է։", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Սուլթան Իբրահիմի սպանությունը", "bc4eb452"], "d": ["Շռայլության և կառավարման ճգնաժամի պատրվակով զորաբանակի և ուլեմաների դաշինքը գահընկեց արեց Իբրահիմին. տասը օր անց ֆեթվայով նրան խեղդամահ արեցին։ Գահ բարձրացավ յոթամյա Մեհմեդ IV-ը. իշխանությունը փաստացի անցավ մեծ վալիդե Քյոսեմ սուլթանի ձեռքը։", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Քյաթիբ Չելեբիի մահը", "e167e89d"], "d": ["«Քեշֆ ազ-զունուն» մատենագիտությամբ և «Ջիհաննումա» աշխարհագրությամբ նա օսմանյան գիտության պատմության գագաթային անունն է. հայտնի է եվրոպական աղբյուրներից օգտվող առաջամարտիկ մոտեցմամբ։", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Էդիրնեի դեպքը — Մուստաֆա II-ի գահազրկումը", "0291c1cd"], "d": ["Փադիշահի՝ Էդիրնեում նստելը և Ֆեյզուլլահ էֆենդիի ազդեցության դեմ զայրույթը վերածվեցին բանակի և արհեստավորների մեծ ապստամբության. շեյխ ուլ-իսլամը ամբոխահարվեց, փադիշահը գահընկեց արվեց, պալատը վերադարձավ Ստամբուլ։", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Դեսպան Փարիզում՝ Յիրմիսեքիզ Մեհմեդ Չելեբի", "26312a3f"], "d": ["Ֆրանսիա ուղարկված մեծ դեսպանությունը դարձավ Արևմուտքը տեղում ուսումնասիրող առաջին համակարգված դիտարկումը. նրա «Սեֆարեթնամեն» ոգեշնչեց Կակաչների դարաշրջանի նորացումը։", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Հիմնվեց առաջին օսմանյան տպարանը", "4943f7e5"], "d": ["Թույլտվություն տրվեց թուրքերեն գիրք տպագրելու. առաջին գործը՝ Վանքուլուի բառարանը, տպագրվեց 1729 թվականին։ Տպարանը Կակաչների դարաշրջանի նորացման ամենամնայուն ժառանգությունն է։", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Կապիտուլյացիաները դարձվեցին մշտական", "d044a79e"], "d": ["Ֆրանսիային տրված արտոնությունները, դադարելով սահմանափակվել փադիշահի կյանքով, կապվեցին մշտական պայմանագրի. միակողմանի չեղարկման ենթակա չդարձած կապիտուլյացիոն ռեժիմը կարողացավ վերանալ միայն Լոզանում։", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Հիմնվեց կայսերական ծովային ինժեներական դպրոցը (Mühendishâne-i Bahrî-i Hümâyun)", "9bf3f439"], "d": ["Չեշմեի աղետից հետո ժամանակակից ծովային սպաներ պատրաստելու համար հիմնված ինժեներական դպրոցը արևմտյան ոճի տեխնիկական կրթության առաջին մշտական հաստատությունն է. ցամաքային ինժեներական դպրոցը հետևեց 1795 թվականին։", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Առաջին մշտական դեսպանությունը Լոնդոնում", "6b5630eb"], "d": ["Որպես Նիզամ-ը Ջեդիդ ծրագրի մաս՝ եվրոպական մայրաքաղաքներում բացվեցին մշտական դեսպանություններ. օսմանյան դիվանագիտությունն անցավ փոխադարձության սկզբունքին։", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Ալեմդար Մուստաֆա փաշայի մահը", "4426534e"], "d": ["1808 թվականի նոյեմբերի 15-ի գիշերը սկսված ենիչերիական ապստամբության ժամանակ Բարձր Դռանը պաշարված բարեփոխիչ մեծ վեզիրը, երբ սպասած օգնությունը չեկավ, հաջորդ օրը, պայթեցնելով զինապահեստը, զոհվեց հարյուրավոր հարձակվողների հետ. Սենեդ-ի Իթթիֆաքի կարգը և բարեփոխումների առաջին փորձը թաղվեցին նրա հետ։", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Առաջին պաշտոնական թերթը՝ «Թաքվիմ-ի Վեքայի»", "c637f623"], "d": ["Սկսեց հրատարակվել պետության պաշտոնական թերթը. սա ժամանակակից հասարակական կարծիքի և պաշտոնական հաղորդագրությունների ավանդույթի սկիզբն է։", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Բալթա Լիմանիի առևտրային պայմանագիրը", "e790b383"], "d": ["Անգլիային նույնիսկ ներքին առևտրում ճանաչվեց ամենաարտոնյալ դիրք, վերացվեց մենաշնորհի (yed-i vahit) կարգը. մինչ տեղական արտադրությունը մնում էր անպաշտպան, պայմանագիրը դարձավ օսմանյան շուկայի՝ ազատ առևտրին լիովին բացվելու փաստաթուղթը։", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Լիբանանի ամիրայության ավարտը — Բաշիր III Շիհաբի պաշտոնազրկումը", "f85ae454"], "d": ["Քրիստոնյա-դրուզական պայքարը և Շուֆի շրջանի ներքին հավասարակշռությունները չկարողանալով վերահսկել՝ էմիր Բաշիր II-ը (III) 1842 թվականի հունվարին պաշտոնազրկվեց. 1516 թվականից (Մաան-օղլուների և ապա Շիհաբ-օղլուների ձեռքով) շարունակվող տեղական ամիրայության կարգն ավարտվեց, և շրջանն անցավ ուղղակի օսմանյան կառավարման, ապա երկկայմակամության համակարգի։", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Դրամի ուղղումը (Tashîh-i sikke)՝ մեջիդիեի կարգը", "c77be809"], "d": ["Դրամական բարեփոխմամբ հավաքվեցին հարգը խաթարված դրամները. ստեղծվեց ոսկե լիրայի (մեջիդիե) վրա հիմնված կայուն երկմետաղյա կարգ։", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Բաալբեքում Հարֆուշ ընտանիքի տեղական իշխանության ավարտը", "8438f4ae"], "d": ["1521 թվականից (Ջանբիրդի Ղազալիի ապստամբությունից հետո) Բաալբեքում որպես փոքր տեղական հարստություն իշխող Հարֆուշ ընտանիքի ազդեցությունը Բարձր Դռան նոր վարչական կարգավորմամբ ավարտվեց. քաղաքը դարձավ Դամասկոսի վիլայեթին ենթակա սովորական կազայի կենտրոն։", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Հիմնվեց «Շիրքեթ-ի Խայրիյե» ընկերությունը", "462830e7"], "d": ["Բոսֆորում շոգենավեր շահագործելու համար հիմնված ընկերությունը համարվում է առաջին օսմանյան բաժնետիրական ընկերությունը. շոգենավերի նավամատույցներն իրենց կնիքը դրեցին քաղաքային կյանքի վրա։", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Առաջին արտաքին փոխառության պայմանագիրը", "9017c579"], "d": ["Ղրիմի պատերազմի ֆինանսավորման համար Լոնդոնի շուկայից վերցվեց առաջին արտաքին փոխառությունը. 21 տարում 15 փոխառությամբ հասած կետը եղավ 1875 թվականի մորատորիումը և Պետական պարտքի վարչությունը։", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Հեռագրային գիծը Ստամբուլում", "d320f39f"], "d": ["Ղրիմի պատերազմի կարիքներից ելնելով անցկացված առաջին հեռագրային գիծը գործարկվեց. մի քանի տասնամյակում կայսրությունն ունեցավ աշխարհի ամենաընդարձակ հեռագրային ցանցերից մեկը։", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Հողային կանունամեն", "6bae243a"], "d": ["Հողային իրավունքը արդիականացրած կանունամեն պետական հողի (միրի) փաստացի տիրապետումը կապեց տապուի (հողի վկայագրի) հետ. այսօրվա Մերձավոր Արևելքի սեփականության կարգի հիմնարար փաստաթղթերից մեկն է։", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Առաջին դասերը Դարուլֆունունում", "08f74066"], "d": ["Համալսարանական մակարդակի կրթություն տալու կոչված Դարուլֆունունը սկսեց աշխատել հանրային դասախոսություններով. ընդմիջումներով շարունակված հաստատությունը 1900 թվականին վերջնականապես բացվեց և դարձավ Ստամբուլի համալսարանի միջուկը։", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Վիլայեթների կանոնադրությունը", "ad20853b"], "d": ["Էյալեթային կարգի փոխարեն ֆրանսիական օրինակով ստեղծվեց վիլայեթային կազմակերպությունը. Միդհաթ փաշայի Դանուբի վիլայեթի փորձը որպես օրինակ վերցնելով տարածվեց ողջ երկրով։", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Աբդուլազիզի եվրոպական ճանապարհորդությունը", "9ff0fa1e"], "d": ["Օսմանյան փադիշահի խաղաղ նպատակով եվրոպական առաջին ճանապարհորդությունը. Փարիզի ցուցահանդեսը և Լոնդոն այցելությունը ծառայեցին որպես և՛ դիվանագիտության, և՛ արդիականացման ցուցափեղկ։", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Բացվեց Ղալաթասարայի կայսերական լիցեյը", "f9688524"], "d": ["Ֆրանսերենով կրթություն տվող լիցեյը, իր ուսանողական կազմով, որ խտրություն չէր դնում կրոնի և ազգի միջև, դարձավ Թանզիմաթի կրթական հավասարության իդեալի խորհրդանիշը։", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Մեջելլեի առաջին գիրքն ուժի մեջ է", "6475461c"], "d": ["Իսլամական իրավունքի պարտավորությունների և գույքային իրավունքի ոլորտը ժամանակակից օրենսդրական տեխնիկայով ամփոփող Մեջելլեն համարվում է առաջին իսլամական քաղաքացիական օրենսգիրքը. Ջևդեթ փաշայի նախագահությամբ հանձնաժողովը 16 գիրքն ավարտեց 1876 թվականին։", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Աբդուլազիզի գահազրկումը", "eb7397ea"], "d": ["Սահմանադրական կարգի կողմնակից պետական գործիչները և զինվորական ղեկավարությունը անձայն հեղաշրջմամբ գահազրկեցին Աբդուլազիզին. հինգ օր անց նրա կասկածելի մահը և դրան հաջորդած Չըրաղանի դեպքերը ծնեցին տարիներ տևելիք հաշվեհարդարներ։", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Չըրաղանի հարձակումը (Ալի Սուավիի դեպքը)", "d2a9ac87"], "d": ["Լրագրող Ալի Սուավին, Մուրադ V-ին կրկին գահ բարձրացնելու համար, հարձակվեց Չըրաղան պալատի վրա. հարձակումը ճնշվեց արյունալի կերպով, Աբդուլ Համիդի վարչակարգը մշտապես խստացրեց անվտանգության օղակը։", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Հիմնվեց Ռեժի վարչությունը (ծխախոտի մենաշնորհ)", "bad9b030"], "d": ["Ծխախոտի եկամուտները փոխանցվեցին Պետական պարտքի վարչության կազմում գործող օտար կապիտալով Ռեժի ընկերությանը. գյուղացու և պահակների միջև «Ռեժիի մաքսանենգության» ընդհարումները տևեցին տասնամյակներ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Զեյլա։", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Կայզեր Վիլհելմ II-ի այցը Ստամբուլ և Երուսաղեմ", "2988cd06"], "d": ["Գերմանական կայսեր երկրորդ այցը ամրապնդեց օսմանա-գերմանական մերձեցումը. բացվեց Բաղդադի երկաթուղու կոնցեսիայի ճանապարհը, Դամասկոսում հնչեց «երեք հարյուր միլիոն մուսուլմանի բարեկամի» ճառը։", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Հիջազի երկաթուղին Մեդինայում", "95009b9c"], "d": ["Միայն մուսուլմանների նվիրատվություններով և տեղական ինժեներությամբ կառուցված 1464 կմ երկարությամբ գիծը հասավ Մեդինա. ուխտագնացության ճանապարհորդությունը շաբաթներից կրճատվեց օրերի։ Սա Աբդուլ Համիդ II-ի շրջանի ամենամեծ ենթակառուցվածքային գործն է։", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Մարտի 31-ի դեպքը", "1d7c2bb2"], "d": ["Սահմանադրական կարգի դեմ մեծ ապստամբությունը գրավեց Ստամբուլը. Սալոնիկից եկած Գործողությունների բանակը ճնշեց ապստամբությունը, և Աբդուլ Համիդ II-ը գահընկեց արվեց։", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Սկսվեց Էդիրնեի պաշարումը", "234d9b28"], "d": ["Շյուքրյու փաշայի հինգ ամիս տևած պաշտպանությունը դարձավ Բալկանյան աղետի մեջ դիմադրության էպոս. քաղաքն ընկավ սովից, հետ վերցվեց 1913 թվականի հուլիսին։", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Բարձր Դռան հարձակումը", "b304d02d"], "d": ["Էդիրնեն հանձնելու նախապատրաստվող կառավարությունը տապալվեց իթթիհադականների զինված հարձակմամբ. սպանվեց ռազմական նախարար Նազըմ փաշան։ Սկսվեց «Միություն և առաջադիմություն» կոմիտեի լիակատար իշխանության շրջանը։", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Լեռնային Լիբանանի մութասարիֆության վերացումը", "b5639051"], "d": ["1861 թվականի Règlement organique-ով հիմնված և 1864 թվականին վերանորոգված միջազգային արձանագրության վրա հիմնված ինքնավար մութասարիֆության կարգը Առաջին համաշխարհային պատերազմի ժամանակ Օսմանյան պետության կողմից միակողմանիորեն չեղարկվեց. ներքին գործերի նախարարությունը սկսեց շրջան ուղղակիորեն նշանակել մուսուլման մութասարիֆներ։ Այսպիսով փակվեց 1861-1915 թվականների ինքնավարության շրջանը, որի ընթացքում պաշտոնավարեցին ութ մութասարիֆ։", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Երկրի բաժանումը շահզադեների միջև", "82f26bfb"], "d": ["Անկարայի ջախջախումից հետո Սուլեյման Չելեբին անցավ Ռումելի և Էդիրնեում հռչակեց սուլթանություն. Իսա Չելեբին իր ձեռքում պահեց Բուրսան, իսկ Չելեբի Մեհմեդը՝ Ամասիա-Թոքաթ-Սեբաստիա շրջանը։ Քարտեզում այս երեք բաժինները ցույց են տրվում առանձին գույներով։", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Գելիբոլուի պայմանագիրը՝ Սև ծովի ափը մինչև Մեսեմբրիա թողնվեց Բյուզանդիային", "a4164eca"], "d": ["Անկարայի ջախջախումից հետո Ռումելիում դիմանալ ցանկացող էմիր Սուլեյմանը Գելիբոլուում պայմանագիր ստորագրեց բյուզանդական կայսր Մանուելի հետ։ Նա Բյուզանդիային թողեց Քարթալը, Պենդիկը և Գեբզեն ու որոշ կղզիներ, Ռումելիում՝ Սալոնիկը և Թեսալիան, Սև ծովում՝ մինչև Մեսեմբրիա ձգվող ափամերձ շերտը. վերացվեց նաև այն հարկը, որ Բյուզանդիան վճարում էր օսմանցիներին։ Ստրանջայի ափի Ահտոպոլը, Իղնեադան և Ռեզվեն այսպիսով քսանմեկ տարի մնացին բյուզանդական կառավարման տակ. Մուրադ II-ը 1424 թվականի հաշտությամբ հետ վերցրեց այս վայրերի մեծ մասը։", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Յըլդըրըմ Բայազիդի մահը գերության մեջ", "7e968d83"], "d": ["Թեմուրի գերության մեջ գտնվող փադիշահը մահացավ Աքշեհիրում. նրա դին բերվեց Բուրսա և թաղվեց։ Նրա մահը շահզադեների միջև գահակալական պայքարը դարձրեց անշրջելի։", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Գելիբոլուի պայմանագիրը — զիջումներ Բյուզանդիային", "dfacbd00"], "d": ["Ռումելիում իր դիրքն ապահովել ցանկացող Սուլեյման Չելեբին, համաձայնության գալով Բյուզանդիայի և լատինական պետությունների հետ, վերադարձրեց Սալոնիկը, Մարմարայի ափերը և որոշ կղզիներ. նա նույնիսկ համաձայնեց խարաջ վճարել։", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Ուլուբաթի ընդհարումը — Իսա Չելեբիի պարտությունը", "500c5d24"], "d": ["Բուրսան ձեռքում պահող Իսա Չելեբին Ուլուբաթում պարտվեց եղբորը՝ Մեհմեդին. վերականգնվելու մի քանի փորձն էլ անարդյունք մնաց։", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Իսա Չելեբիի վերանալը ասպարեզից", "0effa11e"], "d": ["Սուլեյման Չելեբիի աջակցությամբ մի քանի անգամ Անատոլիա վերադարձած Իսա Չելեբին իր վերջին պարտությունից հետո անհետացավ. նրա բաժինն անցավ Չելեբի Մեհմեդին, և քարտեզում Մեհմեդի տարածքն ընդարձակվեց դեպի արևմուտք։", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Մուսա Չելեբին անցավ Վալախիա", "8441267a"], "d": ["Սուլեյման Չելեբիի դեմ Բուրսան և Անկարան կորցրած ու Թոքաթ-Ամասիա նահանջած Չելեբի Մեհմեդը եղբորը՝ Մուսային, խրախուսեց գնալ Ռումելի։ Մուսան, ընդունելով Վալախիայի վոյևոդ Միրչայի հրավերը, ծովով հասավ Վալախիա. այստեղից նա ձեռնամուխ էր լինելու պայքարի, որը Սուլեյմանին թողնելու էր երկու ճակատի միջև։", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Չելեբի Մեհմեդը կրկին գրավեց Բուրսան և Անկարան — անատոլիական բաժինը դուրս եկավ Սուլեյման Չելեբիի ձեռքից", "bfb69f12"], "d": ["Մուսա Չելեբիի՝ Ռումելիում հաջողությունների (Յամբոլ, 1410 թվականի փետրվարի 13) առիթով Անատոլիայում գտնվող էմիր Սուլեյման Չելեբին անցավ Ռումելի։ Անատոլիայից Սուլեյմանի հեռանալուց հետո Մեհմեդ Չելեբին կրկին գրավեց Բուրսայի շրջանը՝ ներառյալ Անկարան, և որպես գահ բարձրանալու նշան հատեց 813 թվականով դրամ։ Քարտեզում Մարմարայի անատոլիական ափը էմիր Սուլեյմանի բաժնից անցնում է Չելեբի Մեհմեդի գույնին։", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Կոսմիդիոնի ճակատամարտը", "0efc2caa"], "d": ["Բյուզանդական աջակցությամբ Ստամբուլի պարիսպների առջև մղված ճակատամարտում Սուլեյման Չելեբին հաղթեց եղբորը՝ Մուսային. սակայն Ռումելիում նրա աջակցությունն արդեն սկսել էր արագորեն հալվել։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ալասոնյա (Elassona), Այդոս (Aytos), Բոլայիր (քարտեզում Ռումելիում Մուսայից Սուլեյմանին անցած վայրերը)։", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Մուսա Չելեբիի Ստամբուլի պաշարումը", "4932f586"], "d": ["Սուլեյմանին աջակցած Բյուզանդիային պատժել ցանկացող Մուսա Չելեբին պաշարեց Ստամբուլը. այս պաշարումը Բյուզանդիային մղեց դաշինքի Չելեբի Մեհմեդի հետ։", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Էմիր Սուլեյմանի մահը — Մուսան՝ Ռումելիի տեր", "325c1549"], "d": ["Էդիրնեից փախչելիս բռնված Սուլեյման Չելեբին սպանվեց. ամբողջ Ռումելին անցավ Մուսա Չելեբիի ձեռքը։ Քարտեզում Ռումելին կապույտ գույնից դառնում է մանուշակագույն։", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Չամուրլուի ճակատամարտը — միասնության վերականգնումը", "0b23173e"], "d": ["Բյուզանդիայի, Սերբական դեսպոտության և Ռումելիի բեյերի աջակցությունն ստացած Չելեբի Մեհմեդը Չամուրլուում վճռական պարտության մատնեց եղբորը՝ Մուսային. Մուսան սպանվեց փախչելիս։ Մուսայի ձեռքում եղած Ռումելին Էդիրնեի հետ անցավ Մեհմեդին, և Մեհմեդ Չելեբին Էդիրնեում իրեն հռչակեց Օսմանյան պետության միակ տիրակալ։ Տասնմեկամյա միջգահակալության շրջանն ավարտվեց, և քարտեզի շահզադեական բաժինները միավորվեցին մեկ մարմնի մեջ։", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Վիեննայի արշավանքի որոշումը — Վաշվարի հաշտությունը չվերանորոգվեց, թիրախը Դյորից (Յանըքքալե) տեղափոխվեց Վիեննա", "1bf278f2"], "d": ["Լեոպոլդ I կայսրը ցանկանում էր վերանորոգել Վաշվարի պայմանագիրը, որի ժամկետը դեռ չէր լրացել, և Մեհմեդ IV-ը ևս խաղաղության կողմնակից էր թվում։ Իսկ մեծ վեզիր Մերզիֆոնցի Կարա Մուստաֆա փաշան, պատճառաբանելով Միջին Հունգարիայի թագավոր հռչակել տված Իմրե Թյոքյոլիի գանգատները, թույլ չտվեց վերանորոգել հաշտությունը. գլխավորապես Վանի Մեհմեդ էֆենդիին և քարոզիչներին շարժման մեջ դնելով՝ համոզեց փադիշահին պատերազմել։ Անցկացված խորհրդակցությունում որոշվեց, որ փադիշահը մնա Բելգրադում, իսկ գլխավոր սերդարը առաջանա Դյորը գրավելու. սակայն Սեկեշֆեհերվարի (İstolni Belgrad) խորհրդակցությունում, չնայած Ղրիմի խան Մուրադ Գիրեյի և Բուդայի կուսակալ Ուզուն Իբրահիմ փաշայի առարկություններին, թիրախը փոխվեց Վիեննայի պաշարման։", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Սկսվեց Վիեննայի երկրորդ պաշարումը — բանակը Վիեննայի մոտ է", "bb542e49"], "d": ["Մեծ վեզիր Կարա Մուստաֆա փաշայի հրամանատարությամբ օսմանյան բանակը 1683 թվականի հուլիսի 14-ին հասավ Վիեննայի մատույցները։ Լեոպոլդ I կայսրը, քաղաքի պաշտպանությունը թողնելով Շտարհեմբերգին, նահանջեց Ավստրիայի խորքերը։ Ի տարբերություն առաջինի՝ ուղղակիորեն Վիեննան թիրախ դարձրած այս երկրորդ պաշարումը տևելու էր մինչև սեպտեմբերի 12-ը։", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Պարկանի ջախջախումը և Էստերգոմի կորուստը", "a7366740"], "d": ["Վիեննայից նահանջող բանակը Պարկանում երկրորդ անգամ ջախջախվեց. ապա ընկավ Հունգարիայի բանալի ամրոցներից Էստերգոմը։ Նահանջը սկսեց վերածվել փլուզման։", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Մերզիֆոնցի Կարա Մուստաֆա փաշայի մահապատիժը", "ce8b10ac"], "d": ["Վիեննայի ջախջախման մեղավոր համարված մեծ վեզիրը խեղդամահ արվեց Բելգրադում. սակայն նրա մահապատիժը ո՛չ ճակատը շտկեց, ո՛չ էլ վերադարձրեց պետության խարխլված հեղինակությունը։", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Կազմվեց Սրբազան լիգան", "060280d0"], "d": ["Պապականության նախաձեռնությամբ Ավստրիայի, Լեհաստանի և Վենետիկի միջև օսմանցիների դեմ կազմվեց Սրբազան լիգան. 1686 թվականին միացավ նաև Ռուսաստանը։ Այսպիսով կայսրությունը մտավ տասնվեց տարի տևելիք բազմաճակատ պատերազմի մեջ։", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Բուդայի առաջին պաշտպանությունը", "ccc43630"], "d": ["Սրբազան լիգայի բանակի Բուդայի առաջին պաշարումը հետ մղվեց ամրոցի չորս ամիս տևած համառ պաշտպանությամբ. սակայն Հունգարիայի ամրոցները շարունակում էին ընկնել մեկը մյուսի հետևից։", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Ույվարի կորուստը", "689ab78c"], "d": ["Քսաներկու տարի օսմանյան ձեռքում մնացած և Եվրոպայում առածի վերածված Ույվարի ամրոցն ընկավ. օսմանյան ներկայությունը Վերին Հունգարիայում քայքայվեց։", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Թյոքյոլիի ձերբակալությունը Վարադում — Միջին Հունգարիայի թագավորությունը ցրվեց, Վերին Հունգարիայի ամրոցները հանձնվեցին", "1741aaaf"], "d": ["Վիեննայի ջախջախումից հետո օսմանցիները սկսել էին Թյոքյոլիին ևս համարել պատերազմի և պարտության պատճառ դարձածների թվում։ 1685 թվականի հոկտեմբերի 15-ին սերդար Մելեք Իբրահիմ փաշայի հրամանով Վարադի բեյլերբեյ Ահմեդ փաշան ձերբակալել տվեց օգնության եկած Թյոքյոլիին. հույս կար նրան հանձնելով Հաբսբուրգներին ձեռք բերել ավելի լավ խաղաղության պայմաններ։ Երբ տարածվեց ձերբակալության լուրը, բացի նրա կնոջ՝ Իլոնա Զրինիի պաշտպանած Մունկաչից, Միջին Հունգարիայի թագավորության բոլոր ամրոցներն ու քաղաքները հանձնվեցին Հաբսբուրգներին. կուրուց զինվորների մեծ մասն անցավ հաբսբուրգյան բանակ։ Երբ Թյոքյոլին 1686 թվականի հունվարի 2-ին Բելգրադում ազատ արձակվեց, թագավորությունն արդեն վերացել էր։", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Բուդայի կորուստը — 145-ամյա հունգարական մայրաքաղաքը", "70800e2b"], "d": ["Յոթանասունութ օր տևած պաշարման վերջում Բուդան ընկավ. վերջին բեյլերբեյ Աբդուրռահման Աբդի փաշան նահատակվեց պարիսպների վրա։ 1541 թվականից օսմանյան կառավարման տակ գտնվող քաղաքի կորուստը համարվում է Հունգարիայի ձեռքից գնալու խորհրդանիշ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Պեշտ։", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Մոհաչի երկրորդ (Հարշանի) ջախջախումը — Տրանսիլվանիայի և Մոհաչի կորուստը", "a7922681"], "d": ["1526 թվականին մեծ հաղթանակ տարած դաշտում այս անգամ ծանր պարտություն կրեցին. բանակը ցրվեց, ապստամբած զինվորները պաշտոնազրկել տվեցին մեծ վեզիրին։ Պարտությունը հանգեցրեց նաև Տրանսիլվանիայի կորստին։", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Աթենքի կորուստը և Պարթենոնի պայթյունը", "b6691730"], "d": ["Վենետիկյան հրետանու արձակած ռումբը օդ հանեց Պարթենոնը, որն օսմանցիներն օգտագործում էին որպես զինապահեստ. երկու հազարամյա տաճարը վերածվեց ավերակի։ Քաղաքն անցավ Վենետիկի ձեռքը (հետ վերցվելու է 1688 թվականին)։", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Մեհմեդ IV-ի գահազրկումը և Սուլեյման II-ի գահակալումը", "9f53037c"], "d": ["Ճակատի աղետների և բանակի ապստամբության հետևանքով 39-ամյա գահակալությունից հետո Մեհմեդ IV-ը գահազրկվեց. նրա փոխարեն գահ բարձրացվեց քառասուն տարի «վանդակում» (kafes) պահված նրա եղբայր Սուլեյման II-ը։", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Բելգրադի առաջին կորուստը — Սրբազան լիգայի պաշարումը", "c6b9b19a"], "d": ["1521 թվականից օսմանյան ձեռքում գտնվող Բելգրադը հանձնվեց Սրբազան լիգայի բանակին. Սերբիայի դարպասները բացվեցին թշնամու առաջ, և վտանգը հասավ Նիշ-Սոֆիա գծին։ Նույն ամսաթվին ատլասում Օսմանյան պետությունից Հաբսբուրգներին անցած մյուս բնակավայրը՝ Հիսարջըք (Գրոցկա). հետևում է Բելգրադի ավագ կենտրոնի շղթային (TDV belgrad. հայտարարված մոտավորություն)։", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Բադենը Պոժարևացի մոտ անցավ Մորավան — Պոժարևացն անցավ Ավստրիային", "bcf3fc59"], "d": ["Բադենի մարկգրաֆ Լյուդվիգը 1689 թվականի օգոստոսին Պոժարևացի մոտ անցնելով Մորավան՝ առաջացավ դեպի Նիշ. քաղաքը մինչև 1690 թվականի ամառը մնաց Ավստրիայի ձեռքում (TDV suleyman-ii-ն ասում է, որ Պոժարևացը հետ վերցվել է 1690 թվականին)։ Օրը և Ռյոդերի ընթերցումը այս նիստում վերստին չեն հաստատվել։", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Նիշի կորուստը — հաբսբուրգյան (Հունգարիայի թագավորության թագի) առաջխաղացումը, ամենակրիտիկական տարին", "c5e27b3f"], "d": ["Հաբսբուրգյան (Հունգարիայի թագավորության թագի) առաջխաղացումը Նիշը ևս հանեց օսմանյան կառավարումից. ասպատակությունները հասան մինչև Սկոպյե և Պրիշտինա։ Իսկ Վիդինն ընկավ դրանից հետո՝ 1689 թվականի հոկտեմբերին (առանձին գրառում)։ Պատերազմի ամենամութ տարում պետությունն իրեն սպառնալիքի տակ զգաց նույնիսկ մայրաքաղաքում։", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Օրշովան և Ֆեթհյուլիսլամը վերցվեցին ավստրիական կայազորի տակ", "ee8dd875"], "d": ["Վիդինի առանց կռվի գրավումից (1689 թվականի հոկտեմբեր, TDV vidin) հետո Բադենը 1689 թվականի հոկտեմբերի 25-ին վերանորոգեց Օրշովան և Ֆեթհյուլիսլամը ու կայազոր տեղադրեց. Օրշովան մինչև 1690 թվականի աշունը մնաց Ավստրիային։ Օրը հիմնված է Bánlaky/Röder-ի վրա, այս նիստում վերստին չի հաստատվել։", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Նիշը կրկին օսմանյան է", "0c4f44eb"], "d": ["Ֆազըլ Մուստաֆա փաշան 1690 թվականի հուլիսին ելավ արշավանքի. Շեհիրքյոյը, Պոժարևացը և Գյուվերջինլիքը գրավելուց հետո պաշարված Նիշը 1690 թվականի սեպտեմբերի 27-ին անցավ օսմանցիների ձեռքը (TDV semendire)։ Նույն ժամանակ հետ էր վերցվել նաև Վիդինը։ Նույն ամսաթվին ատլասում Հաբսբուրգներից օսմանցիներին վերադարձած մյուս բնակավայրեր՝ Յագոդինա (Jagodina) և Պրոկուպլյե (Prokuplje). քանի որ բնակավայրի մակարդակով օրը չի գտնվել, վերցված է Նիշի օրը (TDV semendire. հայտարարված մոտավորություն. Röder 1842-ը գրում է, որ վեզիրը Յագոդինայով անցել է սեպտեմբերի 8-24-ին, հակասությունը լուծված չէ)։", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Սմեդերևոյում ավստրիական զորամասերը հանձնվեցին", "90da20c4"], "d": ["1690 թվականի սեպտեմբերի 27-ին Նիշի գրավումից հետո չորսօրյա պաշարմամբ Սմեդերևոյի ավստրիական զորամասերը հանձնվեցին (TDV semendire)։ Bánlaky/Röder-ը նշում են սեպտեմբերի 24. աղբյուրները հակասում են, հիմք ընդունվեց TDV-ն։", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Բելգրադը հետ վերցվեց", "ab435838"], "d": ["Մեծ վեզիր Քյոփրյուլյուզադե Ֆազըլ Մուստաֆա փաշան 1690 թվականի հոկտեմբերի 8-ին Բելգրադը հետ վերցրեց Ավստրիայից. 1688 թվականին կորցրած քաղաքն այսպիսով վերադարձավ օսմանցիներին (TDV suleyman-ii)։ Նույն ամսաթվին ատլասում Հաբսբուրգներից օսմանցիներին վերադարձած մյուս բնակավայրը՝ Հիսարջըք (Գրոցկա). հետևում է Բելգրադի ավագ կենտրոնի շղթային (TDV suleyman-ii. հայտարարված մոտավորություն)։", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Սլանկամենի ջախջախումը — Ֆազըլ Մուստաֆա փաշան նահատակվեց", "10d626f1"], "d": ["Դարի ամենաարյունալի դաշտային ճակատամարտերից մեկում մեծ վեզիրը ճակատին ստացած գնդակից նահատակվեց. բանակը ցրվեց։ Վերականգնվելու հույսը մարեց այս ճակատամարտի հետ։", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Քիոս կղզու կորուստը", "07c084f8"], "d": ["Վենետիկյան նավատորմը գրավեց Քիոսը. օսմանյան տիրապետությունը Էգեյան ծովում հայտնվեց սպառնալիքի տակ։ Կղզին հաջորդ տարի հետ վերցվելու էր։", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Մուստաֆա II-ի՝ անձամբ արշավանքի ելնելու որոշումը", "61c3ba9c"], "d": ["Նոր փադիշահը, հետևելով իր նախնիների ուղուն, հայտարարեց, որ բանակի գլուխ անցած արշավանքի կելնի. այս որոշումը բարձրացրեց բանակի ոգին և սկիզբ դրեց երկու տարի տևելիք անձնական արշավանքների շրջանին։", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Քիոսի հետգրավումը", "6b496fca"], "d": ["Քոյուն կղզիների ծովամարտերում վենետիկյան նավատորմին հաղթած Մեզոմորտո Հուսեյն փաշան հետ վերցրեց Քիոսը. սա դարձավ օսմանյան ծովագնացության կարճատև վերածննդի նշան։", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Լուգոժի հաղթանակը — Մուստաֆա II-ի առաջին ավստրիական արշավանքը", "d5ee9b34"], "d": ["Փադիշահի անձամբ մասնակցած առաջին արշավանքում հետ վերցվեց Լիպովան, իսկ Լուգոժում պարտության մատնվեցին ավստրիական ուժերը. տարիներ շարունակ ձգվող պարտությունների շղթայում տեղի ունեցավ առաջին բեկումը։ Ատլասը նաև Կարանշեբեշը (Caransebeş) այս արշավանքում համարում է Հաբսբուրգներից օսմանցիներին վերադարձած. աղբյուրը տալիս է միայն 1695 թվականի սեպտեմբերը (TDV mustafa-ii), ատլասի օրը վերցված է Լուգոժի գրառումից (հայտարարված մոտավորություն)։", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Ազովի ամրոցի կորուստը", "2b78b5cd"], "d": ["Սև ծով դուրս գալու նպատակ ունեցող Պետրոս I-ը իր երկրորդ պաշարման ժամանակ գրավեց Ազովը. Ռուսաստանն առաջին անգամ մշտապես հաստատվեց օսմանյան ամրոցում և ծովային ուժ դառնալու ճանապարհին արեց իր առաջին քայլը։", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Ուլաշի (Olaşin) հաղթանակը", "02ac9ca8"], "d": ["Փադիշահի երկրորդ արշավանքում Դանուբի ափին տարած հաղթանակը խափանեց Տեմեշվարը գրավելու ավստրիական ծրագիրը. սակայն պատերազմի ընդհանուր հավասարակշռությունը չփոխեց։", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Զենտայի ջախջախումը — որոշվեց պատերազմի ճակատագիրը", "475c4a7b"], "d": ["Տիսա գետն անցնելիս բանակը ենթարկվեց արքայազն Եվգենիի հանկարծակի հարձակմանը. գետի երկու ափերին բաժանված ուժերը մի քանի ժամում ոչնչացվեցին, զոհվեցին հազարավոր զինվորներ և պետական գործիչներ, այդ թվում՝ մեծ վեզիր Էլմաս Մեհմեդ փաշան։ Օսմանյան պատմության ամենածանր ջախջախումներից մեկը եղած Զենտան խաղաղության բանակցությունների սեղանն անխուսափելի դարձրեց։", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Սկսվեցին Կառլովիցի խաղաղության բանակցությունները", "1f395cf3"], "d": ["Անգլիայի և Հոլանդիայի միջնորդությամբ սկսված բանակցություններում օսմանյան պատվիրակությունն առաջին անգամ ստիպված եղավ ընդունել «uti possidetis» (ինչ ձեռքում է, մնում է) սկզբունքը. յոթանասուներկու նիստ տևած բանակցությունները համարվում են ժամանակակից օսմանյան դիվանագիտության ծնունդը։", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Կավալացի Մուհամմեդ Ալին ոտք դրեց Եգիպտոս", "514c943f"], "d": ["Ֆրանսիական օկուպացիայի տակ գտնվող Եգիպտոսը հետ վերցնելու ուղարկված օսմանյան բանակի մեջ կար նաև Կավալայից հավաքված կամավորների ջոկատ։ Երեսունն անց Մուհամմեդ Ալին այդ ջոկատի երկրորդ հրամանատարն էր. նա Եգիպտոս ոտք դրեց ոչ թե որպես կուսակալ, այլ որպես վաշտի սպա։", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Ալբանացի զինվորները տապալեցին Եգիպտոսի կուսակալին", "c76a0ec2"], "d": ["Ռոճիկները չստացած ալբանական զորամասերը ապստամբեցին և Խյուսրև փաշա կուսակալին ստիպեցին փախչել ամրոցից։ Ֆրանսիացիների նահանջով առաջացած դատարկության մեջ մամլուք բեյերը, ալբանական զորաբանակը և Բարձր Դռան նշանակած կուսակալները եռանկյուն պայքարի մեջ մտան. Մուհամմեդ Ալին այս եռանկյունու մեջ հավասարակշռություններ ստեղծելով առաջ եկավ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Թաիֆ։", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Կահիրեի ուլեմաները Մուհամմեդ Ալիին հռչակեցին կուսակալ", "a16752f2"], "d": ["Հարկային ճնշումից տառապող Կահիրեի արհեստավորներն ու ուլեմաները նաքիբ ուլ-աշրաֆ Օմար Մաքրամի առաջնորդությամբ ապստամբեցին, հայտարարեցին, որ չեն ճանաչում Խուրշիդ փաշա կուսակալին, և Մուհամմեդ Ալիին նստեցրին կուսակալի աթոռին։ Օսմանյան պատմության մեջ կուսակալի՝ ժողովրդի կողմից ընտրվելը հազվագյուտ իրադարձություն է։", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Բարձր Դուռն ընդունեց կատարված փաստը՝ Եգիպտոսի կուսակալության ֆերմանը", "b86736a3"], "d": ["Եգիպտոսում իր թեկնածուին պահելու ուժ չունեցող Բարձր Դուռը Մուհամմեդ Ալիին վեզիրության աստիճանով ուղարկեց Եգիպտոսի կուսակալության ֆերմանը։ Քարտեզում Եգիպտոսը այս ամսաթվից սկսած անցնում է ենթակա (բաց երանգի) շերտ. իրավաբանորեն օսմանյան հող է, փաստացի՝ Կավալացու հարստության երկիր։ Նույն ամսաթվին ենթակա շերտ անցած այլ բնակավայրեր՝ Կահիրե, Ալեքսանդրիա, Դամիետտա, Ասյուտ, Ասուան, Իբրիմ, Սուեզ, Ռաշիդ (Rosetta)։", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Անգլիական Ֆրեյզերի արշավախումբը ափ իջավ Ալեքսանդրիայում", "4d6c31be"], "d": ["Օսմանյան պետության՝ Ֆրանսիային մերձենալուն ի պատասխան՝ Անգլիան Եգիպտոս ուղարկեց ափհանման ուժ։ Մուհամմեդ Ալին այդ ժամանակ Վերին Եգիպտոսում զբաղված էր մամլուքներով. արագ վերադառնալով՝ կազմակերպեց պաշտպանությունը։", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Ռաշիդի (Rosetta) ջախջախումը — անգլիացիները հետ մղվեցին", "3636004c"], "d": ["Ռաշիդ ավան մտած անգլիական շարասյունը փողոցային ընդհարումներում ծանր կորուստներ ունեցավ. սեպտեմբերին ուժերը ամբողջությամբ լքեցին Եգիպտոսը։ Այս հաղթանակը ամրապնդեց Մուհամմեդ Ալիի հեղինակությունը թե՛ Եգիպտոսում, թե՛ Ստամբուլում։", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Ամրոցի դեպքը՝ մամլուք բեյերի ոչնչացումը", "84030b97"], "d": ["Հիջազի արշավանքի առիթով կազմակերպված հանդիսավոր շքերթին հրավիրված մամլուք բեյերը Կահիրեի ամրոցի նեղ անցուղում թակարդն ընկնելով ոչնչացվեցին։ Այսպիսով ավարտվեց հինգդարյա մամլուքական ազդեցությունը, և Եգիպտոսում Մուհամմեդ Ալիի առաջ մրցակից չմնաց։", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Սկսվեց Հիջազի արշավանքը — բանակը ծովով Սուեզից, իսկ ուխտագնացության ճանապարհով ցամաքով շարժվեց Յանբու", "1c05c159"], "d": ["1803 թվականից սաուդյան-վահաբիական կառավարման տակ գտնվող երկու սրբավայրերը (Հարամեյնը) հետ վերցնելը Մահմուդ II-ի լեգիտիմության ամենամեծ խնդիրն էր. երբ Բարձր Դռան ուժերը չբավարարեցին, առաջադրանքը տրվեց Եգիպտոսի կուսակալին։ Մուհամմեդ Ալին բանակի գլուխ ուղարկեց իր տասնվեցամյա որդի Թուսունին։", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Յանբուն հանձնվեց — Հիջազի արշավանքի առաջին ափամերձ հենակետը", "179bc78d"], "d": ["Սուեզից նորակառույց նավերով ճանապարհ ընկած շուրջ երկու հազար ալբանացի հետևակը 1811 թվականի հոկտեմբերին ափ իջավ Յանբուի մոտ. ավանը երկու օրվա թույլ դիմադրությունից հետո հանձնվեց։ Թուսունի հրամանատարությամբ հեծելազորը ցամաքով հետևեց ուխտագնացության ճանապարհին և Աքաբայի և Վաջհի վրայով Յանբու հասավ միայն երկու շաբաթ անց։ Յանբուն դարձավ Մեդինայի և Մեքքայի վրա շարժվելիք եգիպտական բանակի առաջին հենակետը Հիջազում։", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Առաջին ջախջախումը Սաֆրա-Ջեդիդեի կիրճում", "99ef804d"], "d": ["Նեղ լեռնային անցումներում դարանի մեջ ընկած եգիպտական առաջապահ ուժը ցրվեց։ Պարտությունը դարձավ արշավանքի մարտավարական դասը. հասկացվեց, որ առանց բեդվին ցեղերի աջակցության Հիջազում առաջանալ հնարավոր չէ։", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Մեդինան հետ վերցվեց", "6f6a5d55"], "d": ["Երկարատև պաշարումից հետո Մեդինան հանձնվեց։ Մարգարեի քաղաքի հետգրավումը Ստամբուլում նշվեց թնդանոթային տոնախմբություններով. Մուհամմեդ Ալիին որպես պարգև տրվեց նաև Ջիդդայի կուսակալությունը։", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Մեքքան հետ վերցվեց — բացվեց ուխտագնացության ճանապարհը", "3d6d66a0"], "d": ["Մեքքա մտած եգիպտական ուժերը Քաաբայում կրկին օսմանյան փադիշահի անունով խուտբա կարդացնել տվին։ Տասը տարի ընդհատված ուխտագնացության քարավանները կարողացան կրկին ճանապարհ ընկնել։ Քարտեզում Հիջազը վերադառնում է օսմանյան տիրապետության, սակայն քանի որ կառավարումը Կահիրեում էր, ցույց է տրվում ենթակայության երանգով։ Նույն ամսաթվին ենթակա կառավարման անցած այլ վայր՝ Ջիդդա։", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Թաիֆի հետգրավումը — Հիջազի արշավանքի ավարտը", "6315fb31"], "d": ["Մեդինայից (1812 թվականի դեկտեմբեր) և Մեքքայից (1813 թվականի հունվար) հետո Թուսուն փաշայի հրամանատարությամբ եգիպտական բանակը վերջինը Թաիֆը հետ վերցրեց վահաբիներից։ Տասը տարի տևած սաուդյան տիրապետությունն ավարտվեց, և Հիջազի բոլոր երեք սրբազան կենտրոնները կրկին անցան օսմանա-եգիպտական վերահսկողության տակ։", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Մուհամմեդ Ալին անձամբ անցավ Հիջազ", "fda0ea2d"], "d": ["Տեսնելով, որ արշավանքը դանդաղ է ընթանում, կուսակալը կառավարումը վերցրեց իր ձեռքը. ցեղապետերի հետ սակարկելով՝ փորձեց ներսից քայքայել սաուդյան ճակատը։ Այս արշավանքով մեծացավ նաև Եգիպտոսի մասնաբաժինը Կարմիր ծովի առևտրում։", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Բիսելի ճակատամարտը՝ սաուդյան ուժերը ջախջախվեցին", "9c9ab91f"], "d": ["Դաշտային ճակատամարտում ծանր պարտություն կրած սաուդները նահանջեցին ներքին շրջաններ։ Կնքված զինադադարը կայուն չեղավ. երկու տարի անց գործողությունները տեղափոխվելու էին Նեջդի սիրտը։ Ատլասը այս հաղթանակից հետո Թաիֆից արևելք գտնվող Թուրաբան և Խուրման համարում է սաուդյան ձեռքից դուրս եկած (իրադարձության աղբյուրը՝ Lorimer, Gazetteer. բնակավայրերին հատուկ վկայությունը և հունվարի 13 օրը հայտարարված մոտավորություն են)։", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Իբրահիմ փաշան ելավ Նեջդի արշավանքի", "d5ed80d1"], "d": ["Եղբոր՝ Թուսունի մահից հետո հրամանատարությունն ստանձնած Իբրահիմ փաշան անապատում ձեռնամուխ եղավ երկու տարի տևած ծանր երթի։ Ջրհոր առ ջրհոր առաջացող բանակը, ցեղերին մեկ առ մեկ վերացնելով, հասավ սաուդյան մայրաքաղաքի մատույցները։", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Դիրիյան ընկավ — առաջին սաուդյան պետությունն ավարտվեց", "aa96206d"], "d": ["Վեց ամիս տևած պաշարումից հետո Դիրիյան հանձնվեց և ավերվեց։ Էմիր Աբդուլլահ իբն Սաուդը ուղարկվեց Ստամբուլ և մահապատժի ենթարկվեց։ Օսմանյան դրոշն առաջին անգամ այդքան խորը հասավ Արաբիայի ներսը. Նեջդի կայազորը մնաց մինչև 1824 թվականը։ Նույն ամսաթվին միացած այլ վայրեր՝ Դիրիյա (Նեջդ)։", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Սկսվեց Սուդանի արշավանքը", "b1fc6905"], "d": ["Մուհամմեդ Ալիի նպատակը եռակի էր՝ բանակի համար զինվոր հավաքել, հասնել Սեննարի ոսկուն և ոչնչացնել մամլուքների փախած մնացորդները։ Նրա որդի Իսմայիլ փաշայի հրամանատարությամբ ուժը, հետևելով Նեղոսին, իջավ հարավ։", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Դոնգոլան առանց բռնության անցավ եգիպտական բանակին (մամլուքները լքել էին այն 1820 թվականի հունիսին)", "bc5942c0"], "d": ["Նեղոսի մեծ ոլորանի վրա գտնվող Դոնգոլան, 1820 թվականի հունիսին մամլուքների լքելուց հետո, առանց բռնության անցավ Իսմայիլ փաշայի եգիպտական բանակի ձեռքը։ Քարտեզում Սուդանը այս ամսաթվից հայտնվում է ենթակայության շերտում. նվաճողը Կահիրեն է, կառավարողն էլ լինելու է Կահիրեն։", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Ջաբալ ադ-Դայքայի ճակատամարտը — Շայքիյա դաշնությունը վճռական պարտություն է կրում եգիպտական բանակից", "befc9539"], "d": ["Մուհամմեդ Ալի փաշայի որդի Իսմայիլ փաշայի բանակը Քուրտիի առաջին ընդհարումից մեկ ամիս անց Ջաբալ ադ-Դայքայի մոտ երկրորդ և վճռական ճակատամարտում հաղթեց Շայքիյային։ Շայքիյայի առաջնորդ Մաքք Սուբայրը հանձնվեց. Մաքք Շավիշը շարունակեց դիմադրությունը։ Եգիպտոսի տիրապետությունը Նեղոսի ոլորանում դրանից հետո դարձավ մշտական։", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Սեննարի (Ֆունջ) սուլթանությունը հանձնվեց", "3cac7dd2"], "d": ["Երեքդարյա Ֆունջ հարստությունը հանձնվեց առանց ընդհարման։ Նույն տարի Նեղոսի երկու ճյուղերի միախառնման կետում հիմնված ռազմակայանը կարճ ժամանակում վերածվեց Սուդանի վարչական կենտրոն Խարտումի։ Նույն ամսաթվին միացած այլ վայրեր՝ Սեննար։", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Գրավվեց Կորդոֆանը", "06440602"], "d": ["Արևմուտք ուղարկված երկրորդ շարասյունը Բարայում (Bâra) պարտության մատնեց Դարֆուրի ուժերին և գրավեց Կորդոֆանը՝ Նուհուդի շրջակայքի հետ։ Այսպիսով Եգիպտոսի տիրապետությունը Սուդանում Նեղոսի հովտից ընդարձակվեց դեպի արևմտյան տափաստաններ։", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Եգիպտական ուժերը ափ իջան Կրետեում", "835aee90"], "d": ["Երբ հունական ապստամբությունը տարածվեց Կրետե, Բարձր Դուռը խնդրեց եգիպտական ուժ ուղարկել կղզի։ Մուհամմեդ Ալիի ազդեցությունը կղզում սկսվեց այս միջամտությամբ և ութ տարի անց ավարտվեց նրան Կրետեի կուսակալությունը տալով։", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Իսմայիլ փաշայի սպանությունը Շենդիում", "223860c9"], "d": ["Ծանր հարկերի և զինվոր պահանջելու դեմ զայրացած տեղական էմիր Նիմրը, հրկիզելով նրա իջևանած տունը, այրեց Իսմայիլ փաշային և նրա շքախումբը։ Վրեժխնդրության արշավանքը շրջանը վերածեց արյան լճի. դրանից հետո Սուդանի կառավարումը հիմնվեց խստության վրա։", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Մահմուդ II-ը Մորեայի համար օգնություն խնդրեց Մուհամմեդ Ալիից", "03594a42"], "d": ["Ենիչերիական բանակով երեք տարում չճնշվող Մորեայի ապստամբության համար փադիշահը դիմեց եվրոպական ձևով մարզված եգիպտական բանակին։ Փոխարենը խոստացվեց Մորեայի կուսակալությունն ու Կրետեն։ Այս խնդրանքը կայսրության՝ սեփական վիլայեթին կարոտ դառնալու առաջին բացահայտ խոստովանությունն էր։", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Իբրահիմ փաշան ափ իջավ Մոդոնում", "9c993dba"], "d": ["Եգիպտական նավատորմի պաշտպանությամբ ափհանման ուժը ոտք դրեց Մորեայի հարավարևմտյան ծայրին։ Կանոնավոր հետևակով և դաշտային հրետանիով զինված այս բանակը կարճ ժամանակում գերակշռություն հաստատեց ապստամբ խմբերի նկատմամբ։", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Տրիպոլիցան հետ վերցվեց — Մորեայի կենտրոնն ընկավ", "8a478c11"], "d": ["Ապստամբության վարչական կենտրոն Տրիպոլիցայի անկմամբ Մորեայի մեծ մասը կրկին անցավ վերահսկողության տակ։ Քարտեզում թերակղզին, քանի որ եգիպտական ուժերի ձեռքում է, հայտնվում է ենթակայության երանգով։", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Միսսոլոնգին (Մեսոլոնգի) ընկավ", "07257f87"], "d": ["Մեկ տարի տևած պաշարումից հետո քաղաքը գրավվեց։ Սակայն պաշտպանության արձագանքը եվրոպական մամուլում հունական գործի հանդեպ համակրանքը հասցրեց գագաթնակետին և հող նախապատրաստեց մեծ տերությունների միջամտության համար։", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Աթենքի Ակրոպոլիսը հանձնվեց", "3b19f946"], "d": ["Ակրոպոլիսի անկմամբ հունական ապստամբությունը ռազմական առումով գրեթե ավարտվել էր։ Հենց այդ կետում հարցը ներքին ապստամբություն լինելուց դուրս եկավ և դարձավ եվրոպական դիվանագիտության թեմա։", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Լոնդոնի պայմանագիրը՝ երեք պետությունները պարտադրեցին հունական ինքնավարություն", "7ce46fd8"], "d": ["Անգլիան, Ֆրանսիան և Ռուսաստանը որոշեցին միասին գործել՝ օսմանցիների և հույների միջև հրադադարի և ինքնավարության պայմանն ընդունել տալու համար. տեղեկացվեց, որ մերժման դեպքում իրենց նավատորմերը կմիջամտեն։ Բարձր Դուռը մերժեց առաջարկը։", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Ալեքսանդրիայի համաձայնագիրը՝ Եգիպտոսի՝ Մորեայից դուրս գալու որոշումը", "cc978f37"], "d": ["Նավարինում նավատորմը կորցրած Մուհամմեդ Ալին, առանց Ստամբուլի հետ խորհրդակցելու, ուղղակիորեն համաձայնության գալով անգլիական ծովակալի հետ՝ ընդունեց իր ուժերը դուրս բերել Մորեայից։ Կուսակալի՝ մեծ տերությունների հետ ինքնուրույն պայմանագիր կնքելը գալիք ճգնաժամի նախանշանն էր։", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Եգիպտական ուժերը դատարկեցին Մորեան", "8fb742dd"], "d": ["Վերջին զորամասերը բարձրացվեցին նավերի վրա. թերակղզին փաստացի ձեռքից գնաց և 1830 թվականի Լոնդոնի արձանագրությամբ դարձավ անկախ Հունաստանի միջուկը։ Իսկ Մուհամմեդ Ալին չէր ստացել խոստացված Մորեայի կուսակալությունը և փոխարենը կորցրել էր մեծ նավատորմ և բանակ։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Մոդոն, Կորոն։", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Կրետեի կառավարումը թողնվեց Մուհամմեդ Ալիին", "7f76396d"], "d": ["Որպես Մորեայի կորստի փոխհատուցում՝ Կրետեի կուսակալությունը տրվեց Մուհամմեդ Ալիին։ Կղզին տասը տարի կառավարվեց Կահիրեից. քարտեզում այդ ժամանակահատվածում երևում է ենթակայության երանգով։ Նույն ամսաթվին միացած այլ վայրեր՝ Կանդիա (Կրետե)։", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Իբրահիմ փաշան մտավ Սիրիա — սկսվեց առաջին ճգնաժամը", "1a5cc386"], "d": ["Պատրվակը Աքքայի կուսակալն էր, որը չէր վերադարձնում Եգիպտոսից փախած ֆելլահներին. իրական պատճառը Սիրիայի փայտանյութի, նավահանգիստների և մարդկային ռեսուրսների՝ Մուհամմեդ Ալիի կարիքն էր։ Բանակը, անցնելով Սինայը, արագորեն գրավեց Պաղեստինի ծովափը։", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Սկսվեց Աքքայի պաշարումը", "b211d96d"], "d": ["1799 թվականին Նապոլեոնին կանգնեցրած ամրոցը վեց ամիս դիմադրեց։ Պաշարումը եգիպտական բանակի ժամանակակից հրետանու առաջին մեծ փորձությունն էր։", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Աքքան ընկավ", "0f47917b"], "d": ["Պարիսպները ռմբակոծող մարտկոցները բացվածք արեցին, և ամրոցը գրավվեց։ Բացվել էր Սիրիայի դուռը. Բարձր Դուռը նույն օրերին Մուհամմեդ Ալիին հայտարարեց ապստամբ և վերացրեց նրա կուսակալությունը։", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Դամասկոսը հանձնվեց", "48da3b62"], "d": ["Քաղաքը հանձնվեց առանց կռվի։ Իբրահիմ փաշան, հայտարարելով հարկային կարգը և ոչ մուսուլմաններին ճանաչված հավասարությունը, փորձեց շահել տեղական աջակցությունը. նույն քաղաքականությունը մի քանի տարի անց դառնալու էր նաև նրա դեմ ապստամբությունների պատճառ։ Նույն օրերին միացած այլ վայրեր՝ Բեյրութ, Տրիպոլի (Լիբանան), Սիդոն։", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Հոմսի ճակատամարտը", "867810ee"], "d": ["Սիրիան փրկելու ուղարկված օսմանյան բանակը ջախջախվեց բաց տեղանքում։ Պարզվեց, որ ենիչերիության վերացումից վեց տարի անց ստեղծված նոր բանակը դեռ պատրաստ չէր։", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Գրավվեց Հալեպը", "9c0ead76"], "d": ["Հյուսիսային Սիրիայի առևտրի և կառավարման կենտրոնը ևս ընկավ։ Այսպիսով եգիպտական բանակը հասավ Տավրոսի ստորոտներին և շարժվեց դեպի Անատոլիայի դռան լեռնանցքները։", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Բելենի (Beylan) լեռնանցքի ջախջախումը — բացվեց Կիլիկիան", "4bae872b"], "d": ["Ամանոս լեռների նեղ լեռնանցքում պաշտպանության գիծը ճեղքվեց։ Անտիոքը, Ադանան և Տարսոնը անցան եգիպտական ուժերին (Մարաշի օկուպացիան, ըստ TDV-ի, 1833 թվականն է, առանձին գրառում). քարտեզում Կիլիկիան անցնում է ենթակայության երանգի։ Անատոլիայի խորքերը տանող ճանապարհն այժմ անպաշտպան էր։", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Գյուլեքի կիրճն ընկավ — Իչելի ծովափը (Մերսին, Սիլիֆքե) անցավ եգիպտական վերահսկողության", "d9049b5b"], "d": ["Տավրոսի՝ դեպի Կիլիկիա դուռը՝ Գյուլեքի կիրճը, անցավ եգիպտական բանակի ձեռքը։ Իբրահիմ փաշան Իչելի սանջակում նշանակեց իր մյութեսելիմին (կառավարիչ), և ծովափի բոլոր նավամատույցներն անցան եգիպտական վերահսկողության տակ։ Քարտեզում Մերսինը և Սիլիֆքեն այս օրվանից (ստորին սահման. նշանակման օրը աղբյուրում նշված չէ) ցույց են տրվում Եգիպտոսին ենթակա. քանի որ Քյոթահիայի որոշմամբ անցավ միայն Ադանայի մուհասսըլությունը, այս վերահսկողությունն ավարտվում է Անատոլիայի դատարկմամբ։", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Կոնիայի Էրեղլին եգիպտական օկուպացիայի տակ — Կոնիա–Ադանա ճանապարհի տավրոսյան մուտքը", "fb908900"], "d": ["Գյուլեքի կիրճն անցած եգիպտական բանակի՝ Կոնիա տանող ճանապարհի վրա գտնվող Էրեղլին 1832 թվականին մտավ Իբրահիմ փաշայի օկուպացիայի տակ և 1833 թվականի Քյոթահիայի կարգավորմամբ դատարկվելուց հետո կրկին միացվեց Կարամանի վիլայեթին։ Քարտեզում այն Ադանայի և Կոնիայի միջև օկուպացիայի գծի աղբյուրով հիմնավորված միջանկյալ կետն է. Ուլուքըշլայի և Քարափընարի համար քաղաքի մակարդակով վկայություն չի գտնվել։", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Եգիպտական բանակը մտավ Կոնիա", "13952a2d"], "d": ["Տավրոսն անցած բանակը հասավ Կենտրոնական Անատոլիա։ Առաջին անգամ օսմանյան կուսակալի ուժերը առաջանում էին կայսրության միջուկային հողերում։ Նույն ամսաթվին միացած այլ վայրեր՝ Կարաման։", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Կոնիայի դաշտային ճակատամարտը՝ մեծ վեզիրը գերի ընկավ", "ec82cc9a"], "d": ["Մառախլապատ եղանակին ցրված օսմանյան բանակը ծանր պարտություն կրեց, և մեծ վեզիր Ռեշիդ Մեհմեդ փաշան գերի վերցվեց։ Պետության կենտրոնական բանակն այլևս գոյություն չուներ. Ստամբուլի և եգիպտական ուժերի միջև կանգնող ուժ չէր մնացել։", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Մարաշը ենթարկվեց եգիպտական օկուպացիայի", "f558e383"], "d": ["Ըստ TDV-ի՝ Մարաշը 1833 թվականին ենթարկվեց Կավալացի Իբրահիմ փաշայի օկուպացիային և մոտ տասնինը ամիս մնաց նրա կառավարման տակ։ Քանի որ Մարաշը Քյոթահիայի կարգավորման էյալեթային սահմաններից դուրս էր, այս կառավարումը իրավաբանական չէ, այլ փաստացի։", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Քարահիսար-ը Սահիբը (Աֆյոն) ենթարկվեց եգիպտական օկուպացիայի — Կոնիա–Քյոթահիա ճանապարհը", "ae0c2c78"], "d": ["Կոնիայի դաշտային ճակատամարտից հետո դեպի Քյոթահիա առաջացող եգիպտական բանակի ճանապարհի վրա գտնվող Քարահիսար-ը Սահիբը 1833 թվականին որոշ ժամանակ մնաց Իբրահիմ փաշայի ձեռքում։ Քարտեզում այն Կոնիայի և Քյոթահիայի միջև օկուպացիայի գծի աղբյուրով հիմնավորված միջանկյալ կետն է. Աքշեհիրի, Ըլգընի և Իսհակլըի համար քաղաքի մակարդակով վկայություն չի գտնվել, դրանք օսմանյան գույնով են։", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Եգիպտական բանակը հասավ Քյոթահիա", "214f8df6"], "d": ["Իբրահիմ փաշան կանգ առավ Ստամբուլից երեք օթևան հեռավորության վրա գտնվող Քյոթահիայում։ Նրա՝ առաջ չգնալու պատճառը ոչ թե ռազմական, այլ քաղաքական էր. հաշվի էին առնվել ռուսական միջամտությունը և Եվրոպայի արձագանքը։", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Ռուսական նավատորմը Բյույուքդերեի առջև", "6f836d61"], "d": ["Անգլիայից և Ֆրանսիայից օգնություն չստացած Մահմուդ II-ը դիմեց իր երեկվա թշնամուն՝ Ռուսաստանին։ Փադիշահի «խեղդվողը օձից էլ կկառչի» խոսքով հիշվող այս որոշումը հանգեցրեց ռուս զինվորների ափհանմանը նեղուցներում և տագնապի ահազանգ հնչեցրեց Եվրոպայում։", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Քյոթահիայի փոխզիջումը (բանավոր) — Սիրիան և Ադանան՝ Կավալացուն", "25fe9985"], "d": ["Բարձր Դուռը Եգիպտոսից, Կրետեից և Հիջազից բացի Մուհամմեդ Ալիին թողեց Դամասկոսի, Հալեպի, Տրիպոլիի (Լիբանան) և Սիդոնի կուսակալությունները, իսկ Ադանայի մուհասսըլությունը՝ Իբրահիմ փաշային։ Փոխարենը բանակը հետ քաշվեց Տավրոսից հարավ։ Սա պայմանագիր չէր, այլ փադիշահի՝ կուսակալին տված ֆերմանների տեսքով էր. հարցը չէր լուծվել, այլ հետաձգվել էր։", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Եգիպտական բանակի նահանջը Անատոլիայից ավարտվեց Գյուլեքի կիրճով", "a53ac2a3"], "d": ["Քյոթահիայի կարգավորումից հետո եգիպտական ուժերը դատարկեցին Անատոլիան. մոտ հունիսի կեսերին բանակն ամբողջությամբ Գյուլեքի կիրճով անցավ Կիլիկիա։ Իչելի ծովափը (Մերսին, Սիլիֆքե) կրկին վերադառնում է օսմանյան կառավարման. Ադանայի մուհասսըլությունը և Սիրիան մնում են Եգիպտոսին։", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Հյունքյար Իսքելեսիի պայմանագիրը", "da741d5c"], "d": ["Ռուսաստանի հետ ստորագրվեց ութամյա փոխադարձ պաշտպանական դաշինք։ Ըստ գաղտնի հոդվածի՝ եթե Ռուսաստանը ենթարկվեր հարձակման, Օսմանյան պետությունը նեղուցները փակելու էր ռազմանավերի առաջ։ Սա դարձավ օսմանյան դիվանագիտության ամենավիճելի որոշումներից մեկը և Անգլիային ակտիվացրեց եգիպտական հարցում։", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Պաղեստին-Նաբլուսի ապստամբությունը եգիպտական կառավարման դեմ", "4fe43e27"], "d": ["Պարտադիր զինվորական ծառայությունը, զենքի հավաքումը և նոր հարկերը Պաղեստինում հանգեցրին լայն ապստամբության։ Ապստամբությունը դաժանորեն ճնշվեց. եգիպտական կառավարման աջակցությունը տեղական ժողովրդի աչքում արագ հալվեց։", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Մարաշում եգիպտական կառավարման ավարտը (մոտավոր)", "bb46ca42"], "d": ["TDV-ի «մոտ տասնինը ամիս» տևողությունը 1833 թվականի օկուպացիայից հաշվելով՝ եգիպտական կառավարումն ավարտվում է մոտ 1834 թվականի ամռանը։ Այն, որ Քյուչյուքալի-օղլուներից Մուստաֆա բեյը 1834 թվականին, չկարողանալով դիմակայել եգիպտական բանակին, քաշվեց դեպի Մարաշի կողմերը, ցույց է տալիս, որ Մարաշն այդ ժամանակ եգիպտական վերահսկողությունից դուրս ապաստարան էր։", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Ջաբալ ադ-Դուրուզի ապստամբությունը", "12e74626"], "d": ["Դրուզական շրջանում ծագած դիմադրությունը տևեց երկու տարի։ Սիրիայում կուտակված դժգոհությունը 1840 թվականին, երբ դաշնակից նավատորմերը ափ իջան, դատարկելու էր եգիպտական բանակի թիկունքը։", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Մուհամմեդ Ալին հայտնեց անկախության մտադրությունը", "48633bbd"], "d": ["Կուսակալը մեծ տերությունների հյուպատոսներին հայտնեց, որ մտածում է հռչակել Եգիպտոսի և Սիրիայի անկախությունը։ Անգլիան վճռականորեն դեմ արտահայտվեց. Միջերկրական ծովում հզոր և Ֆրանսիային մոտ պետության ծնունդը կսպառնար Հնդկաստանի ճանապարհին։", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Օսմանյան բանակն անցավ Եփրատը", "9af1ea69"], "d": ["Մահմուդ II-ը, Քյոթահիայում կորցրածը հետ վերցնելու համար, իր բանակը մղեց Սիրիայի սահման։ Բանակում որպես խորհրդական գտնվող պրուսացի սպա Մոլտկեն առարկեց դիրքերի ընտրությանը և վաղաժամ հարձակմանը. նրա առարկությունները չլսվեցին։", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Նիզիպի ճակատամարտը — օսմանյան բանակը ցրվեց", "156b3cdf"], "d": ["Վատ դասավորված օսմանյան բանակը մի քանի ժամում ջախջախվեց։ Մինչ պարտության լուրը կհասներ Ստամբուլ, փադիշահը մահացավ. մի քանի օրվա ընթացքում պետությունը կորցնելու էր իր բանակը, տիրակալին, ապա նաև նավատորմը։", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Մահմուդ II-ի մահը", "07eccfff"], "d": ["Երեսունմեկ տարվա գահակալության ընթացքում ենիչերիությունը վերացրած և կենտրոնական կառավարումը վերականգնած փադիշահը մահացավ՝ չհաղթելով իր ամենամեծ հակառակորդին։ Նրա հիվանդությունը ճիշտ չէր ախտորոշվել։ Նրա մահը, ենիչերիական մտածելակերպի շարժման մեջ մտնելու վախից, թաքցվեց մինչև հունիսի 30-ը, մինչ քաղաքում ռազմական միջոցներ ձեռնարկվեցին։", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Աբդուլմեջիդի գահակալումը և Մահմուդ II-ի հուղարկավորությունը", "d0f3d2cc"], "d": ["Հոր մահից հետո գահ բարձրացավ տասնվեցամյա Աբդուլմեջիդը։ Նույն օրը Մահմուդ II-ի դին բերվեց Թոփքափի պալատ. վախեցած խառնակությունը տեղի չունեցավ, մուսուլման և ոչ մուսուլման լայն զանգվածներ մասնակցեցին հուղարկավորության թափորին։", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Նավատորմի հանձնումը Ալեքսանդրիային", "a53e6103"], "d": ["Կապուդան փաշա Ահմեդ Ֆևզի փաշան, կասկածելով, որ մեծ վեզիր Քոջա Խյուսրև փաշան նավատորմը տալու է Ռուսաստանին, նավատորմը տարավ Ալեքսանդրիա և հանձնեց Մուհամմեդ Ալիին։ Օսմանյան պետությունը նույն ամսվա ընթացքում մնաց առանց բանակի, առանց փադիշահի և առանց նավատորմի։", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Մեծ տերությունների համատեղ նոտան", "2a3b8316"], "d": ["Հինգ պետությունները նոտա հանձնեցին Բարձր Դռանը՝ խնդրելով եգիպտական հարցում միայնակ համաձայնագիր չկնքել։ Այսպիսով ներքին հարցը պաշտոնապես դարձավ «եվրոպական հարց». Օսմանյան պետությունը փաստացի կորցրեց իր սեփական վիլայեթի վերաբերյալ որոշում կայացնելու իրավասությունը։", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Լոնդոնի պայմանագիրը՝ չորս պետություն օսմանցիների կողքին", "a517f775"], "d": ["Ֆրանսիան դուրս թողնելով ստորագրված պայմանագիրը վերջնագիր ներկայացրեց Մուհամմեդ Ալիին. եթե տասը օրում ընդուներ՝ ժառանգական կուսակալություն Եգիպտոսում և ցմահ իրավունքով Աքքան. եթե քսան օրում ընդուներ՝ միայն Եգիպտոսը. եթե մերժեր՝ ոչինչ։ Կուսակալը մերժեց։", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Բեյրութի ռմբակոծումը և դաշնակիցների ափհանումը", "0905ce92"], "d": ["Անգլո-ավստրիական նավատորմը ռմբակոծեց Բեյրութը. Լիբանանի լեռներում եգիպտական կառավարման դեմ ապստամբած ժողովրդին զենք բաժանվեց։ Իբրահիմ փաշայի վերահսկողությունը Սիրիայում փլուզվեց ներքին ապստամբության և արտաքին միջամտության միջև։", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Բեյրութը և ափամերձ քաղաքները ձեռքից գնացին", "09bdaf23"], "d": ["Բաալբեքի ուղղությամբ ընդհարումներից հետո եգիպտական ուժերը նահանջեցին ափից։ Քարտեզում Լիբանանի ափը դուրս է գալիս ենթակայության երանգից և վերադառնում ուղղակի օսմանյան կառավարման։", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Աքքան ընկավ երկու ժամում", "5aec21f0"], "d": ["Դաշնակից նավախմբի ռմբակոծությունից ամրոցի զինապահեստը պայթեց, և Աքքան մի քանի ժամում հանձնվեց։ Ամրոցը, որ ութ տարի առաջ Իբրահիմ փաշան կարողացել էր գրավել միայն վեց ամսում, ցույց տվեց ծովային հրետանու գերազանցությունը։", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Ալեքսանդրիայի կոնվենցիան", "85cb47b0"], "d": ["Մուհամմեդ Ալին համաձայնեց հրաժարվել Սիրիայից, Ադանայից, Կրետեից և Հիջազից, վերադարձնել օսմանյան նավատորմը և ճանաչել փադիշահի գերիշխանությունը. փոխարենը երաշխավորվեց Եգիպտոսի ժառանգական կուսակալությունը։", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Եգիպտական բանակը դատարկեց Սիրիան և Կիլիկիան", "719a28dc"], "d": ["Ինը տարի տևած օկուպացիան ավարտվեց. Իբրահիմ փաշայի բանակը Սինայի վրայով վերադարձավ Եգիպտոս։ Քարտեզում Հալեպից Գազա, Ադանայից Կրետե ձգվող լայն գոտին կրկին անցնում է ուղղակի օսմանյան կառավարման։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ուրֆա, Մարաշ, Տարսոն, Անտիոք, Կանդիա (Կրետե), Համա, Դամասկոս, Երուսաղեմ, Յաֆա, Նաբլուս։", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ֆերման՝ Եգիպտոսի կուսակալությունը ժառանգաբար թողնվեց Կավալացու ընտանիքին", "87b89ff8"], "d": ["Փադիշահի ֆերմանը ճանաչեց կուսակալությունը՝ հարստության ներսում հորից որդի անցնող. փոխարենը բանակի թվակազմը կրճատվեց մինչև տասնութ հազար, հարկը կապվեց Ստամբուլին, վերացվեցին դրամ հատելու և պայմանագրեր կնքելու իրավասությունները։ Եգիպտոսը մնաց որպես վիլայեթ, բայց այժմ առանձին հարստության երկիր էր։ Հիջազի և երկու սրբավայրերի կառավարումը վերադարձավ Բարձր Դռանը։ Նույն ամսաթվին ենթակայության շերտից ուղղակի շերտ վերադարձած այլ բնակավայրեր՝ Մեքքա, Մեդինա, Ջիդդա, Յանբու։", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Լոնդոնի նեղուցների կոնվենցիան", "0e95a1ea"], "d": ["Հյունքյար Իսքելեսիին փոխարինած կոնվենցիան սահմանեց, որ խաղաղ ժամանակ նեղուցները փակ լինեն բոլոր ռազմանավերի առաջ։ Այսպիսով Ռուսաստանի միայնակ ձեռք բերած արտոնությունը վերածվեց Եվրոպայի համատեղ երաշխիքի. նեղուցների հարցն ստացավ միջազգային կարգավիճակ։", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Իբրահիմ փաշան փաստացի դարձավ Եգիպտոսի կուսակալ", "9e14f5d9"], "d": ["Ծերացող և մտավոր ունակությունները կորցնող Մուհամմեդ Ալիի փոխարեն կուսակալությունը հանձնվեց նրա որդի Իբրահիմ փաշային։ Սակայն մի քանի ամիս անց՝ 1848 թվականի նոյեմբերին, նա մահացավ հորից առաջ։", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Կավալացի Մուհամմեդ Ալի փաշայի մահը", "871310e0"], "d": ["Կավալայում ծնված, Եգիպտոսում հարստություն հիմնած, կայսրությունը երկու անգամ անդունդի եզրին հասցրած կուսակալը մահացավ ութսուն տարեկանում։ Նրա հիմնած հարստությունը իշխեց Եգիպտոսում մինչև 1953 թվականը. իսկ պետությունը, տեսնելով, որ նրա բացած վերքը կարողացել է փակել եվրոպական միջամտությամբ, առաջ գնաց Թանզիմաթի ուղիով։", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Սուլեյման բ. Քութալմիշը պարտվեց և զոհվեց Այն Սեյլեմում. Անտիոքը դուրս եկավ Անատոլիայի սելջուկների ձեռքից", "0412dfa1"], "d": ["1084 թ. Անտիոքը Բյուզանդիայից գրաված Սուլեյման բ. Քութալմիշը զոհվեց Սիրիայի սելջուկ տիրակալ Թութուշի դեմ Այն Սեյլեմի ճակատամարտում. քաղաքն անցավ Մեծ սելջուկների սուլթան Մելիքշահի վերահսկողության տակ, և կուսակալ նշանակվեց Յաղըսյանը։", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Մելիքշահը մահացավ. Անտիոքը Յաղըսյանի հետ ենթարկվեց Սիրիայի սելջուկ Թութուշին", "c61da1b4"], "d": ["Մեծ սելջուկների սուլթան Մելիքշահի մահից հետո պետությունը բաժանվեց ժառանգների միջև. Անտիոքի կուսակալ Յաղըսյանը ենթարկվեց Սիրիայի տիրակալ Թութուշին։", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Նիկիան հանձնվեց խաչակիրներին. սելջուկյան կենտրոնը տեղափոխվեց Կոնիա, Բյուզանդիան սկսեց վերագրավել արևմտյան Անատոլիան", "8a4e90fa"], "d": ["Խաչակիրների կողմից Նիկիայի (Իզնիկ) պաշարումից հետո քաղաքը 1097 թ. հունիսի 19-ին հանձնվեց Բյուզանդիային. սելջուկ սուլթան Քըլըչ Արսլան I-ը իր կենտրոնը տեղափոխեց երկրի խորքը՝ Կոնիա, իսկ Բյուզանդիան վերագրավեց արևմտյան Անատոլիայի ափերի այնպիսի վայրեր, ինչպիսին է Եփեսոսը։", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Քըլըչ Արսլան II-ը Բյուզանդիայից գրավեց Դորիլեոնը (Էսքիշեհիր) և Քյոթահիան", "3ddee6c2"], "d": ["Միրիոկեֆալոնից (1176) հետո Անատոլիայի ներսում գտնվող բյուզանդական Դորիլեոն և Քյոթահիա բերդերը Մանուելի վերջին տարիներին/մահից հետո՝ 576/1180 թ., անցան Քըլըչ Արսլան II-ի ձեռքը։", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Կարամանօղլու Մեհմեդ բեյը նշանակվեց Էրմենեքի սուբաշի և իր կառավարման տակ վերցրեց Իչ Իլը", "6d62be11"], "d": ["Կարամանօղլու Մեհմեդ բեյը 675 (1276) թ. նշանակվեց Էրմենեքի սուբաշի և իր կառավարման տակ վերցրեց Իչ Իլը. Էրմենեքը դարձավ հաջորդ տարի Կոնիայի վրա շարժվելու Կարամանօղուլների առաջին կենտրոնը։", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Էրթուղրուլ Ղազիի մահը և Օսման բեյի՝ բեյլիքի գլուխ անցնելը — Սոյութի և Դոմանիչի ժառանգությունը", "395fb9fa"], "d": ["Ըստ TDV-ի՝ Էրթուղրուլ Ղազին մահացել է 680 (1281-82) թվականին. հոդվածը նշում է, որ տրվում են նաև 1288 և 1289 թվականները։ Օսման բեյը հորից ստացավ ոչ թե նվաճված քաղաք, այլ սելջուկյան սուլթանի՝ սահմանամերձ շրջանի ամենաառաջ գծում տեղավորած Էրթուղրուլին տված երկու հատկացումները՝ Սոյութում ձմեռանոց (yurtluk) և Դոմանիչում ամառանոց։ Այսինքն՝ բեյլիքն իր գործը սկսել է ոչ թե նվաճման ժառանգությամբ, այլ երկու արոտավայրի հատկացմամբ. քարտեզում այս երկու վայրերը ցույց են տրվում ոչ թե որպես «նվաճում», այլ որպես «ժառանգություն»։", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Սիցիլիական երեկոյան — Անժու հարստությունը կորցրեց Սիցիլիա կղզին", "547db635"], "d": ["Պալերմոյում Զատկի երկուշաբթի օրը, երեկոյան աղոթքի ժամին, Շառլ I Անժուացու կառավարման դեմ բռնկված ապստամբությունը Սիցիլիա կղզին պոկեց Անժու հարստությունից։ Սիցիլիայի թագավորությունը բաժանվեց երկու մասի. կղզին ուղղվեց դեպի Արագոն, իսկ Անժու հարստությունը պահպանվեց Նեապոլ կենտրոնով մայրցամաքային թագավորությունում։ Հարստության ադրիատիկյան և միջերկրածովյան արտաքին տիրույթները ևս մնացին կապված այս թագավորությանը. 1267 թվականից իրենց ձեռքում գտնվող Կորֆուն և 1270-ականներից պահվող Դուրեսը շարունակեցին մնալ Նեապոլի թագավորության մաս. Ալբանիայի ափի Վլյորա, Կանինա և Խիմարա ամրոցները ևս մնացին Նեապոլ կենտրոնով թագավորությունում (Վլյորայի հրամանատար John of Taxis-ը 1282 թվականի ողջ ընթացքում դիմադրեց բյուզանդացիներին. Դուրեսը, Վլյորան և Կանինան, ամենայն հավանականությամբ, 1285 թվականի սկզբին անցան Բյուզանդիային)։ Իսկ Մալթան անցավ արագոնացիների ձեռքը միայն 1284 թվականին։", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Կուլաջահիսարի հարձակումը — Օսման բեյի առաջին ռազմական գործողությունը", "79b00b14"], "d": ["TDV-ի «Օսման I» հոդվածը. «Ինեգյոլի մոտ փոքր Կուլաջա Հիսարը թալանեց և հրի մատնեց (684/1285)»։ Սա Օսման բեյի՝ աղբյուրներում թվագրելի առաջին ռազմական գործողությունն է։ Մշտական բնակավայր չի գրավվել, ամրոցը թալանվել և այրվել է. հետևաբար դա ոչ թե նվաճում, այլ դասական սահմանային ասպատակություն է։ Համարվում է բեյլիքի ռազմական գործունեության ելակետը։", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Քարաջահիսարի նվաճումը — առաջին քաղաքային ձեռքբերումը և տիրապետությունը Էսքիշեհիրին", "178ae619"], "d": ["TDV-ի «Օսման I» հոդվածը. Օսման բեյը 687 (1288) թվականին «նվաճելով Քարաջահիսարը՝ տիրեց Էսքիշեհիրին»։ Սա բեյլիքի առաջին իրական քաղաքային ձեռքբերումն է, և ըստ ավանդության՝ այս հաջողությամբ Օսման բեյը սահմանամերձ շրջանում բարձրացել է սանջակի բեյության. պատմվում է, որ նրա անունով առաջին ուրբաթօրյա խուտբան ընթերցվել է Քարաջահիսարում, և այստեղ նշանակվել է առաջին կադին։ TDV-ի «Էսքիշեհիր» հոդվածը նշում է, որ օսմանյան ավանդույթը տալիս է 1291 թվականը, սակայն դրա ճշմարտացիությունը կասկածելի է։", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Աքքայի անկումը մամլուքների ձեռքը — խաչակիրների վերացումը Սիրիայի ափից՝ Սիդոն և Բեյրութ", "3ca7a464"], "d": ["Երկար ժամանակ Երուսաղեմի խաչակիր թագավորության կենտրոնը եղած Աքքան նվաճեց մամլուքների սուլթան ալ-Մալիք ալ-Աշրաֆ Խալիլը, և խաչակիրների տիրապետությունը Պաղեստինում ավարտվեց։ Աքքայից նահանջած տամպլիեր ասպետները ապաստանեցին Սիդոնում. մամլուքների բանակի մոտենալուն պես նրանք լքեցին ծովային ամրոցը և փախան Կիպրոս, և քաղաքը նույն ամառը անցավ մամլուքներին։ 1197 թվականից խաչակիրների ձեռքում գտնվող Բեյրութը ևս 1291 թվականին գրավեց Դամասկոսի կուսակալ Սինջար ալ-Շուջաին։ Այսպիսով խաչակիրների երկու դարի ներկայությունը ջնջվեց Սիրիա-Պաղեստինի ափից։", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Բիլեջիքի և Յարհիսարի նվաճումը գիշերային հարձակմամբ", "f461b0af"], "d": ["TDV-ի «Բիլեջիք» հոդվածը. «Թեև Բիլեջիքի տեքֆուրը, այդ թվում նաև շրջանի մյուս տեքֆուրները, Օսման Ղազիի դեմ մահափորձ նախապատրաստեցին, երբ այդ դավադրությունը հայտնի դարձավ, օսմանյան ուժերը հանկարծակի հարձակմամբ նվաճեցին Յարհիսարը և Բիլեջիքը (1299)»։ Երկու ամրոցները գրավվել են մեկ գործողությամբ, նույն գիշերային հարձակմամբ։ Այս ամսաթիվը շրջադարձային կետ է, որն ընդունվում է որպես Օսմանյան պետության հիմնադրման տարի։ Նույն ամսաթվին միացած այլ վայրեր՝ Ինեգյոլ։", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Քոյունհիսարի (Բաֆեոս) ճակատամարտը — բյուզանդական բանակի դեմ առաջին մեծ հաղթանակը", "584a9512"], "d": ["TDV-ի «Օսման I» հոդվածը. Օսման բեյը 1302 թվականի հուլիսի 27-ին Բաֆեոսում (Քոյունհիսար) կռվեց բյուզանդական բանակի դեմ և հաղթեց նրան։ Այս հաղթանակը շրջադարձային կետ է, որը Օսման բեյին տարածաշրջանային սահմանամերձ բեյից բարձրացրեց հարստության հիմնադրի կարգավիճակի։ Ճակատամարտից հետո Բուրսայի դաշտավայրն անցավ օսմանյան վերահսկողության տակ, սկսվեց Իզնիկի շրջափակումը։", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Դիմբոսի հաղթանակը և այնուհետև Քիթեի ու Ուլուբաթի գրավումը", "e168ab64"], "d": ["TDV-ի «Օսման I» հոդվածը. 702 (1303) թվականին Բուրսայի, Քեսթելի, Քիթեի և Ադրանոսի տեքֆուրների կազմած դաշինքը ջախջախվեց Դիմբոսի կիրճում. թշնամին կռվելով նահանջեց մինչև նեղ կիրճը, և Քեսթելի տեքֆուրը զոհվեց մարտադաշտում։ Հաղթանակից անմիջապես հետո գրավվեցին Քիթեի և Ուլուբաթի ամրոցները՝ կտրելով Բուրսայի ցամաքային կապը և խստացնելով նրա շրջափակումը։ Երիտասարդ Օրհանը ևս մասնակցել է այս ճակատամարտին։", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Սաքարիայի արշավանքը՝ Լեբլեբիջիհիսարի, Լեֆքեի, Մեքեջեի և Գեյվեի գրավումը", "a51ba4d3"], "d": ["TDV-ի «Օսման I» հոդվածը տալիս է 704 (1304) թվականի Սաքարիայի արշավանքի հաջորդականությունը. «Երբ հասավ Լեբլեբյուջի ամրոցին, տեքֆուրը հնազանդվեց... Հասավ Լեֆքե... Հասավ Մեքեջե... Գնաց Գեյվե և գրավեց ամրոցը, որը դատարկ գտավ»։ Լեֆքեն Սաքարիայի հովտի՝ դեպի Բիլեջիք բացվող դարպասն է։ Այս մեկ արշավանքով, հովտի երկայնքով ձգվող ամրոցների շղթան անցնելով օսմանյան վերահսկողության, փակվեց Իզնիկի ավազանի արևելյան թևը։", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Քիոսն անցավ ջենովացի Ձակկարիա ընտանիքի վերահսկողության տակ", "9eebe4de"], "d": ["Այդընօղուլների սպառնալիքի պայմաններում Բյուզանդիայի կայսրը օգնություն խնդրեց ջենովացի Բենեդետտո Ձակկարիայից. կղզին անցավ նրա վերահսկողության տակ (անվանական բյուզանդական վասալություն)։ Ձակկարիաների տիրապետությունը տևեց մինչև 1329 թ.։", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Սամոսն անցավ Քիոսի ջենովացիների (Ձակկարիա) սեփականության տակ", "0e6f51e3"], "d": ["Քիոսը վերահսկողության տակ վերցրած ջենովացի Ձակկարիա ընտանիքը իր սեփականությանը միացրեց նաև գրեթե ամայացած Սամոսը (TDV. 1304-1329)։", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Գեյվեի կիրճի ամրոցների նվաճումը՝ Քարաչեփյուշ, Քարաթիգին և Աբսու", "76907c78"], "d": ["TDV-ի «Օրհան» հոդվածը. Օրհանը 705 (1305) թվականի Սաքարիայի արշավանքում «նվաճեց Քարաչեփյուշի (Katoikia), Իզնիկի առջևի Քարաթիգինի և Աբսուի (Hypsu՝ Գեյվեի կիրճում) ամրոցները»։ Այս երեք ամրոցը, փակելով Սաքարիայի հովտի և Իզնիկի ավազանի միջև անցումը, ամբողջությամբ կտրեցին Իզնիկի ցամաքային օգնությունը։ Գեյվեի կիրճի Քարաչեփյուշում և Աբսուում տեղավորվեց Ղազի Աբդուրռահմանը. քաղաքն այլևս կարող էր ընկնել միայն սովից։", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Ադրանոսի (Օրհանելի) արշավանքը — Օսման բեյի վերջին արշավանքը", "4811546c"], "d": ["TDV-ի «Օրհան» հոդվածը 1323 թվականի աշնան Ադրանոսի ամրոցի արշավանքը գրանցում է որպես Օսման բեյի վերջին արշավանք։ Ադրանոսի տեքֆուրը այն տեքֆուրների դաշինքի անդամն էր, որը քսան տարի առաջ Դիմբոսում կազմվել էր օսմանցիների դեմ. այս արշավանքը նշանակում էր այդ հաշիվը փակել։ Ամրոցի վերջնական նվաճման օրն անհայտ է. գործողությունները շարունակել է Օրհան բեյը։", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Օսման Ղազիի մահը և Օրհան բեյի՝ բեյլիքի գլուխ անցնելը", "021487cd"], "d": ["Բեյլիքին իր անունը տված Օսման Ղազին, ըստ Ասփորչա խաթունի և Մեքեջեի վակֆնամեների վկայության, մահացել է 724 (1324) թվականին։ 1305 թվականից արշավանքներում բանակի գլուխ կանգնած նրա որդի Օրհանը հոր մահից հետո առանց որևէ գահակալական կռվի անցավ բեյլիքի գլուխ։ Հիմնադիր սերնդի՝ դրոշը առանց ցնցումների փոխանցելը ցույց է տալիս, որ սահմանամերձ բեյլիքից դեպի պետություն ձգվող ճանապարհին հարստությունն իր առաջին մեծ փորձությունն անցավ հանգիստ։", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Քիոսը վերցվեց Ձակկարիայից և միացվեց Բյուզանդիային", "f6741b26"], "d": ["Անդրոնիկոս III կայսրը Ձակկարիային հեռացրեց կղզուց և կղզին, Բենեդետտո III-ի կուսակալությամբ, միացրեց Բյուզանդիային։ 1346 թ. կղզին օկուպացնելու էր ջենովացի Սիմոնե Վինյոզին։", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Սամոսը Ձակկարիայից վերադարձավ Բյուզանդիային (Քիոսի շղթա)", "08034974"], "d": ["Ձակկարիաների լորդության անկումով (1329 թ. Քիոսի միացումը Բյուզանդիային) Սամոսում ջենովական սեփականությունը նույնպես դադարեց։", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Պելեկանոնի (Մալթեփե) ճակատամարտը և ամբողջ Քոջաելիի գրավումը", "389e7bd4"], "d": ["TDV-ի «Օրհան» հոդվածը. ճակատամարտի առաջին օրը Օրհան Ղազին բյուզանդական բանակը դեպի իրեն գրավելու համար ուղարկեց երեք հարյուր հոգուց բաղկացած ուժ. երկրորդ օրը Փազարլուի հրամանատարության ներքո ջոկատների հարթավայր իջնելով ճակատամարտը մեծացավ, և կայսեր նետով վիրավորվելուց բյուզանդական բանակում խուճապ սկսվեց։ Արդյունքը վճռական էր. «Օրհանը գրավեց ամբողջ Քոջաելին. հաղթանակից հետո իզնիկցիների ոչ մի հույս չմնաց»։ Հերեքեից մինչև Ուսկյուդար ծովափնյա ավաններն անցան օսմանյան իշխանության տակ, Գեբզեն դարձավ շրջանի կենտրոն։ Սա Ստամբուլը փրկելու եկած բյուզանդական կայսերական վերջին բանակն էր։", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Իզնիկում առաջին օսմանյան մեդրեսեի հիմնադրումը", "c85fb625"], "d": ["Իզնիկը գրավելուց անմիջապես հետո Օրհան բեյը այստեղ կադի նշանակեց Չանդարլը Կարա Հալիլին, մի բազիլիկա վերածեց մզկիթի և կողքին իմարեթ ու մեդրեսե կառուցել տալով՝ սկիզբ դրեց քաղաքի վերաշինությանը։ Ըստ TDV-ի «Դավուդ-ի Կայսերի» հոդվածի՝ մեդրեսեի շինարարությունն ավարտվեց 1336 թվականին, և Օրհան Ղազին նրա դասախոսի (մյուդեռիսի) պաշտոնին, օրական 30 ակչեով, բերեց Դավուդ-ի Կայսերիին։ Այս մեդրեսեն օսմանյան գիտական կյանքի առաջին ինստիտուցիոնալ քայլն է. բեյլիքը նվաճման ուժի կողքին ավելացրեց նաև գիտական ավանդույթ։ Նվաճմամբ վերցված բյուզանդական մայրաքաղաքի վերածվելը իսլամական գիտական կենտրոնի օսմանցիների՝ նստակյաց պետություն դառնալու հավակնության առաջին կոնկրետ նշանն էր։", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Բյուզանդիայի խարաջատու դառնալը — Իզմիթի պաշարումը և պայմանագիրը", "0c1ec8d3"], "d": ["TDV-ի «Օրհան» հոդվածը. Օրհանը 733 (1333) թվականի ամռանը մեծ բանակով և քարանետ մեքենաներով պաշարեց Իզմիթը, կայսրը համաձայնեց պայմանագրի։ Պաշարումից հրաժարվելու դիմաց Բյուզանդիան համաձայնեց Օրհանին տարեկան վճարել 12.000 ոսկի (հիպերպիրոն). «այսպիսով օսմանյան էմիրի աչքում Բյուզանդիան վերածվեց խարաջատու երկրի»։ Փոխարենը Օրհանը լինելու էր կայսեր բարեկամը և չէր հարձակվելու Բյուզանդիային ենթակա քաղաքների վրա։ Սահմանամերձ բեյլիքի՝ Արևելյան Հռոմին հարկատու դարձնելը ուժերի հավասարակշռության ինչքան փոխվելու հռչակումն էր։", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Սամոթրակեն վենետիկցիներից անցավ ջենովացի Գատիլուզիո ընտանիքին", "c499ed5f"], "d": ["1204 թ. ի վեր կղզին իրենց ձեռքում պահող վենետիկցիներին ջենովացի Գատիլուզիո ընտանիքը դուրս մղեց կղզուց։", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Կարեսիի բեյլիքի բռնակցումը՝ Բալըքեսիր, Բերգամա, Բիղա, Էդրեմիթ և Էրդեք", "c7cb0511"], "d": ["TDV-ի «Օրհան» հոդվածը (Ինալջըք) բռնակցումը դնում է 735 (1334-35) թվականին. Դեմիրհան բեյի մահից հետո Կարեսիի ղազիները և Հաջի Իլբեյը, գահի հրավիրելով Դուրսուն բեյին, օգնություն խնդրեցին Օրհանից։ Օրհանը նախ շարժվեց Բալըքեսիրի վրա. երբ խաղաղության բանակցության գնացած Դուրսուն բեյը մահացավ Բերգամայի ամրոցից արձակված նետից, բեյլիքն ամբողջությամբ միացավ օսմանյան երկրին։ Նույն գործողությունների ընթացքում հնազանդվեցին Քիրմաստին և Միհալիչը, գրավվեց Գյոլյազըն, և նախկինում անվտանգության երաշխիքով թողնված Ուլուբաթը վերջնականապես զավթվեց։ Օրհանը Կարեսիի սանջակում նշանակեց Սուլեյման փաշային և Բիղան դարձրեց սահմանամերձ կենտրոն. այսպիսով ձեռք բերվեց Ռումելի անցնելու ծովային կադրը։ Նշում. TDV-ի «Կարեսի-օղլուներ» հոդվածը նույն իրադարձության համար տալիս է 746 (1345) թվականը. հանրագիտարանը հակասում է ինքն իրեն։ Նույն ամսաթվին միացած այլ վայրեր՝ Չանաքքալե։", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Սամոսն անցավ Քիոսի Մահոնայի սեփականության տակ", "01628b2f"], "d": ["Այն բանից հետո, երբ ջենովացի Սիմոնե Վինյոզին գրավեց Քիոսը, և կառավարումը հանձնվեց Մահոնա ընկերությանը, Սամոսը նույնպես անցավ Քիոսի ջենովացիների (Մահոնա) սեփականության տակ (TDV. 1346-1475)։", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Օրհան Ղազիի առաջին կապիտուլյացիան ջենովացիների հետ", "e64cb196"], "d": ["Վենետիկա-ջենովական պատերազմի ժամանակ ջենովացիների հետ համաձայնության եկած Օրհան Ղազին 1352 թվականի փետրվարի Բոսֆորի ճակատամարտից հետո Պերայի պաշտպանությանն ուղարկեց 1000 նետաձիգ և զինվորների տեղափոխման համար տրամադրեց 60.000 ոսկի. փոխարենը ջենովացիներին շնորհեց առաջին կապիտուլյացիան։ Պայմանագրի ամբողջական տեքստը մեր օրերը չի հասել։ Սա օսմանցիների՝ եվրոպական ծովային ուժի հետ կնքած առաջին պաշտոնական համաձայնագիրն է, որը երեսունհինգ տարի անց՝ 1387 թվականին, վերանորոգվելու էր։", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Գելիբոլուի գրավումը — մշտական պլացդարմ Ռումելիում", "ba51a160"], "d": ["1349-1352 թվականներին որպես Կանտակուզենոսի դաշնակից շրջակայքին ծանոթացած օսմանցիները 1354 թվականին գրավեցին Գելիբոլուն. հնարավորությունը ստեղծել էր քաղաքի պարիսպները ավերած մեծ երկրաշարժը։ Այսպիսով Չիմփեի նեղ պլացդարմը վերածվեց նեղուցի ռումելիական ափի իրական հենակետի, և դեպի Թրակիա բացվող դուռը լայն բացվեց։ Գելիբոլուն 1366 թվականին Սավոյայի խաչակրաց արշավանքով ձեռքից գնալու էր, բայց 1376 թվականի երկրորդ նվաճմամբ վերջնականապես անցնելու էր օսմանյան տիրապետության տակ։ Նույն ամսաթվին միացած այլ վայրեր՝ Քիլիթբահիր։", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Ռումելիի նվաճող Սուլեյման փաշայի մահը", "2dc98228"], "d": ["Օրհան բեյի ավագ որդին և Ռումելիի նվաճումների ճարտարապետ Սուլեյման փաշան աղբյուրներում 758 (1357), 759 և 760 (1359) թվականներով տրվող ամսաթվերից առավել ընդունվածը եղած 1357 թվականի աշնանը որսի ժամանակ ձիուց ընկնելով մահացավ։ 1352-1354 թվականների անցումներով Ռումելիում մշտական օսմանյան ներկայությունը հիմնած շահզադեի մահը գահաժառանգության հերթը թողեց եղբորը՝ Մուրադին։ Բոլայիրում թաղված Սուլեյման փաշայի դամբարանը մնաց որպես Եվրոպայում օսմանյան հնագույն հարստական հուշարձան։", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Փենջիքի օրենքը — ենիչերիական զորաբանակի հիմքի դրումը", "e5877c2d"], "d": ["Ռումելիի նվաճումներից հետո ուլեմաներից Կարամանցի Կարա Ռուստեմի խորհրդով ուժի մեջ մտավ փենջիք համակարգը, որը նախատեսում էր պետությանը հատկացնել ռազմագերիների մեկ հինգերորդը կամ դրա դրամական համարժեքը։ Այս գերիներից ընտրվածների՝ թուրքական ընտանիքների մոտ դաստիարակվելով զինվորագրվելով ձևավորվեց ուղղակիորեն փադիշահին ենթակա մշտական հետևակային ուժի՝ ենիչերիական զորաբանակի միջուկը։ Ցեղային հեծելազորի վրա հիմնված սահմանամերձ բեյլիքի՝ կենտրոնացված բանակ ունեցող պետության վերափոխումը սկսվեց այս կարգավորմամբ։", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Իջնելը Արևմտյան Թրակիա՝ Գյումյուլջինեի նվաճումը", "9ef69221"], "d": ["Էդիրնեի գրավումից հետո Մարիցայից արևմուտք շարժված սահմանապահ ուժերը Ղազի Էվրենոս բեյի հրամանատարությամբ գրավեցին Արևմտյան Թրակիայի կենտրոն Գյումյուլջինեն։ Քաղաքը դարձավ առաջապահ ռազմակայան, որտեղից Էվրենոս բեյը իր ասպատակությունները տանելու էր Մակեդոնիա։ Այսպիսով Թրակիայի՝ դեպի Էգեյան ծովի ափ ձգվող հատվածն անցավ օսմանյան վերահսկողության, և բացվեց Սալոնիկի ճանապարհը։", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Վառնան անցավ Դոբրուջայի իշխանապետությանը և դարձավ մայրաքաղաք", "2bfe73f9"], "d": ["Բուլղարական ցարության տրոհման գործընթացում Սև ծովի ափի Վառնան միացավ Դոբրոտիչի հիմնած Դոբրուջայի իշխանապետությանը և դարձվեց այս փոքր պետության մայրաքաղաքը։", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Ֆիլիպեից արևմուտք՝ Թաթարփազարջըղի և Իհթիմանի միացումը", "1664d0e1"], "d": ["1372 թվականին Ֆիլիպեի գրավումից հետո Մարիցայի հովտի վերին ծայրի Թաթարփազարջըղը և դեպի Սոֆիա բացվող լեռնանցքը պահող Իհթիմանը կապվեցին օսմանյան կառավարմանը։ Չիրմենի ճակատամարտից հետո վասալացած տեղական իշխանների ձեռքում գտնվող այս գիծը, անցնելով ուղղակի կառավարման, Ֆիլիպե-Սոֆիա ուղին դարձրեց անընդհատ։ Այս առաջխաղացումը տասներկու տարի անց Սոֆիայի նվաճմանը տանող ճանապարհի նախապատրաստությունն է։", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Սավջի բեյի ապստամբությունը — շահզադեի և բյուզանդական գահաժառանգի համատեղ խռովությունը", "75198c33"], "d": ["Մուրադ I-ի որդի Սավջի բեյը և բյուզանդական կայսր Հովհաննես V-ի որդի Անդրոնիկոս Պալեոլոգոսը 1373 թվականի մայիսի սկզբին Բուրսայում և Ստամբուլում միաժամանակ ապստամբեցին իրենց հայրերի դեմ։ Երկու հարստությունների գահաժառանգներին միավորող այս դաշինքը արագորեն ճնշվեց. Սավջի բեյը ձերբակալվեց, աչքերին շիկացած շյուղ քաշեցին և մահապատժի ենթարկեցին։ Օսմանյան ավանդության՝ ապստամբության համար տված 787 (1385) թվականը սխալ է. իրադարձությունը ընկնում է Բյուզանդիայի՝ օսմանյան վասալության մեջ մտնելուն անմիջապես հաջորդող տարիներին և ցույց է տալիս, թե որքան էին իրար խառնվել երկու արքունիքները։", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Ստրումայի և Մեստայի հովիտները՝ Քյոսթենդիլի, Պետրիչի, Նևրոկոփի և Դրամայի միացումը", "8c0980c4"], "d": ["Չիրմենի հաղթանակից հետո օսմանցիներին խարաջ վճարել սկսած սերբ և բուլղար տեղական իշխանների ձեռքում գտնվող Ստրումայի և Մեստայի հովիտները, սահմանապահ բեյերի առաջխաղացմամբ, անցան ուղղակի օսմանյան կառավարման։ Քյոսթենդիլի, Պետրիչի, Նևրոկոփի և Դրամայի միացմամբ բացվեց Մակեդոնիայի արևելյան կեսը, և Սալոնիկն ու Սերեզը մտան պաշարման օղակի մեջ։ Քարտեզում Ռումելիի հարավարևմտյան ընդարձակումը այս գործողությունների արդյունքն է։", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Էրեթնայի բեյլիքի ավարտը և Կադի Բուրհանեդդինի պետության հիմնադրումը", "60dcaf57"], "d": ["1335 թվականին իլխանական կուսակալությունից ծնված և Սեբաստիա ու Կեսարիա կենտրոնով Կենտրոնական Անատոլիան քառասունվեց տարի կառավարած Էրեթնա-օղլուները քայքայվեցին պալատական ներքին պայքարներից։ 1378 թվականի մայիսին վեզիր դարձած Կադի Բուրհանեդդինը, վերացնելով իր մրցակիցներ Քըլըջարսլանին և Հաջի Շադգելդիին, 1381 թվականի աշնանը հռչակեց իր սուլթանությունը, վերջ դրեց բեյլիքին և հիմնեց իր անունը կրող պետությունը։ Այսպիսով օսմանցիների արևելյան հարևանը փոխվեց. Սեբաստիա-Կեսարիա գիծը դրանից հետո տասնյոթ տարի մնալու էր Կադի Բուրհանեդդինի ձեռքում։", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Թեմուրը գրավեց Հերաթը՝ Քերթ հարստության ավարտը և Խորասանի անցումը Թեմուրյաններին", "15f6019e"], "d": ["Խորասանը 1380 թվականին բաժանված էր սարբադարների, քերթերի և մուզաֆարյանների միջև պայքարով։ Թեմուրը, որդի Միրան շահին շրջան ուղարկելուց հետո, ինքը շարժվեց Հերաթի վրա և որոշ ժամանակ պաշարելուց հետո քաղաքն ընդունեց Քերթի մելիք Ղիյաս ադ-Դին Փիր Ալիից։ Նրա մեկնելուց հետո ծագած ապստամբությունը Միրան շահը արյան մեջ ճնշեց, և վերջ դրվեց 1255 թվականից Հերաթում իշխող Քերթ հարստությանը։ Այս ամսաթվին ամբողջ Խորասանը՝ Մաշհադից մինչև Նիշապուր, անցավ թեմուրյան կառավարման։", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Առաջխաղացումը Մակեդոնիայի խորքը՝ Մանաստիրի և Օհրիդի նվաճումը", "63bb7838"], "d": ["Via Egnatia-ի վրա գտնվող Մանաստիրը և լճի ափի Օհրիդը Ալբանիայի ուղղությամբ ասպատակությունների ժամանակ անցան օսմանյան կառավարման։ Երկուսն էլ Ադրիատիկ ձգվող ճանապարհի բանալի կետերն էին. Օհրիդը նաև Բալկանների հնագույն ուղղափառ արքեպիսկոպոսության կենտրոնն էր։ TDV-ն նշում է, որ Օհրիդի նվաճման ամսաթվի վերաբերյալ հստակ տեղեկություն չկա, առաջ են քաշվել 787 (1385) թվականը և Կրալևիչ Մարկոյի մահից հետո եկող 797 (1395) թվականը. այստեղ հիմք է ընդունված 1385-ը։ Հետագա դարերում Մանաստիրը լինելու էր Ռումելիի ամենակարևոր ռազմական կենտրոններից մեկը։", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Սավրայի ճակատամարտը — Ալբանիայի դարպասների բացումը", "dda6671b"], "d": ["Բալշա հարստության դեմ նեղը ընկած ալբանացի բեյ Կառլո Թոփիայի օգնության կանչով օսմանյան ուժերը Սավրայի դաշտում ջախջախեցին Բալշա II-ի բանակը. Բալշան զոհվեց մարտադաշտում։ Տեղացի բեյի հրավերով մղված այս ճակատամարտը օսմանցիներին բերեց առաջին մշտական ազդեցությունը մինչև Ադրիատիկի ափերը ձգվող ալբանական հողերում։ Տարածաշրջանի բեյերի՝ իրար դեմ ելնելը հնարավորության վերածող այս քաղաքականությունը առաջիկա հարյուրամյակում լինելու էր բալկանյան նվաճումների անփոփոխ մեթոդը։", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Թեմուրի «եռամյա արշավանքը»՝ Ատրպատականի և Հյուսիսային Իրանի գրավումը", "2a98ec51"], "d": ["Խորասանի արշավանքների ընթացքում Իրանի ցրված վիճակը մոտիկից տեսած Թեմուրը 788 թվականին (1386) շարժվեց դեպի արևմուտք։ «Եռամյա արշավանք» անվանված 1386-1388 թվականների գործողություններում Մազանդարանի, Լուրիստանի և Վրաստանի վրայով անցնելով Ատրպատական՝ հասավ Ղարաբաղ. Թավրիզը, Արդաբիլը, Ուրմիան և Նախիջևանը անցան թեմուրյան կառավարման։ Հյուսիսային Իրանի և Ատրպատականի գրավումը, ինչպես ժամանակին Ջոչիի ուլուսի և Իլխանների միջև էր, սկիզբ դարձավ նաև Ոսկե Հորդայի հետ երկարատև հակամարտության։", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Ֆրենքյազըսըի ճակատամարտը և Կոնիայի պաշարումը — առաջին կարամանյան արշավանքը", "af4e5d77"], "d": ["Կարաման-օղլու Ալաեդդին Ալի բեյի դեմ, որը, թեև իր փեսան էր, անհանգստանում էր Արևմտյան Անատոլիայում օսմանյան ընդարձակումից, Մուրադ I-ն անձամբ ելավ արշավանքի. Ֆրենք Յազըսը կոչվող վայրում տեղի ունեցած ճակատամարտում մարզված և փորձառու օսմանյան բանակը հաղթեց կարամանյան ուժերին։ Այնուհետև պաշարվեց Կոնիայի ամրոցը, սակայն Ալաեդդին բեյին ներելով բեյլիքը լիովին չվերացվեց։ Այս արշավանքը օսմանցիների և Կարամանի միջև մեկ դար տևելիք և միայն 1468 թվականին վերջնական բռնակցմամբ ավարտվելիք երկար հաշվեհարդարի բացման արարն է։", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Մուշը Կարա-Կոյունլուների կառավարումից անցավ Լենկթեմուրի իշխանության տակ (789/1387)", "ed2e7a11"], "d": ["Մոնղոլական շրջանից հետո Կարա-Կոյունլուների կառավարման տակ անցած Մուշը 789 (1387) թ. անցավ Կարա-Կոյունլուների հողերին տիրացած Լենկթեմուրի կառավարման տակ։ Ատլասում Մուշն այդ տարում գրանցված է որպես Կարա-Կոյունլուներից Թեմուրյաններին անցած։", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Գելիբոլուի նավաշինարանի հիմնադրումը — օսմանյան նավատորմի ծնունդը", "47546241"], "d": ["Օսմանյան պետության առաջին կազմակերպված նավաշինարանը 1390 թվականին Յըլդըրըմ Բայազիդը հիմնեց Գելիբոլուում՝ Բյուզանդիայից մնացած նավաշինարանի տեղում։ Արևմտյան Անատոլիայի բեյլիքների ծովային ժառանգությունը ստանձնած օսմանցիները այսպիսով առաջին անգամ դարձան իրենց նավը իրենք կառուցող ծովային ուժ։ Դարդանելի նեղուցի բանալի կետում տեղադրված նավաշինարանը, Ստամբուլի պաշարումից մինչև Էգեյան արշավանքները, մեկուկես դար ծառայեց որպես օսմանյան նավատորմի գլխավոր հենակետ։", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Համիդ գավառը միացավ օսմանցիներին՝ Իսպարթա, Բուրդուր, Ուլուբորլու, Էյիրդիր", "e3da7de5"], "d": ["Կարաման-օղլու Ալաեդդին բեյի՝ Համիդ գավառի վրա հարձակման և ժողովրդի գանգատի առիթով արշավանքի ելած Յըլդըրըմ Բայազիդը գրավեց Համիդ-օղլուների մնացած բոլոր հողերը և դրանց կառավարումը տվեց իր որդի Իսա Չելեբիին։", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Մուզաֆարյան հարստության ավարտը՝ Շահ Մանսուրի պարտությունը Շիրազի մոտ", "5fd14eb8"], "d": ["1318 թվականից Յազդում, Ֆարսում, Սպահանում և Քերմանում իշխող Մուզաֆարյանների վերջին հզոր տիրակալ Շահ Մանսուրը, իր ազգականների հետ միավորվելով, շարժվեց Թեմուրի դեմ։ Շիրազի մոտ տեղի ունեցած ճակատամարտում, երբ նրա էմիրներից մեկն անցավ թշնամու կողմը, կորցրեց իր ուժերի մեծ մասը, պարտվեց և սպանվեց։ Թեմուրի՝ դրանից հետո նաև հարստության բոլոր անդամներին սպանել տալով ավարտվեց մուզաֆարյան իշխանությունը, և Ֆարսն ու Քերմանը միացան թեմուրյան կառավարմանը։", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Ամասիայի միացումը օսմանյան հողերին", "fe2860cf"], "d": ["Յըլդըրըմ Բայազիդի՝ Կենտրոնական Անատոլիայի գործողությունների ժամանակ պաշարված Ամասիայի էմիրը քաղաքը հանձնեց օսմանցիներին, և Բայազիդը 1393 թվականին մտավ քաղաք։ Սուլթանը դրա կառավարումը թողեց որդի Մեհմեդ Չելեբիին. որպես շահզադեական սանջակ՝ Ամասիան դրանից հետո դարձավ օսմանյան հարստության ամենակարևոր դաստիարակության օջախներից մեկը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Լադիկ (Ամասիա), Մերզիֆոն, Օսմանջըք, Չորում։ Այս ընտրությունը վճռորոշ լինելու էր հետագա միջգահակալության շրջանում. Չելեբի Մեհմեդը պետությունը վերամիավորելու պայքարը վարելու էր հենց այս ամասիական հենքից։", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Թեմուրը գրավեց Բաղդադը — Ջալայիրյանները փախան Անատոլիա", "4d5602b3"], "d": ["Թեմուրը երկարատև պաշարումից հետո գրավեց Բաղդադը. քաղաքի տերը՝ ջալայիրյան սուլթան Ահմեդը, փախչելով արևմուտք, ապաստան գտավ նախ մամլուքների, ապա օսմանյան պալատում։ Թեմուրի արևմտյան ընդարձակումը այսպիսով առաջին անգամ ուղղակի շփվեց օսմանյան ազդեցության գոտու հետ։ Երկու տիրակալների թշնամանքի առաջին օղակը սկսվում է այստեղից։", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Վառնայի գրավումը Սև ծովի ափին", "a84b2abf"], "d": ["Բուլղարական ցարության՝ Դանուբի և Սև ծովի միջև գտնվող հողերի սեղմման ժամանակ ափի ամենամեծ նավահանգիստ Վառնան անցավ օսմանյան կառավարման։ Նավահանգստի գրավումը բացեց Դոբրուջայի ուղղությամբ առաջխաղացման ճանապարհը և օսմանցիներին Սև ծովի արևմտյան ափին բերեց առաջին մեծ նավամատույցը։ Վառնան հիսունմեկ տարի անց դառնալու էր նաև 1444 թվականի հաղթանակի բեմը, երբ ոչնչացվելու էր խաչակիր բանակը։", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Նևշեհիրի և Ուրգյուփի շրջանը Կարամանօղուլներից անցավ օսմանցիների ձեռքը", "06ff59e8"], "d": ["Կարամանօղուլների դեմ Յըլդըրըմ Բայազիդի արշավանքների ընթացքում Նևշեհիրի (Մուշքարա) և Ուրգյուփի շրջանը 800/1398 թ. անցավ օսմանյան կառավարման տակ. 1402 թ. Անկարայի ճակատամարտից հետո Լենկթեմուրը տարածքը վերադարձրեց Կարամանօղուլներին։", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Կադի Բուրհանեդդինի պետության կործանումը", "b13391e3"], "d": ["Ակ-կոյունլուների տիրակալ Կարայուլուք Օսման բեյին գերի ընկած Կադի Բուրհանեդդինը, թեև առաջարկեց ազատ արձակվել Սեբաստիան հանձնելու դիմաց, քաղաքի բնակչությունը դիմադրեց, և սուլթանը մահապատժի ենթարկվեց պարիսպների առջև։ Սեբաստիայի ավագները, թեև գլուխ անցկացրին նրա որդի Ալաեդդին Ալի Չելեբիին, ակ-կոյունլուների ճնշման դիմաց օգնություն խնդրեցին Յըլդըրըմ Բայազիդից. Սուլեյման Չելեբիի հրամանատարությամբ օսմանյան ուժերը, հաղթելով Կարայուլուքին, տիրեցին քաղաքին։ Այսպիսով Կադի Բուրհանեդդինի պետությունն անցավ պատմության գիրկը, և Սեբաստիան, Թոքաթը, Նիկսարն ու Կեսարիան միացան օսմանյան հողերին։ Նույն ամսաթվին միացած այլ վայրեր՝ Քըրշեհիր, Չորում։", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Թեմուրի առճակատումը՝ փախստականների վերադարձը մերժվեց", "33790bc8"], "d": ["Թեմուրի ճնշման հետևանքով ջալայիրյան սուլթան Ահմեդը և կարա-կոյունլուների առաջնորդ Կարա Յուսուֆը ապաստանեցին օսմանյան հողերում. Թեմուրը պահանջեց վերադարձնել այս երկու փախստականներին, Յըլդըրըմ Բայազիդը մերժեց։ Դրա հետևանքով երկու տիրակալների միջև սկսվեց փոխադարձ ծանր վիրավորանքներ պարունակող նամակների փոխանակություն։ Պատերազմի գաղափարական հիմքը ստեղծվեց այս նամակագրությամբ՝ դեռ մեկ զինվոր էլ շարժման մեջ չմտած։", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Յըլդըրըմի հիվանդանոցը Բուրսայում — առաջին օսմանյան հիվանդանոցը", "5f0dc59a"], "d": ["Այն տարիներին, երբ Յըլդըրըմ Բայազիդը կառուցել էր տալիս Բուրսայի փառահեղ Ուլու մզկիթը, քաղաքին պարգևեց նաև հիվանդանոց (դարուշշիֆա). իմարեթից, մեդրեսեից, իջևանատնից և կամրջից բաղկացած բարեգործական լայն ծրագրի բժշկությանը հատկացված օղակն էր սա։ Պետության հիմնած առաջին հիվանդանոցը եղած այս կառույցը, ծառայելով նաև որպես բժիշկներ պատրաստող բժշկական դպրոց, որոշեց օսմանյան առողջապահական հաստատությունների օրինակը։ Անկարայի աղետից ընդամենը երկու տարի առաջ ավարտված այս գործը Յըլդըրըմի՝ Բուրսան կայսերական մայրաքաղաքի վերածելու պատկերացման վերջին օղակներից է։", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Թեմուրը հողին հավասարեցրեց Սեբաստիան", "f4d79de6"], "d": ["Ակ-կոյունլու Կարայուլուք Օսման բեյի և Երզնկայի էմիր Մութահարտենի առաջնորդությամբ Սեբաստիա շարժված Թեմուրը քաղաքը պաշարեց տասնութ օր և, ոչ մեկի արյունը չթափելու խոստումով այն ընդունելուց հետո, մեծ կոտորած արեց. պաշտպաններին լցրեց խրամատները և ողջ-ողջ ծածկել տվեց հողով։ Ավերվեցին քաղաքի կարևոր կառույցները՝ առաջին հերթին պարիսպները, և Սեբաստիան ժողովրդագրական առումով փլուզվեց։ Սա Անկարայի ճակատամարտից երկու տարի առաջ Թեմուրի՝ օսմանյան հողերին հասցրած առաջին մեծ հարվածն է։", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Յըլդըրըմ Բայազիդը հետ վերցրեց Երզնկան և Կամախը", "7047ca08"], "d": ["Թեմուրի՝ սիրիական արշավանքի ելնելը օգտագործելով՝ Յըլդըրըմ Բայազիդը Թեմուրին ենթակա Երզնկայի էմիր Մութահարտենի ձեռքից վերցրեց Երզնկան և Կամախը։ Թեև Սեբաստիայի ավերմանը չէր միջամտել, այս քայլը նշանակում էր ուղղակի մարտահրավեր նետել Թեմուրի ազդեցությանն Արևելյան Անատոլիայում։ Դրանից հետո երկու տիրակալների հարաբերությունները դարձան անուղղելի։", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Թեմուրի վերջնագիրը Թավրիզից — չորս պայման", "3e1ac50e"], "d": ["Թեմուրը Թավրիզից ուղարկած դեսպանի միջոցով չորս պայման ներկայացրեց. Կամախը վերադարձնել Մութահարտենին, Անատոլիայի բեյերից վերցրած հողերը վերադարձնել տերերին, որպես պատանդ ուղարկել օսմանյան շահզադե և ընդունել գլխանոցն ու գոտին որպես հպատակության նշան, հանձնել Կարա Յուսուֆին։ Բայազիդը դրանցից և ոչ մեկը չընդունեց. չնայած պետական գործիչների պնդումներին և Մութահարտենի միջնորդությանը՝ բանակցությունները տապալվեցին։ Թեմուրը վճռական էր Չինաստան արշավանքի ելնելուց առաջ վերջնականապես փակել անատոլիական հարցը։", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Սարուխանյանները վերականգնվեցին — Մանիսան դուրս եկավ օսմանյան կազմից", "ac747b05"], "d": ["Անկարայի ջախջախումից երեք շաբաթ անց Թեմուրի աջակցությամբ Օրհան բեյը գլուխ անցավ բեյլիքի, և Սարուխան գավառը կրկին անկախացավ։ Մանիսա կենտրոնով շրջանը 1390 թվականի օսմանյան բռնակցումից տասներկու տարի անց դուրս եկավ քարտեզից։ Սա Թեմուրի՝ բեյլիքները վերակենդանացնելու քաղաքականության առաջին կիրառություններից է, որի ամսաթիվը հստակ հայտնի է։", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Էմիր Սուլեյմանը պետական գանձարանով փախավ Ռումելի", "0a2b7363"], "d": ["Բուրսայի պետական գանձարանը, արխիվները, ընտանիքն ու եղբայրներին իր հետ վերցնելով՝ էմիր Սուլեյմանը Գեմլիքից նավով անցավ Գյուզելջեհիսար (Անատոլու Հիսարը), այնտեղից հասնելով Գելիբոլու՝ Էդիրնեում հռչակեց իր իշխանությունը։ Պետական արխիվի և գանձարանի տեղափոխումը Ռումելի սկիզբն է մեկ սերնդի ընթացքում օսմանյան ծանրության կենտրոնի՝ Բալկաններ տեղափոխվելու։ Քարտեզում Ռումելին այս ամսաթվից գծվում է էմիր Սուլեյմանի սեփական գույնով։", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Թեմուրը վերականգնեց Անատոլիայի բեյլիքները — թուրքական միասնությունը ցրվեց", "15187774"], "d": ["Անկարայի հաղթանակից հետո Թեմուրը իր մոտ գտնվող բեյերին վերադարձրեց իրենց նախկին հողերը։ Կարաման-օղլու Մեհմեդ և Ալի բեյերին տրվեցին Կարաման գավառը՝ Կեսարիայով, Քըրշեհիրով, Սիվրիհիսարով և Բեյշեհիրով. Գերմիյան-օղլու Յաքուբ II բեյին՝ Քյոթահյան և Գերմիյան գավառը. Ջանդար-օղլու Իսֆենդիյար բեյին՝ Կաստամոնու-Սինոպ գծից բացի Չանքըրըն և Քալեջիքը։ Այդըն, Մենթեշե և Թեքե գավառները ևս վերադարձան իրենց նախկին հարստություններին։ Յըլդըրըմ Բայազիդի տասը տարում ստեղծած անատոլիական թուրքական միասնությունը ցրվեց մեկ ամառվա ընթացքում. քարտեզում այս բեյլիքները կրկին հայտնվում են իրենց գույներով։ Նույն գործընթացում ձեռքից ձեռք անցած այլ բնակավայրեր՝ Աքսարայ, Դենիզլի, Էրեղլի (Կոնիա), Էրմենեք, Ըլգըն, Քարափընար, Կեսարիա, Կոնիա, Քըրշեհիր, Քյոթահյա, Սիվրիհիսար, Սյոքե։", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Թեմուրը Իզմիրը վերցրեց Սուրբ Հովհաննեսի ասպետներից", "66dd1dd4"], "d": ["Քյոթահյայի, Դենիզլիի, Այդընի, Այասուլուքի և Տիրեի վրայով դեպի արևմուտք իջած Թեմուրը պաշարեց և գրավեց 1344 թվականից քրիստոնյաների ձեռքում գտնվող ծովափնյա Իզմիրը։ Այս ամրոցը, որը Յըլդըրըմ Բայազիդը տարիներով չէր կարողացել գրավել, կարճ ժամանակում գրաված Թեմուրը, շրջակա ամրոցներն ևս գրավելուց հետո, Այդըն գավառը թողեց նախկին տերերին և վերադարձավ արևելք։ Դրանից հետո քաղաքն անցավ Այդըն-օղլու Ջյունեյդ բեյի կառավարմանը։", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Իսա Չելեբին գրավեց Բուրսան — ծնվեց անատոլիական բաժինը", "955128c1"], "d": ["Անկարայի ջախջախումից հետո Կարեսիի կողմերը քաշված Իսա Չելեբին, երբ Թեմուրը Իզմիրում էր, գրավեց Բուրսան։ Թեմուրի զինվորների թալանած և այրած նախկին մայրաքաղաքում նա հռչակեց իր իշխանությունը և իր անունով դրամ հատել տվեց. 1403 թվականի հունվարին Անատոլիայում ճանաչվում էր որպես «թուրքերի տիրակալ»։ Քարտեզում Մարմարայի ասիական ափի երկայնքով ձգվող այս բաժինը երևում է Իսա Չելեբիի սեփական գույնով։", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Թեմուրի հեռանալը Անատոլիայից", "93a98839"], "d": ["Ստանալով լուրը, որ Յըլդըրըմ Բայազիդը մահացել է Աքշեհիրում, Թեմուրը, համարելով իր անատոլիական գործն ավարտված, շարժվեց դեպի արևելք։ Նրա ետևում մնացին իրեն հավատարմություն հայտնած բեյլիքները և միմյանց դեմ ելած օսմանյան շահզադեները. Սեբաստիայի նման որոշ քաղաքներ թողնվեցին Թեմուրին ենթակա էմիրների՝ Մեզիդ բեյի նմանների ձեռքում։ Թեմուրը այլևս չվերադարձավ Անատոլիա, սակայն նրա ստեղծած այս մասնատված կարգը տևեց տասը տարի։", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Էմիր Սուլեյմանն անցավ Անատոլիա՝ Բուրսան անցավ նրա ձեռքը", "9b27aa5f"], "d": ["Իսա Չելեբիի պարտության մասին լսելով՝ էմիր Սուլեյմանը Չանդարլը Ալի փաշայի հետ հզոր բանակով անցավ Անատոլիա և գրավեց Բուրսան. 1404 թվականի մարտի գրառումները ցույց են տալիս, որ Կարադենիզ Էրեղլին ևս նրա կառավարման տակ էր։ Կարճ ժամանակում թե՛ Ռումելիին, թե՛ Անատոլիայի մեծ մասին տիրած Սուլեյմանի դեմ Չելեբի Մեհմեդը չկարողացավ դիմադրել։ Նույն գործընթացում Չելեբի Մեհմեդից էմիր Սուլեյմանին անցած այլ բնակավայրեր՝ Աքյազը, Անատոլու Հիսարը, Աբսու (Հիփսու), Ադրանոս (Օրհանելի), Աքհիսար (Փամուքովա), Արմութլու, Այդոս ամրոց, Այվալըք, Բալըքեսիր, Բեհրամքալե (Ասոս), Բերգամա, Բեյքոզ, Բիղա։ Քարտեզում այս ամսաթվից մինչև Չելեբի Մեհմեդի կողմից Բուրսայի հետգրավումը (1410) երկու ափերը երևում են մեկ գույնով՝ էմիր Սուլեյմանի բաժնում։", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Ենիշեհիրի դաշտի ճակատամարտը — Չելեբի Մեհմեդը քաշվեց Ամասիա", "f1568288"], "d": ["Բուրսան և Անկարան կորցրած Չելեբի Մեհմեդը Ենիշեհիրի դաշտում պարտվելով էմիր Սուլեյմանին՝ կորցրեց Արևմտյան Անատոլիայի բոլոր ձեռքբերումները և քաշվեց Թոքաթ-Ամասիա հենակետ։ Այս պարտությունից հետո նա, խուսափելով ուղղակի ընդհարումից, ձեռնամուխ եղավ Անատոլիայի խորքերում իր իշխանության ամրապնդմանը։ Այսպես սկսվեց միջգահակալության ամենաերկար անշշուկ փուլը։", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Էմիր Սուլեյմանը Անկարան վերցրեց Չելեբի Մեհմեդից", "d6a2acd6"], "d": ["Թեմուրի՝ Անատոլիայից հեռանալուց հետո Չելեբի Մեհմեդի ձեռքում մնացած Անկարան 1406 թվականին պաշարեց էմիր Սուլեյմանը։ Ամրոցի պահապան Յաքուբ բեյը որոշ ժամանակ դիմացավ, սակայն մեծ վեզիր Չանդարլը Ալի փաշայի խորամանկությամբ ամրոցը հանձնեց Սուլեյմանին։ Դրա հետևանքով Չելեբի Մեհմեդը, համաձայնության գալով Կարաման-օղլու Մեհմեդ բեյի հետ, շարժման մեջ մտավ Սուլեյմանի դեմ։", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Չելեբի Մեհմեդը Սեբաստիան հետ վերցրեց Թեմուրյան Մեզիդ բեյից", "90079b0c"], "d": ["Թեմուրի արշավանքից հետո Սեբաստիայի կառավարումը թողնվել էր Թեմուրին ենթակա Մեզիդ բեյին։ Ամասիայում գտնվող Չելեբի Մեհմեդը իր հրամանատար Բայազիդ փաշային ուղարկեց քաղաքը գրավելու, և կատաղի դիմադրությունից հետո Սեբաստիան երկրորդ անգամ անցավ օսմանյան հարստության ձեռքը։ Այսպիսով Մեհմեդի բաժինը Անկարայի ճակատամարտից վեց տարի անց արևելքում հասավ իր նախկին սահմանին։", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Արթուքյան հարստության ավարտը՝ Մարդինի հանձնումը կարա-կոյունլուներին", "15b06f33"], "d": ["1106 թվականից Մարդինում իշխող և հարստության ամենաերկարակյաց ճյուղը եղած Արթուքյանները չկարողացան դիմանալ ակ-կոյունլուների ճնշմանը։ Հասկանալով, որ չի կարող պաշտպանել քաղաքը, մելիք Ահմեդը համաձայնության գալով կարա-կոյունլուների տիրակալ Կարա Յուսուֆի հետ՝ Մարդինը հանձնեց նրան։ Այսպիսով ավարտվեց երեք դարն անց արթուքյան տիրապետությունը. Մարդինը և նրա շրջակայքը, մինչև մեկ դար անց օսմանցիներին անցնելը, դարձան կարա-կոյունլու-ակ-կոյունլու պայքարի բեմ։", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Յամբոլի ճակատամարտը — Մուսա Չելեբին մտավ Էդիրնե", "8f978408"], "d": ["Վալախիայի վրայով Ռումելի անցած Մուսա Չելեբին վալախական և սերբական աջակցությամբ Յամբոլում ջախջախեց էմիր Սուլեյմանի ուժերը և մտավ Էդիրնե։ Միջգահակալության շրջանում Ռումելին առաջին անգամ դուրս եկավ էմիր Սուլեյմանի ձեռքից։ Սակայն նրա իշխանությունը մշտական չեղավ. չորս ամիս անց Կոսմիդիոնում պարտվելով՝ նա քաշվելու էր Բալկանների խորքերը։", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Ինջեղիզի ճակատամարտը — Չելեբի Մեհմեդի առաջին ռումելիական պարտությունը", "3c35cd43"], "d": ["Բյուզանդիայի նավերով Ռումելի անցած Չելեբի Մեհմեդը Ինջեղիզում կռվի բռնվեց Մուսա Չելեբիի հետ. Մուսան իր հրամանատարության տակ գտնվող յոթ հազար ենիչերիներով պարտության մատնեց Մեհմեդին, և Մեհմեդը ստիպված եղավ վերադառնալ Անատոլիա։ Այս պարտությունը Մեհմեդին ուղղեց ուղղակի պատերազմի փոխարեն Ռումելիի սահմանապահ բեյերին և Սերբական դեսպոտությունը իր կողմը գրավելու ռազմավարության։ Ինը ամիս հետո Չամուրլուի հաղթանակի հիմքը նախապատրաստվեց այս դիվանագիտությամբ։", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Կոնիայի պաշարումը և պայմանագիրը Կարամանյանների հետ — հետ վերցվեցին Համիդ և Սայիդ գավառները, Բեյշեհիրը, Սեյդիշեհիրը և Աքշեհիրը", "0996257e"], "d": ["Միջգահակալության շրջանում օսմանյան հողերի վրա հարձակված և Բուրսան պաշարած ու այրած Կարամանյանների դեմ Չելեբի Մեհմեդը կազմակերպեց մեծ արշավանք և 818 թվականի Մուհառամին պաշարեց Կոնիան։ Կարաման-օղլու Մեհմեդ II բեյը ստիպված եղավ խաղաղություն խնդրել. պայմանագրի արդյունքում Համիդ գավառը (Իսպարթայի շրջանը) և Սայիդ գավառը կրկին միացան օսմանյան հողերին, վերադարձվեցին նաև Բեյշեհիրը, Սեյդիշեհիրը և Աքշեհիրը. օսմանցիներին վերադարձավ նաև Սիվրիհիսարը, որը Թեմուրը 1402 թվականին տվել էր Կարամանյաններին։ Այս արշավանքը, որով սկսեց կարկատվել Անկարայի ճակատամարտով ցրված անատոլիական միասնությունը, Չելեբի Մեհմեդին «երկրորդ հիմնադիր» համարելու կոնկրետ հիմքերից է։", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Իզմիրի գրավումը Այդըն-օղլու Ջյունեյդ բեյից", "2377ca51"], "d": ["Միջգահակալության ողջ ընթացքում շահզադեների միջև անընդհատ կողմ փոխող Այդըն-օղլու Ջյունեյդ բեյի կենտրոն Իզմիրը տասնօրյա պաշարումից հետո գրավեց Չելեբի Մեհմեդը. Ջյունեյդը ներում ստացավ և ուղարկվեց Նիկոպոլիսի սանջակի բեյ։ 1402 թվականին Թեմուրի կողմից Այդըն-օղլուներին վերադարձված քաղաքը այսպիսով տասներեք տարի անց վերադարձավ օսմանցիներին։ Ջյունեյդը 1422 թվականին կրկին գրավելու էր քաղաքը, և հարցը 1424-1426 թվականներին միայն Մուրադ II-ը փակելու էր։", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Թորլաք Քեմալի մահապատիժը — Սարուխանը վերջնականապես օսմանյան է", "8a09dbf1"], "d": ["Շեյխ Բեդրեդդինի շարժման արևմտաանատոլիական թևը ղեկավարող Թորլաք Քեմալը Մանիսայի շրջանում պարտության մատնվեց և մահապատժի ենթարկվեց։ Այս ամսաթվից հետո Սարուխանի շրջանը վերջնականապես անցավ օսմանյան վերահսկողության, և 1402 թվականին Թեմուրի վերակենդանացրած բեյլիքն անցավ պատմության գիրկը։ Այսպիսով մաքրվեցին միջգահակալության շրջանի վերջին քաղաքական մնացորդները Արևմտյան Անատոլիայում։", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Վլյորայի, Բերաթի և Կանինայի նվաճումը", "1e1949b8"], "d": ["Օսմանցիները 1417 թվականին Ադրիատիկի ափի Վլյորան, երկրի ներքին մասի Բերաթ քաղաքի և Կանինա ամրոցի հետ միասին, վերցրին իրենց տիրապետության տակ։ Մեկ տարի անց Վենետիկի՝ քաղաքը հետ վերցնելու փորձը ձախողվեց, և այստեղ ստեղծվելով սանջակային կառույց՝ օսմանյան իշխանությունը դարձավ մշտական։ Վլյորայի գրավումը առաջին անգամ օսմանցիներին դարձրեց Ադրիատիկում ուղղակի նավահանգստի տեր՝ Իտալիայի դեմ ձեռք բերելով ծովից այն կողմ ցատկատախտակ։", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Կենտրոնական Անատոլիայի հետգրավումը՝ Կեսարիա և Քըրշեհիր", "204eacb3"], "d": ["Միջգահակալության շրջանում Կարամանյանների ձեռքն անցած կենտրոնաանատոլիական քաղաքները Չելեբի Մեհմեդի՝ պետությունը վերականգնելու արշավանքների ընթացքում վերադարձան օսմանյան կառավարման։ Կեսարիայի և Քըրշեհիրի միացմամբ Անկարայի ճակատամարտում կորցրած Կըզըլըրմաքի ավազանը մեծ մասամբ հետ վերցվեց։ Այս առաջխաղացումը չորս տարի առաջ Կոնիայի պաշարմամբ սկսված դեպի արևելք շարժվելու քաղաքականության շարունակությունն է։", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Մամլուքները Կեսարիան տվեցին Դուլկադիրյան Նասրեդդին Մուհամմեդին", "aad4b00c"], "d": ["Կարաման-օղլու Մեհմեդ բեյի դեմ արշավանքի ելած մամլուքների բանակը գրավեց Կեսարիան. մամլուք հրամանատարը, քաղաքն ու նրա շրջակայքը թողնելով Դուլկադիրյան Նասրեդդին Մուհամմեդին, վերադարձավ իր երկիրը։", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Մեհմեդ I-ի մահը և Մուրադ II-ի գահակալումը", "98acac77"], "d": ["Գահակալական կռիվների շրջանին (Ֆեթրեթ) վերջ դրած և օսմանյան երկիրը կրկին մեկ ձեռքում միավորած Մեհմեդ I-ը մահացավ 1421 թ. հունիսի 25-ին Ադրիանապոլսում (Էդիրնե), և նրա որդի Մուրադը գահ բարձրացավ Բուրսայում։ Նրա մահից առաջ Բյուզանդիայի հետ կնքված պայմանավորվածության համաձայն՝ նրա կրտսեր որդիները պատանդ պետք է ուղարկվեին կայսեր մոտ, իսկ կայսրը ազատ չպետք է արձակեր իր ձեռքում պահվող գահի հավակնորդ Մուստաֆա Չելեբիին. Մուրադ II-ը հրաժարվեց իր եղբայրներին ուղարկել կայսրին։", "c8093fa8"]}
});
